SELECT 'moj-all-verified-judgments-review-002-chunk-186' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"fb28b985-ad93-5c71-b896-84373e88114a","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -شرط موافقة املدعي على املشتري اجلار- نقض الشرط وإمتام البيع دون موافقة املدعي -الدعوى باملطالبة بالشفعة تقام على من بيده العن -عدم وجود مرفق مشترك بن املدعي واجلار -صرف النظر عن الدعوى .","document_number":"3460931","case_number":"33342513","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف بفتح هذه اجللسة","circuit":"الدائرة بصرف النظر عن دعوى املدعي جتاه املدعى عليه وأخلت","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"شفعة -شفعة جار -شرط موافقة املدعي على املشتري اجلار- نقض الشرط وإمتام البيع دون موافقة املدعي -الدعوى باملطالبة بالشفعة تقام على من بيده العن -عدم وجود مرفق مشترك بن املدعي واجلار -صرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/11 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3460931 :‬‬\n                         ‫َر ْق ُم الدعوى‪33342513 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34214373‬تاريخه‪1434/5/18:‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬شــرط موافقــة املدعــي علــى املشــتري اجلــار‪-‬‬\n      ‫نقــض الشــرط وإمتــام البيــع دون موافقــة املدعــي‪ -‬الدعــوى باملطالبــة‬\n      ‫بالشــفعة تقــام علــى مــن بيــده العــن‪ -‬عــدم وجــود مرفــق مشــترك بــن‬\n                                ‫املدعــي واجلــار‪ -‬صــرف النظــر عــن الدعــوى ‪.‬‬\n\n\n\n      ‫حديــث جابــر ‪ -‬رضــي اهلل عنــه ‪»:-‬أن النبــي صلــى اهلل عليــه وســلم قضى‬\n      ‫بالشــفعة يف كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق‬\n                                                ‫فــا شــفعة» أخرجــه البخــاري‪.‬‬\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صديقــه وملــا علــم بأنــه‬\n      ‫يبحــث عــن منــزل وأن جــاره عــرض منزلــه للبيــع فشــفع املدعــي لــه لــدى‬\n      ‫البائــع فحســم خمســن ألــف ريــال ألجــل شــفاعته كمــا أعفــاه عــن‬\n      ‫أجــرة الســعي املســتحقة لــه بشــرط أال يبيــع املنــزل علــى أحــد إال بإذنــه‬\n      ‫وموافقتــه ليختــار اجلــار املناســب وأنــه وافــق علــى هــذا الشــرط‪ -‬حيــث‬\n      ‫إن املدعــى عليــه لــم يلتــزم بهــذا الشــرط فقــد أقــام عليــه دعــوى بطلــب‬\n      ‫الشــفعة يف العقــار وإلزامــه بدفــع مــا حســمه البائــع ألجــل شــفاعته لــه‬\n      ‫خمســن ألــف ريــال ‪ -‬أقــر املدعــى عليــه بشــراء املنــزل وأنكــر أنــه‬\n      ‫اشــتراه بــدون ثمــن املثــل وطلــب رد دعــوى املدعــي لكونــه غيــر ذي صفــة‬\n‫‪359‬‬\n\f‫فليــس مالــكا للمنــزل وأن املدعــي اســتلم أجــرة الســعي بحكــم مــن‬\n‫احملكمــة اجلزائيــة ‪ -‬أقــر املدعــي بصــدور حكــم لــه بأجــرة الســعي‬\n‫واســتالمه للمبلــغ ‪ -‬قــرر املدعــي بــأن بائــع املنــزل لــم يوكلــه يف املطالبــة‬\n‫باخلمســن ألــف ريــال ولــم يتنــازل لــه بهــا ولــم يشــترط البائــع علــى‬\n‫املدعــى عليــه ذلــك ‪ -‬عليــه وملــا قــرره املدعــي أن مبلــغ اخلمســن ألــف‬\n‫ريــال التــي تنــازل عنهــا بائــع املنــزل للمدعــى عليــه لــم تكــن مشــروطة‬\n‫علــى املدعــى عليــه أال يبيعهــا علــى مــن ال يرتضــي املدعــي جيرتــه وأن‬\n‫بائــع املنــزل لــم يوكلــه يف مطالبــة املدعــى عليــه باملبلــغ املذكــور وإقــرار‬\n‫املدعــي أن املنــزل محــل النــزاع يف حــي ســكني ال يوجــد بينهمــا حــق‬\n‫مشــترك مــن طريــق خــاص ونحــوه‪ ،‬وحلديــث جابــر رضــي اهلل عنــه عنــد‬\n‫البخــاري أن النبــي صلــى اهلل عليــه وســلم «قضــى بالشــفعة يف كل مــا‬\n‫لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة» كمــا أن‬\n‫املطالبــة بالشــفعة تقــام علــى مــن بيــده العــن جلميــع ذلــك فقــد حكمــت‬\n‫الدائــرة بصــرف النظــر عــن دعــوى املدعــي جتــاه املدعــى عليــه وأخلــت‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعوى‪-‬بعــرض ذلــك علــى الطرفــن قــرر‬\n‫املدعــى عليــه القناعــة وأمــا املدعــي فقــرر عــدم القناعــة وطلــب رفعــه‬\n‫حملكمــة االســتئناف بالئحــة اعتراضيــة ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n\n                                                                                        ‫‪360‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....................‬املــازم القضائــي لــدى‬\n      ‫فضيلــة الشــيخ ‪ .........................‬القاضــي باحملكمــة العامــة بالريــاض‬\n      ‫واملكلــف بفتــح هــذه اجللســة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪33342513‬‬\n      ‫وتاريــخ ‪1433/05/17‬ه املقيــدة باحملكمــة برقــم ‪33933734‬‬\n      ‫وتاريــخ ‪1433/05/17‬ه ففــي يــوم الســبت املوافق‪1433/08/17‬ه ـ‬\n      ‫حضــر املدعــي ‪ ......................‬ســعودي اجلنســية ســجل مدنــي رقــم‬\n      ‫………………‪ ..‬ولــم يحضــر املدعــى عليــه وال وكيــل عنــه ووردنــا‬\n      ‫محضــر التبليــغ رقــم ‪ 33933734‬يف ‪1433/5/24‬ه ـ املتضمــن أنــه مت‬\n      ‫تبليــغ املدعــى عليــه لشــخصه وتســلم صــورة مــن ورقــة التبليــغ مبوعــد‬\n      ‫اجللســة ولكــون املدعــى عليــه تبلــغ لشــخصه فقــد قــررت ســماع الدعوى‬\n      ‫غيابيــا وبســؤال املدعــي عــن دعــواه قــدم مذكــرة نصهــا مــا يلــي دعــواي‬\n      ‫ضــد املدعــى عليــه بســبب نقضــه للشــرط الــذي مت بيننــا بعــدم بيــع املنــزل‬\n      ‫الــذي تشــفعت لــه بشــرائه لكــي يجاورنــي وذلــك ألي شــخص إال بعــد‬\n      ‫موافقتــي علــى املشــتري وأطلــب حقــي يف املبلــغ الــذي حســم مــن البيعــة‬\n      ‫الســابقة ألجلــي وقــدره خمســون ألــف ريــال لكــي تتــم البيعــة للمدعــو‬\n      ‫‪ ...‬وذلــك مــن املالــك الســابق املدعــو ‪ ...............‬حيــث غــدر بــي وعــدم‬\n      ‫وفائــه للشــرط والوعــد الــذي مت بيننــا بعــدم البيــع إال بعــد مشــاورتي يف‬\n      ‫املشــتري والرجــوع لــي باختيــار مــن يجاورنــي مثلمــا فعلــت عندمــا أراد‬\n      ‫هــو شــراء املنــزل الــذي يجاورنــي وتتمثــل الواقعــة أنــه يف شــهر جمــادي‬\n      ‫اآلخــرة مــن عــام ‪1432‬ه ـ طلــب منــي املذكــور التوســط يف شــراء املنــزل‬\n\n‫‪361‬‬\n\f‫الــذي يجاورنــي وطلــب منــي مســاعدته يف التشــفع لــدى مالــك املنــزل‬\n‫الــذي يجاورنــي مــن أجــل بيعــه للمدعــو ‪ ...‬وبالفعــل حــدث ذلــك ووافــق‬\n‫صاحــب املنــزل علــى بيعــه للمذكــور مببلــغ مليــون ومائتــا ألــف ريــال‬\n‫‪ 1.200.000‬ريــال مــع العلــم بــأن صاحــب املنــزل املدعــو ‪...................‬‬\n‫ـاء علــى تشــفعي لــه ألن الــذي يرغــب يف شــراء‬     ‫تقديــرا حلســن اجلــوار وبنـ ً‬\n‫املنــزل املدعــو ‪ ............‬صديــق لــي قــام بخصــم خمســن ألــف ريــال مــن‬\n‫ســعر ســوم منزلــه حيــث كان مســيوم مببلــغ مليــون ومائتــان وخمســون‬\n‫ألــف ريــال ‪ 1.250.000‬ريــال ومتــت البيعــة وكان نصيبــي مــن الســعي‬\n‫عشــرة آالف ريــال وقــد طلــب منــي املدعــو ‪ ..............‬التنــازل عــن ســعيي‬\n‫تقديــرا لــه وبالفعــل حــدث ذلــك مــن أجــل مســاعدته علــى الــزواج وإعانــة‬\n‫لــه علــى الســكن وتقديــرا للصداقــة التــي كانــت بيننــا ولكــن بشــرط‬\n‫أن يتــزوج ويســكن هــو بجــواري وإذا خالــف ذلــك يكــون ســعيي قائــم‬\n‫ويقدمــه لــي إذا رغــب البيــع وقــد وافــق علــى ذلــك واشــترطنا أن ال تتــم‬\n‫البيعــة إال بعــد مشــاورتي يف املشــتري الــذي يرغــب الســكن بجــواري‬\n‫حيــث كنــت أرغــب أن يكــون مــن منطقــة الريــاض ووافــق علــى ذلــك‬\n‫وبعــد مضــي ســتة أشــهر قــام املذكــور بعــرض املنــزل للبيــع بســبب أنــه‬\n‫لــم يكتــب لــه الــزواج حســب ادعائــه وقــد أخبرنــي بذلــك وتعهــد لــي بــأن‬\n‫ال تتــم البيعــة إال بعــد موافقتــي ومشــاروتي يف الشــخص الــذي يرغــب‬\n‫شــراءه حســب الشــرط املذكــور أعــاه وأن ســعيي محفــوظ وقــدره‬\n‫عشــرة آالف ريــال ولكــن املذكــور خــان عهــده ولــم يــويف حيــث قــام‬\n‫ببيــع املنــزل المــرأة فلســطينية حتمــل جنســية ســعودية ومتزوجــه مــن‬\n‫فلســطيني مببلــغ وقــدره مليــون وأربعمائــة وخمســون ألــف ريــال بــدون‬\n‫مشــاروتي يف املشــتري حســب االتفــاق الــذي مت بيننــا وتفاجــأت بذلــك‬\n\n\n                                                                                         ‫‪362‬‬\n\f      ‫وقمــت باالتصــال عليــه هاتفيــا حيــث أنكــر تعهــده ووعــده وكذلــك‬\n      ‫رفــض تســليمي الســعي املشــترط بيننــا وقــدره عشــرة آالف ريــال فضيلــة‬\n      ‫الشــيخ أطالــب مبــا يلــي ‪ -1‬حــق الشــفعة يف مــن يســكن بجــواري حيــث‬\n      ‫غــدر بــي املدعــو ‪ ...........‬ولــم يبلغنــي مبــن يرغــب يف شــراء املنــزل حيــث‬\n      ‫باعــه علــى امــرأة فلســطينية حتمــل جنســية ســعودية بالرغــم مــن تعهــده‬\n      ‫بعــدم بيعــه إال بعــد الرجــوع لــي وحيــث أن الشــفعة وجــدت إلعطــاء اجلــار‬\n      ‫احلــق يف شــراء منــزل جــاره الختيــار مــن يجــاوره حيــث تضــررت وكنــت‬\n      ‫أرغــب أن يجاورنــي شــخص مــن أبنــاء وطنــي لكي اســتأمن على عائلتي‬\n      ‫يف حالة عدم تواجدي يف املنزل ‪ -2‬املبلغ الذي مت حسمه من قبل جاري‬\n      ‫ســابقا املدعــو ‪ .............‬حيــث حســم مبلــغ وقــدره خمســن ألــف ريــال مــن‬\n      ‫مبلــغ ســوم املنــزل حيــث كان مســيوم مببلــغ مليــون ومائتــان وخمســون‬\n      ‫ألــف ريــال ولكــن تقديــرا منــه جليرتــي قــام بحســم املبلــغ املذكــور‬\n      ‫أعــاه تقديــرا لــي ولشــفاعتي لديــه مــن أجــل بيعــه للمدعــو‪..................‬‬\n      ‫فضيلــة الشــيخ آمــل إلزامــه بدفــع حقوقــي املذكــورة أعــاه واهلل عــز‬\n      ‫وجــل مطلــع علــى مــا حــدث بيننــا هــذه دعــواي ‪ .‬ا‪.‬ه ـ وجــرى رفــع اجللســة‬\n      ‫لتبليــغ املدعــى عليــه ويف جلســة أخــرى لــدي أنــا ‪ ......................‬القاضــي‬\n      ‫باحملكمــة العامــة بالريــاض حضــر املدعــي أصالــة ‪ ...................‬وحضــر‬\n      ‫حلضــوره ‪......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...................‬الوكيــل الشــرعي عــن ‪ .....................‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة عــدل محافظــة الدرعيــة برقــم ‪ 33355108‬يف‬\n      ‫‪1433/7/26‬ه ـ التــي تخولــه مراجعــة احملاكــم الشــرعية وكتابــة‬\n      ‫العــدل والبلديــة وبتــاوة الدعــوى علــى املدعــى عليــه وكالــة قــال ســبق‬\n      ‫وأن مت إرســال إجابــة موكلــي لفضيلتكــم مــن قبــل فضيلــة رئيــس‬\n\n\n‫‪363‬‬\n\f‫هــذه احملكمــة واملقيــدة برقــم ‪ 34/471300‬يف ‪1434/2/25‬ه ـ أطلــب‬\n‫مــن فضيلتكــم ضبطهــا وباالطــاع عليهــا وجدتهــا موقعــة مــن املدعــى‬\n‫عليــه أصالــة ونصهــا اآلتــي أطلــب مــن اهلل ثــم فضيلتكــم احلكــم بــرد‬\n‫الدعــوى املقامــة ضــدي مــن املدعــو ‪ ...........................‬بخصــوص دفــع‬\n‫فــرق القيمــة للفيــا املباعــة علـ ّـي مــن قبــل املدعــو ‪ .....................‬مببلــغ‬\n‫وقــدره خمســون ألــف ريــال حســب زعمــه وذلــك لألســباب اآلتيــة ‪/1‬‬\n‫الدعــوى مقامــة مــن غيــر ذي صفــة فاملدعــي ال ميلــك الفيــا وليــس‬\n‫وكيــا عــن صاحبهــا ‪ /2‬أنــا اشــتريت الفيــا بســعرها وقــت البيــع ومــا‬\n‫زعمــه املدعــي مــن أن صاحــب الفيــا باعنــي بأقــل مــن القيمــة بخمســن‬\n‫ألــف ريــال فعــار عــن الصحــة متامــا ‪ /3‬املدعــي رفــع علـ ّـي دعــوى مطالبــة‬\n‫بالســعي أمــام احملكمــة اجلزئيــة بالريــاض وانتهــت مبوجــب احلكــم‬\n‫الصــادر رقــم ‪ 33243920‬وتاريــخ ‪1433/5/12‬ه ـ املرفــق صورتــه لــدى‬\n‫القاضــي يف احملكمــة اجلزئيــة بالريــاض فضيلــة الشــيخ ‪...................‬‬\n‫املتضمــن اســتالمه لقيمــة مطالبتــه بالســعي ولــم يشــر يف دعــواه إلــى أنــه‬\n‫حصــل لــي علــى تخفيــض مــن قيمــة الفيــا ممــا يــدل علــى بطــان دعــواه‬\n‫‪ /4‬أنــا ضابــط مبــرور الريــاض وعملــي حســاس وســبب لــي مضايقــة يف‬\n‫عملــي وإربــاك باجلهــاز الــذي أعمــل بــه بســبب هــذه الدعــوى الباطلــة‬\n‫لــذا أطلــب مــن اهلل ثــم مــن فضيلتكــم إدخــال املدعــي العــام يف هــذه‬\n‫القضيــة لكــف شــره عنــي وعــن بقيــة النــاس وإذا لــم يــردع فســيتمادى‬\n‫يف غيــه كمــا أطلــب احلكــم بصــرف النظــر عــن دعــواه لعــدم إقامتهــا‬\n‫مــن ذي صفــة وأخــذ التعهــد اخلطــي الشــديد بعــدم مالحقتــي مســتقبال‬\n‫كمــا احتفــظ بحقــي يف طلــب تعويضــي عــن األضــرار املاديــة واملعنويــة‬\n‫التــي ســببها لــي املدعــي بســبب هــذه القضيــة الباطلــة هكــذا أجــاب‬\n\n\n                                                                                             ‫‪364‬‬\n\f      ‫وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى عليــه مــن اســتالمي‬\n      ‫ملبلــغ الســعي املذكــور فهــو صحيــح ومــا عــداه فغيــر صحيــح والصحيــح‬\n      ‫مــا ذكــرت وبســؤال املدعــي هــل مالــك الفيــا الذي اشــترى منــه املدعى‬\n      ‫عليــه أصالــة قــد وكلــه يف املطالبــة مببلــغ اخلمســن ألف املدعــى بها قال‬\n      ‫لــم يوكلنــي املالــك بذلــك إال أن هــذا املبلــغ حســم للمدعــى عليــه بســبب‬\n      ‫وســاطتي كمــا ســألت املدعــي هــل تنــازل املالــك للمدعــى عليــه عــن‬\n      ‫اخلمســن ألــف ريــال كان مشــروطا بالتــزام املشــتري املدعــى عليــه يف‬\n      ‫هــذه الدعــوى بــأن ال يســكن يف الفيــا وال يبيعهــا علــى مــن ال يرتضــي‬\n      ‫جيرتــه أجــاب املدعــي قائــا لــم يشــترط هــذا الشــرط علــى املدعــى عليــه‬\n      ‫إال يف العشــرة آالف ريــال التــي تنازلــت لــه عنهــا ثــم جــرى رفــع اجللســة‬\n      ‫وتأجلــت للنظــر والتأمــل ويف يــوم األربعــاء ‪1434/3/11‬هـ حضر املدعي‬\n      ‫أصالــة ‪...............‬واملدعــى عليــه وكالــة ‪................‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومــا قــرره املدعــي أن مبلــغ اخلمســن ألــف ريــال‬\n      ‫التــي تنــازل عنهــا بائــع الفيــا للمدعــى عليــه لــم تكــن مشــروطة علــى‬\n      ‫املدعــى عليــه أن ال يبيعهــا علــى مــن ال يرتضــي املدعــي جيرتــه وأن بائــع‬\n      ‫الفيــا لــم يوكلــه يف مطالبــة املدعــى عليــه باملبلــغ املذكــور وإقــرار‬\n      ‫املدعــي أن الفيــا محــل النــزاع يف حــي ســكني ال يوجــد بينهمــا حــق‬\n      ‫مشــترك مــن طريــق خــاص ونحــوه وحلديــث جابــر رضــي اهلل عنــه عنــد‬\n      ‫البخــاري أن النبــي صلــى اهلل عليــه وســلم (قضــى بالشــفعة يف كل مــا‬\n      ‫لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة ) هــذا إضافــة‬\n      ‫إلــى أن الدعــوى باملطالبــة بالشــفعة تقــام علــى مــن بيــده العــن جلميــع‬\n      ‫ذلــك فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي جتــاه املدعــى‬\n      ‫عليــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبعــرض ذلــك علــى‬\n\n\n‫‪365‬‬\n\f‫الطرفــن قــرر املدعــى عليــه القناعــة وأمــا املدعــي فقــرر عــدم القناعــة‬\n‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة وأفهمتــه باســتالم‬\n‫نســخة مــن احلكــم يف ‪1434/3/15‬ه ـ لتقــدمي اعتراضــه عليــه خــال‬\n‫ثالثــن يومــا وإال ســقط حقــه يف االعتــراض واكتســب احلكــم القطعية‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬ويف يــوم االثنــن ‪1434/6/5‬ه ـ‬\n‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قــرار الدائــرة الثانيــة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫رقــم ‪ 34214373‬يف ‪1434/5/18‬ه ـ املتضمــن مصادقتهــم علــى احلكــم‬\n                                          ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n‫‪ 33/933734‬وتاريــخ ‪1434/04/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪........................ /‬املســجل برقــم‬\n‫‪ 3460931‬وتاريــخ ‪1434/3/11‬ه اخلــاص بدعــوى ‪............................. /‬‬\n‫ضــد‪ ................./‬و بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫والالئحــة لــم يظهــر مــا يوجــب االعتــراض‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                              ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪366‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":359,"source_page_end":366,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"759cb735c85e68d0a88d19ab8a07c20491cb72f82f408b3d2ed41a19e88cbdb2","normalized_text_hash":"7a5265f75b55867c9919b65166b90ce4df1b9f35c9ec90abf87051da5d6aead5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p359-3460931"},{"id":"a978362a-49e4-5ebb-b199-e8dc2fdd2068","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع أرض زراعية -تأخر املدعي يف إقامة الدعوى رغم العلم بالبيع -طلب الشفعة على الفور -سقوط الشفعة عند التأخر يف طلبها بدون عذر -ما يدون على صك التملك حجة يعتمد عليه -رد دعوى املدعي لعدم ثبوتها .","document_number":"34289201","case_number":"34112070","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالقوارة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/6","year":"1434","subject":"شفعة -شفعة جار -بيع أرض زراعية -تأخر املدعي يف إقامة الدعوى رغم العلم بالبيع -طلب الشفعة على الفور -سقوط الشفعة عند التأخر يف طلبها بدون عذر -ما يدون على صك التملك حجة يعتمد عليه -رد دعوى املدعي لعدم ثبوتها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34289201 :‬‬\n                         ‫َر ْق ُم الدعوى‪34112070 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34332398‬تاريخه‪1434/10/18 :‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع أرض زراعيــة‪ -‬تأخــر املدعــي يف إقامــة الدعوى‬\n      ‫رغــم العلــم بالبيــع‪ -‬طلــب الشــفعة علــى الفــور‪ -‬ســقوط الشــفعة عنــد‬\n      ‫التأخــر يف طلبهــا بــدون عــذر‪ -‬مــا يــدون علــى صــك التملــك حجــة‬\n                              ‫يعتمــد عليــه‪ -‬رد دعــوى املدعــي لعــدم ثبوتهــا ‪.‬‬\n\n\n\n      ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( الشــفعة كحــل العقــال ) رواه ابــن‬\n                                                                       ‫ماجــه ‪.‬‬\n                        ‫‪ -2‬ما رواه عبدالرزاق عن شريح ( الشفعة ملن واثبها ) ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بإثبــات شــفعته لــأرض‬\n      ‫التــي اشــتراها ‪ -‬حيــث اشــترى املدعــى عليــه أرضـ ًا زراعيــة مــن شــقيق‬\n      ‫مــوكل املدعــي مببلــغ ثالثمائــة ألــف ريــال وكان يعتقــد املدعــي أن‬\n      ‫شــقيقه مجــرد وســيط يف األرض بــن البائــع واملشــتري املدعــى عليــه‬\n      ‫ولــم يعلــم موكلــه بــأن شــقيقه قــد اشــترى امللــك لنفســه ثــم باعــه علــى‬\n      ‫املدعــى عليــه إال يف العــام املاضــي ونظــر ًا لوجــود شــراكة بــن موكلــه‬\n      ‫وشــقيقه البائــع يطلــب إثبــات شــفعة موكلــه يف األرض ‪ -‬صــادق املدعى‬\n      ‫عليــه علــى شــراء األرض مــن شــقيق املدعــي وأنكــر شــراكة املدعــي‬\n      ‫لشــقيقه فاملالــك أفــرغ لشــقيق املدعــي ولــم يذكــر لــه شــريك ًا يف امللــك‬\n‫‪367‬‬\n\f‫ولــو كان شــريك ًا ملــوكل املدعــي لذكــر ذلــك يف اإلفــراغ كمــا قــد‬\n‫أقــر املدعــي وكالــة بــأن موكلــه قــد علــم حقيقــة البيــع بــأن شــقيقه‬\n‫اشــترى هــذا امللــك لنفســه وليــس مجــرد وســيط يف العــام املاضــي‬\n‫ولــم يتقــدم بهــذه الدعــوى إال اآلن والشــفعة يطالــب بهــا فــور ًا ويطلــب‬\n‫املدعــى عليــه رد الدعــوى ‪ -‬لــم يتقــدم املدعــي برفــع هــذه الدعــوى رغــم‬\n‫علمــه بعمليــة البيــع منــذ فتــرة ‪ -‬وحيــث إن امللــك الزراعــي املذكــور يف‬\n‫الدعــوى قــد همــش علــى صكــه بأنــه انتقــل لشــقيق املدعــي وليــس فيــه‬\n‫أي إشــارة إلــى شــراكة مــوكل املدعــي لــه وهــذا يناقــض الشــراكة‬\n‫املدعــى بهــا إذ أن مــا يــدون علــى الصــك يعتبــر حجــة يســتند عليــه وحتــى‬\n‫أن هنــاك شــراكة بــن‬     ‫لــو فــرض صحــة مــا ذكــره املدعــي وكالــة مــن َّ‬\n‫موكلــه وبــن شــقيقه فهــذا ال مينــع أن تكــون هنــاك أمــاك ًا يختــص‬\n‫أن املدعــي وكالــة قــد ذكــر‬    ‫بهــا كل واحــد منهمــا عــن اآلخــر وحيــث َّ‬\n‫يف دعــواه بــأن موكلــه قــد علــم بالبيــع واالفــراغ بتاريــخ ‪1433/7/11‬ه ـ‬\n‫أي قبــل ســنة تقريب ـ ًا ولــم يتقــدم بهــذه الدعــوى إال قبــل أربعــة أشــهر‬\n‫تقريب ـ ًا وهــذا يــدل علــى عــدم صحــة الدعــوى إذ لــو كان مــوكل‬\n‫املدعــي صادق ـ ًا ملــا تأخــر يف تقــدمي الدعــوى شــهور ًا بعــد أن علــم أن‬\n‫البيــع قــد مت قبــل عــدة ســنوات والشــفعة «ملــن واثبهــا» رواه عبدالــرزاق‬\n‫عــن شــريح وذكــره الفقهــاء يف كتبهــم والشــفعة كحــل العقــال رواه‬\n‫ابــن ماجــة بســند ضعيــف والفقهــاء قــد نصــوا علــى أن الشــفعة علــى‬\n‫الفــور وقــت علمــه فــإن لــم يطلبهــا بــا عــذر بطلــت وذلــك ألن التراخــي‬\n‫يف طلبهــا يضــر باملشــتري لكونــه ال يســتقر يف ملكــه املبيــع ومينعــه مــن‬\n‫التصــرف ومــا ذكــره املدعــي وكالــة أعــاه مبــرر ًا لتأخــر موكلــه يف‬\n‫تقــدمي الدعــوى ال يعتبــر عــذر ًا مقبــو ًال يف تأخيــر التقــدم بطلــب الشــفعة‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫وحيــث أن امللــك الزراعــي محــل النــزاع قــد أفــرغ باســم املدعــى عليــه‬\n      ‫منــذ تســع ســنوات وخــال كل هــذه الســنوات كان امللــك محــل النــزاع‬\n      ‫بحــوزة املدعــى عليــه ويبعــد أن متــر كل هــذه الســنوات ولــم يعلــم مــوكل‬\n      ‫املدعــي بــأن شــقيقه اشــترى هــذا امللــك ثــم باعــه على املدعــى عليه إ ّال يف‬\n      ‫‪1433/7/11‬ه ‪ -‬صــدر احلكــم بــرد دعــوى املدعــي لعــدم ثبوتهــا ‪ -‬قنــع‬\n      ‫املدعــى عليــه واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n                    ‫احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة العامــة بالقــوارة‬\n      ‫وبناء على املعاملة احملالة لنا برقم ‪ 34112070‬وتاريخ ‪1434/03/08‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34589268‬وتاريــخ ‪ 1434/03/08‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/05/04‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫العاشــرة وأربعــن دقيقــة ‪ 10 : 40‬وفيهــا حضــر ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬الشــرعي عــن ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬وذلــك مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل بريــدة الثانيــة‪ 37667‬يف ‪1433/07/13‬ه ـ املخــول‬\n      ‫للوكيــل فيهــا حــق املطالبــة واملخاصمــة واملدافعــة واملرافعــة والشــفعة‬\n      ‫وإقامــة الدعــاوي وحتريرهــا والــرد عليهــا وتقــدمي الالئحــة االعتراضيــة‬\n      ‫وإقامــة البينــة واالنــكار وطلــب حتليــف اليمــن وقبولهــا ورفضهــا‬\n      ‫والدفــع وقبــول احلكــم ونفيــه و االعتــراض عليــه وطلــب االســتئناف‬\n      ‫والصلــح‪ ..‬الــخ فادعــى علــى احلاضــر معــه لدينــا ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬قائــا يف دعــواه عليــه انــه بتاريــخ‬\n\n‫‪369‬‬\n\f‫‪1425/8/13‬ه ـ بــاع شــقيق موكلــي ‪ ...... ......‬ملــكا زراعيــا يقــع يف‬\n‫بلــدة الصلبيــة مملــوك لــه مبوجــب الصــك الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 17‬يف ‪1419/11/29‬ه ـ وحــدوده وأطوالــه ومســاحته كمــا يلــي‬\n‫مــن الشــمال يحــده بقيــة امللــك بطــول أربعمائــة متــر ومــن اجلنــوب يحــده‬\n‫شــارع عرضــه خمســة وعشــرون متــرا بطــول اربعمائــة متــر وشــرقا‬\n‫يحــده بقيــة امللــك بطــول اربعمائــة متــر وغربــا شــارع عرضــه عشــرون‬\n‫متــر بطــول اربعمائــة متــر ومجمــوع مســاحته مائــة وســتون الــف متــر‬\n‫مربــع بــاع شــقيق موكلــي هــذا امللــك علــى املدعــي عليــه هــذا احلاضــر‬\n‫بثمــن قــدره ثالثمائــة الــف ريــال وأفــرغ هــذا امللــك باســم املدعــي عليــه‬\n‫وكان موكلــي يعتقــد حــن العقــد املــؤرخ بالتاريــخ املذكــور اعــاه‬\n‫بــأن شــقيقه ‪ ......‬مجــرد وســيط بهــذا البيــع بــن املالــك االول لهــذا امللــك‬\n‫وهــو ‪ ......‬وبــن املدعــي عليــه وقــد ذكــر شــقيق موكلــي ملوكلــي بأنــه‬\n‫مجــرد وســيط بينهمــا ولــم يعلــم موكلــي بــان شــقيقه ‪ ......‬قــد اشــترى‬\n‫هــذا امللــك لنفســه مــن ‪ ......‬ثــم باعــه علــى املدعــي عليــه ‪ ......‬اال يف العــام‬\n‫املاضــي فقــط ونظــرا الن موكلــي شــريك لشــقيقه ‪ ......‬يف امالكــه‬\n‫وجتارتــه لــذا فانــي اطلــب اثبــات شــفعة موكلــي يف عقــد البيــع املبــرم‬\n‫بــن شــقيق موكلــي وبــن املدعــي عليــه بنفــس الثمــن فموكلــي ســيدفع‬\n‫للمشــتري وهــو املدعــى عليــه ثالثمائــة الــف ريــال وهــو ثمــن شــرائه‬\n‫للملــك املذكــور يف الدعــوى هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n‫دعــوى املدعــي وكالــة اجــاب بقولــه ســأجيب عــن الدعــوى يف اجللســة‬\n‫القادمــة هكــذا أجــاب علمــا بأنــه قــد أنتهــى وقت اجللســة ولــذا رفعت يف‬\n‫الســاعة احلاديــة عشــرة والنصــف وحــدد للطرفــن موعــد يف يــوم الثالثــاء‬\n‫املوافــق ‪1434/5/28‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n                                                                                            ‫‪370‬‬\n\f      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/04‬ه‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/05/28‬ه ـ‬\n      ‫افتتحــت اجللســة الثانيــة يف الســاعة العاشــرة وفيهــا حضــر املدعــي‬\n      ‫وكالــة واملدعــى عليــه وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالة‬\n      ‫أبــرز إجابتــه يف ثــاث أوراق مت إرفاقهــا يف املعاملــة وأجــاب املدعــى عليــه‬\n      ‫بقولــه إن مضمــون إجابتــي يتلخــص فيمــا يلــي أوالـ مــا ذكــره املدعــي‬\n      ‫وكالــة بــأن شــقيق موكلــه ‪ ......‬بــاع علــي امللــك املذكــور يف الدعــوى‬\n      ‫بثــاث مائــة ألــف ريــال وأنــه أفرغــه لــي فهــذا كلــه صحيــح وقــد أفرغــه‬\n      ‫لــي يف التاريــخ املذكــور يف الدعــوى أمــا مــا ذكــره يف بقيــة دعــواه فغيــر‬\n      ‫صحيــح فقولــه أن موكلــه كان يعتقــد أن شــقيقه ‪ ......‬كان مجــرد‬\n      ‫وســيط يف البيــع املــؤرخ يف ‪1425/8/13‬ه ـ غيــر صحيــح كمــا أن مــا‬\n      ‫ذكــره مــن أن موكلــه شــريك لشــقيقه ‪ ......‬يف امللــك املذكــور كل‬\n      ‫هــذا غيــر صحيــح فامللــك قــد أفــرغ لشــقيق مــوكل املدعــي ‪...... ......‬‬\n      ‫ولــم يذكــر لــه شــريك يف امللــك إذ لــوكان شــريكا ملــوكل املدعــي‬\n      ‫لذكــر ذلــك يف اإلفــراغ ومعلــوم أن الصكــوك ســندات رســمية تثبــت‬\n      ‫صحــة مــا حتتــوي عليــه وإال لكانــت الصكــوك عبثــا كمــا أن املدعــي‬\n      ‫وكالــة قــد أقــر بــأن شــقيق موكلــه قــد اشــترى امللــك لنفســه وهــذا‬\n      ‫ينفــي الشــراكةـ ثانيــا ـ قــد أقــر املدعــي وكالــة بــأن موكلــه قــد علــم‬\n      ‫حقيقــة البيــع بــأن شــقيقه ‪ ......‬اشــترى هــذا امللــك لنفســه وليــس مجــرد‬\n      ‫وســيط يف العــام املاضــي ولــم يتقــدم بهــذه الدعــوى إال اآلن والشــفعة‬\n      ‫يطالــب بهــا فــورا وال تؤخــر لقولــه صلــى اهلل عليه وســلم (الشــفعة كحل‬\n      ‫العقــال) والبــد أن تكــون علــى الفــور ثالث ـاـ الشــراكة التــي ادعــى بهــا‬\n      ‫املدعــي وكالــة حتتــاج الــى إثبــات أي الشــراكة التــي بــن موكلــه‬\n\n\n‫‪371‬‬\n\f‫وبــن شــقيقه ‪ ......‬فــإذا ثبتــت شــراكته فلــه مطالبــة شــريكه يف ثمــن‬\n‫املبيــع ملــا تقــدم فإنــي أطلــب رد الدعــوى هكــذا أجــاب وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة أفــاد بقولــه ســأرد علــى مــا ذكــره املدعــى عليــه‬\n‫يف اجللســة القادمــة هكــذا أجــاب ورفعــت اجللســة يف الســاعة احلاديــة‬\n‫عشــرة وحــدد للطرفــن موعــد يف يــوم الثالثــاء ‪1434/6/20‬ه ـ الســاعة‬\n‫العاشــرة حــرر يف ‪1434/5/28‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                             ‫وآلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/7/22‬ه ـ افتتحــت‬\n‫اجللســة الثالثــة يف الســاعة العاشــرة والنصــف وحضــر فيهــا املدعــي‬\n‫وكالــة واملدعــى عليــه علم ـ ًا أنــه ســبق وأن حــدد للطرفــن موعــد يف‬\n‫يــوم الثالثــاء ‪1434/6/20‬ه ـ وحضــر فيهــا املدعــي وكالــة ولــم يحضــر‬\n‫املدعــى عليــه ولــم تفتــح اجللســة نظــر ًا لكــون الكهربــاء حينئــذ كانــت‬\n‫مقطوعــة ولــم يشــتغل النظــام وبســؤال املدعــي وكالــة عمــا ذكــره‬\n‫املدعــى عليــه أجــاب بقولــه ان لــدي ورقــة محــررة مــن موكلــي اطلــب‬\n‫تدوينهــا وهــي تتضمــن الــرد علــى مــا دفــع بــه املدعــى عليــه ثــم ابــرز‬\n‫الورقــة وهــذا نصهــا «أو ًال ‪ :‬يعلــم اهلل ســبحانه أننــي صــادق فيمــا ذكرته‬\n‫أننــي كنــت أعتقــد جازمـ ًا أن أخــي ‪ ......‬كان وســيطا بــن املدعــى عليــه‬\n‫والبائــع‪ ...... /‬املالــك االول للمزرعــة محــل النــزاع ‪ ،‬وأبــرأ إلــى اهلل أن‬\n‫أظلــم نفســي وغيــري بدعــوى كاذبــة ‪،‬ثانيـ ًا ‪:‬مــا أشــار إليــه أننــا لــو كنــا‬\n‫شــركاء لتــم إصــدار الصــك باســمنا وليــس باســم ‪ ......‬وحــده ينفيــه مــا‬\n‫مت االتفــاق عليــه بيننــا يف عقــد الشــراكة احملــرر عــام ‪1420‬ه ـ حيــث‬\n‫يوجــد عقــارات باســمي وعقــارات باســم االخ ‪ ......‬قبــل خروجــه مــن‬\n‫الشــراكة وعقــارات باســم االخ ‪ ......‬وهــي مشــتركة بيننــا بالســوية ‪،‬‬\n\n\n                                                                                        ‫‪372‬‬\n\f      ‫ثالثـ ًا ‪ :‬مــا أشــار إليــه أن الشــفعة كحــل العقــال الــخ فهــذا صحيــح ولهــذا‬\n      ‫فإننــي فــور علمــي بــأن أخــي ‪ ......‬اشــترى املزرعــة ثــم باعهــا شــفعت يف‬\n      ‫احلــال وأشــهدت احلاضريــن علــى ذلــك ‪ ،‬رابع ـ ًا ‪ :‬ليــس لــي حــق مطالبــة‬\n      ‫أخــي ‪ ......‬بقيمــة املزرعــة مــا دمــت شــريكا ولــي حــق الشــفعة فيهــا ‪،‬‬\n      ‫خامس ـ ًا ‪ :‬الشــفعة شــيء وتقــدمي الدعــوى شــيء آخــر فأنــا فــور علمــي‬\n      ‫شــفعت أمــا تقــدمي الدعــوى فأخرتــه بســبب ‪ 1‬ـ ـ وجــود خصومــة بــن‬\n      ‫أخــي ‪ ......‬واملدعــى عليــه لــدي فضيلتكــم وخشــيت أن أتقــدم بالدعــوى‬\n      ‫فينصــرف الظــن الــى ان الهــدف هــو االربــاك والتشــويش علــى خصــم‬\n      ‫أخــي فأثــرت التريــث حلــن انتهــاء اخلصومــة بينهمــا إال أن تأخــر احلكــم‬\n      ‫بينهمــا أجبرنــي علــى التقــدم بدعــواي ‪ 2 ،‬ـ ـ االســتفادة مــن ســير الدعوى‬\n      ‫بينهمــا فيمــا يثبــت صحــة دعــواي يف الشــفعة ‪ 3 ،‬ـ ـ البحــث عــن مزيــد‬\n      ‫مــن البينــات التــي تثبــت الشــراكة وذلــك ببعــض املعامــات مــع االخريــن‬\n      ‫بينــي وبــن اخــي ‪ ........‬تلــك هــي إجابــة موكلــي عــن مذكــرة املدعــى‬\n      ‫عليــه ‪ ،‬علمــا ان موكلــي يســعى جاهــد ًا للحصــول علــى بعــض االوراق‬\n      ‫الثبوتيــة للتعامــات القدميــة بينــه واخيــه ‪ ......‬مــن جهــة واالشــخاص‬\n      ‫الذيــن مت التعامــل معهــم مــن جهــة اخــرى «‪ .‬انتهــى نصهــا ‪ .‬فجــرى ســؤال‬\n      ‫املدعــي وكالــة متــى علــم موكلــه بــأن شــقيقه ‪ ......‬قــد اشــترى امللــك‬\n      ‫الزراعــي املذكــور اعــاه مــن املالــك ‪ ......‬ومتــى علــم ان امللــك املذكــور‬\n      ‫افــرغ لشــقيقه ‪ ......‬فأجــاب بقولــه ال أعلــم عــن ذلــك وســأرجع ملوكلــي‬\n      ‫لســؤاله عــن ذلــك هكــذا اجــاب والنتهــاء وقــت اجللســة فقــد رفعــت يف‬\n      ‫الســاعة احلاديــة عشــرة والنصــف وحــدد للطرفــن موعــد يف يــوم الســبت‬\n      ‫‪1434/8/6‬ه ـ يف الســاعة العاشــرة ‪ ..‬وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/22‬ه ـ‬\n\n\n‫‪373‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/08/06‬ه ـ‬\n‫افتتحــت اجللســة الرابعــة يف الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وبســؤال املدعــي وكالــة عمــا ســألته عنــه يف‬\n‫آخــر اجللســة املاضيــة فيمــا يتعلــق بوقــت علــم موكلــه بشــراء شــقيقه‬\n‫‪ ......‬امللــك الزراعــي املذكــور مــن املالــك االول ‪ ......‬ووقــت علــم موكلــه‬\n‫بإفــراغ امللــك الزراعــي املذكــور باســم شــقيقه ‪ ......‬وكذلــك متــى‬\n‫علــم موكلــه بإفــراغ امللــك املذكــور باســم املدعــى عليــه ‪ ......‬فأجــاب‬\n‫املدعــي وكالــة بقولــه لــم يعلــم موكلــي بجميــع مــا ذكــر ســواء فيمــا‬\n‫يتعلــق بإفــراغ امللــك باســم شــقيقه ‪ ......‬او إفــراغ امللــك بعــد ذلــك باســم‬\n‫املدعــى عليــه لــم يعلــم عــن ذلــك إ َّال بتاريــخ ‪1433/7/11‬ه ـ وبعــد ان‬\n‫علــم شـ َّهد علــى ذلــك شــهود ًا ووكلنــي فتقدمــت بهــذه الدعــوى هكــذا‬\n‫أجــاب فســألته ملــاذا لــم يتقــدم بهــذه الدعــوى إ َّال قبــل أربعــة أشــهر رغــم‬\n‫علــم موكلــه بالبيــع واالفــراغ للملــك الزراعــي ـ محــل النــزاع ـ قبــل ســنة‬\n‫فأجــاب بقولــه ان ســبب ذلــك هــو وجــود خصومــة بــن شــقيق موكلــي‬\n‫‪ ......‬وبــن املدعــى عليــه ‪ ......‬فلــم يرغــب التشــويش بدعــوى الشــفعة علــى‬\n‫ـاء علــى مــا‬\n           ‫الدعــوى القائمــة بــن ‪ ......‬واملدعــى عليــه هكــذا أجــاب فبنـ ُ‬\n‫تقــدم مــن دعــوى املدعــي وكالــة وإجابــة املدعــى عليــه باملصادقــة علــى‬\n‫دعــوى املدعــي وكالــة فيمــا يتعلــق بشــرائه ـ أي شــراء املدعــى عليــه ـ‬\n‫امللــك الزراعــي املذكــور يف الدعــوى مــن شــقيق مــوكل املدعــي بالثمــن‬\n‫والتاريــخ املذكوريــن يف الدعــوى ونفــى مــا ذكــره املدعــي وكالــة يف‬\n‫دعــواه مــن ان موكلــه كان يعتقــد ان شــقيقه ‪ ......‬كان مجــرد وســيط‬\n‫بــن ‪ ......‬وبــن املدعــى عليــه ‪ ......‬كمــا نفــى املدعــى عليــه مــا ذكــره‬\n‫أن بــن موكلــه وبــن شــقيقه ‪ ......‬شــراكة يف‬          ‫املدعــي وكالــة مــن َّ‬\n\n                                                                                         ‫‪374‬‬\n\f      ‫امللــك الزراعــي املذكــور يف الدعــوى وبعــد االطــاع علــى صــك امللــك‬\n      ‫الزراعــي املذكــور يف الدعــوى وعلــى ســجله فــاذا هــو ســاري املفعــول‬\n      ‫باســم املدعــى عليــه ‪ ......‬وحيــث ان امللــك الزراعــي املذكــور يف الدعــوى‬\n      ‫قــد ظَّ هــر عليــه بأنــه أنتقــل ‪ ......‬وليــس فيــه أي إشــارة الــى شــراكة‬\n      ‫مــوكل املدعــي لــه وهــذا يناقــض الشــراكة املدعــى بهــا إذ إن مــا يــدون‬\n      ‫علــى الصــك يعتبــر حجــة يســتند عليــه وحتــى لــو فــرض صحــة مــا ذكــره‬\n      ‫أن هنــاك شــراكة بــن موكلــه وبــن شــقيقه ‪......‬‬         ‫املدعــي وكالــة مــن َّ‬\n      ‫فهــذا ال مينــع أن تكــون هنــاك أمــاك ًا يختــص بهــا كل واحــد منهمــا‬\n      ‫أن املدعــي وكالــة قــد ذكــر يف دعــواه بــأن موكلــه‬        ‫عــن اآلخــر وحيــث َّ‬\n      ‫قــد علــم بالبيــع واالفــراغ بتاريــخ ‪1433/7/11‬ه ـ أي قبل ســنة تقريب ًا ولم‬\n      ‫يتقــدم بهــذه الدعــوى إال قبــل أربعــة أشــهر تقريبـ ًا وهــذا يــدل علــى عــدم‬\n      ‫صحــة الدعــوى إذ لــو كان مــوكل املدعــي صادق ـ ًا ملــا تأخــر يف تقــدمي‬\n      ‫الدعــوى شــهور ًا بعــد ان علــم أن البيــع قــد مت قبــل عــدة ســنوات والشــفعة‬\n      ‫«ملــن واثبهــا» رواه عبدالــرزاق عــن شــريح وذكــره الفقهــاء يف كتبهــم‬\n      ‫والشــفعة كحــل العقــال رواه ابــن ماجــة بســند ضعيــف والفقهــاء قــد‬\n      ‫نصــوا علــى أن الشــفعة علــى الفــور وقــت علمــه فــإن لــم يطلبهــا بــا عــذر‬\n      ‫بطلــت وذلــك ألن التراخــي يف طلبهــا يضــر باملشــتري لكونــه ال يســتقر‬\n      ‫يف ملكــه املبيــع ومينعــه مــن التصــرف ومــا ذكــره املدعــي وكالــة أعــاه‬\n      ‫مبــرر ًا تأخــر موكلــه يف تقــدمي الدعــوى ال يعتبــر عــذر ًا مقبــو ًال يف تأخيــر‬\n      ‫التقــدم بطلــب الشــفعة فانتظــاره انتهــاء الدعــوى االخــرى التــي بــن ‪......‬‬\n      ‫واملدعــى عليــه ‪ ......‬ال يعــد عــذر ًا مقبــو ًال يف تأخيــر طلــب الشــفعة وحيــث‬\n      ‫أن امللــك الزراعــي ـ محــل النــزاع ـ قــد أفــرغ باســم املدعــى عليــه منــذ‬\n      ‫تســع ســنوات وخــال كل هــذه الســنوات كان امللــك محــل النــزاع‬\n\n\n‫‪375‬‬\n\f‫بحــوزة املدعــى عليــه ويبعــد أن متــر كل هــذه الســنوات ولــم يعلــم مــوكل‬\n‫املدعــي بــأن شــقيقه اشــترى هــذا امللــك ثــم باعــه علــى املدعــى عليــه إ ّال‬\n‫ـدي خصومــة ال تــزال قائمــة بــن املدعــى‬     ‫يف ‪1433/7/11‬ه ـ علم ـ ًا أن لـ َّ‬\n‫عليــه وشــقيق مــوكل املدعــي ‪ ......‬بخصــوص معــدات يف نفــس هــذا‬\n‫امللــك الزراعــي ـ محــل النــزاع ـ وقــد يكــون ســبب تقــدمي هــذه الدعــوى‬\n‫هــو تلــك الدعــوى القائمــة بــن املدعــى عليــه و‪ ......‬ملــا تقــدم لــم تثبــت‬\n‫ـدي دعــوى املدعــي وكالــة فــرددت دعــواه وبذلــك حكمــت واهلل أعلــم‬            ‫لـ َّ‬\n‫وأحكــم وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه‬\n‫أمــا املدعــي وكالــة فقــد قــرر عــدم القناعــة بــه وطلــب رفعــه حملكمــة‬\n‫االســتئناف بالئحــة اعتراضيــة فــأ فهمتــه بــأن مــدة االعتــراض ثالثــون‬\n‫ـار ًا مــن تاريــخ هــذا اليــوم ليقــدم اعتراضــه خاللهــا وإذا انتهــت‬\n                                                                        ‫يومـ ًا اعتبـ ً‬\n‫هــذه املــدة ولــم يقــدم اعتراضــه خاللهــا فــإن احلكــم يعتبــر مكتســب ًا‬\n‫للصفــة القطعيــة ففهــم ذلــك ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/06‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫ففــي يــوم األحــد ‪1434/8/28‬ه ـ افتتحــت اجللســة اخلامســة يف الســاعة‬\n‫التاســعة وجــرى االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــي‬\n‫‪ ......‬ولــم أجــد فيهــا مــا يؤثــر علــى احلكــم وقــررت رفــع املعاملــة وبرفقهــا‬\n‫الالئحــة االعتراضيــة حملكمــة االســتئناف مبنطقــة القصيــم لتدقيــق‬\n‫احلكــم ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1434/08/28‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n\n\n                                                                                           ‫‪376‬‬\n\f      ‫ال ـمـ ــحكمة الـ ـع ــام ـ ــة بالقــوارة الشــيخ ‪ ...... /‬ب ــرق ـ ــم (‪)342200667‬‬\n      ‫وتــاري ـ ــخ ‪1434/9/16‬هـ ؛ احملالة إلينا برقم (‪ )34436092‬؛ الــمرف ـ ــق‬\n      ‫بها ال ـصــك الــمسج ــل ب ــرق ــم (‪ )......‬وت ــاريـ ــخ ‪1434/8/6‬هـ ؛ الصادر‬\n      ‫ا عــن ‪ ......‬ضــد‪، ...... /‬‬\n                                 ‫مــن فضيلتــه ؛ اخلــاص بدعــوى‪ ...... ...... /‬وكيـ ً‬\n      ‫بشــأن املطالبــة بإثبــات شــفعة مــوكل املدعــي يف بيــع ملــك زراعــي‪ ،‬وقــد‬\n      ‫تضمــن الصــك حكــم فضيلتــه أنــه لــم تثبــت لديــه دعوى املدعــي وكالة‬\n      ‫ورد دعــواه؛ علــى النحــو املفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة ‪ ،‬قررنــا املصادقــة علــى احلكــم‪.‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪377‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":367,"source_page_end":377,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"abdbf9fe3aa1f01a6f08e2b97929fc655f15533042054cef9c12dc5500af472c","normalized_text_hash":"f1dce50822bd7cb0f43bdda037ace9ce004351f6258da020d8d39e87335de253","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p367-34289201"},{"id":"9d6ff593-71e1-50cb-8d28-a90a03293cfb","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع أرض زراعية -إقرار املدعي بامتاك املدعى عليه (املشتري) لقطعة أرض مالصقة لأرض محل الدعوى- اإلقرار بوجود مسقى مستقل وفواصل بن أرض املدعي واألرض محل الدعوى -إذا وقعت احلدود وصرفت الطرق فا شفعة -صرف النظر عن الدعوى.","document_number":"34232609","case_number":"34134568","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/6","year":"1434","subject":"شفعة -شفعة جار -بيع أرض زراعية -إقرار املدعي بامتاك املدعى عليه (املشتري) لقطعة أرض مالصقة لأرض محل الدعوى- اإلقرار بوجود مسقى مستقل وفواصل بن أرض املدعي واألرض محل الدعوى -إذا وقعت احلدود وصرفت الطرق فا شفعة -صرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34232609 :‬‬\n                   ‫َر ْق ُم الدعوى‪34134568 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34355968‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع أرض زراعيــة‪ -‬إقــرار املدعــي بامتــاك املدعــى‬\n‫عليــه (املشــتري) لقطعــة أرض مالصقــة لــأرض محــل الدعــوى‪-‬‬\n‫اإلقــرار بوجــود مســقى مســتقل وفواصــل بــن أرض املدعــي واألرض‬\n‫محــل الدعــوى‪ -‬إذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة‪ -‬صــرف‬\n                                                      ‫النظــر عــن الدعــوى‪.‬‬\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (فــإذا وقعــت احلــدود وصرفــت الطــرق فــا‬\n                                                   ‫شــفعة) رواه البخــاري‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بــأن لــه أرض ـ ًا زراعيــة ويالصقهــا‬\n‫ركيــب جــاره وال يفصــل بــن املزرعتــن ســوى عقــم صغيــر وقــد باعــه‬\n‫علــى املدعــى عليــه ومبــا أنــه أحــق بهــذا الركيــب مــن املدعــى عليــه‬\n‫يطلــب حــق الشــفعة يف هــذا الركيــب هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n‫عليــه باملصادقــة علــى الدعــوى وأن جــار املدعــي الــذي باعــه الركيــب‬\n‫هــو خالــه وجــاره مــن اجلهــة الشــرقية وأنــه اشــتراه منــذ خمســة عشــر‬\n‫عام ـ ًا ولــه مصلحــة مــن ذلــك ليتمكــن مــن فتــح طريــق مــن خاللــه إلــى‬\n‫ركيبــه ويرفــض طلــب املدعــي الشــفعة هكــذا أجــاب ‪ -‬صــادق املدعــي‬\n\n                                                                                  ‫‪378‬‬\n\f      ‫بــأن للمدعــى عليــه ركيــب مالصــق لركيــب خالــه مــن اجلهــة الشــرقية‬\n      ‫‪ -‬قــرر الطرفــان بــأن لــكل ركيــب مســقى مســتقل ‪ -‬مبــا أن املدعــي‬\n      ‫أقــر بــأن للمدعــى عليــه أرض مالصقــة لــأرض املدعــى بهــا مــن جهتهــا‬\n      ‫الشــرقية وأن لــكل مــن أرضــه واألرض محــل الدعــوى مســقى مســتقل‬\n      ‫وأن أرضــه وأرض املدعــى عليــه واألرض املدعــى بهــا مفصــول بعضهــا‬\n      ‫عــن بعــض واضحــة املعالــم بينــة احلــدود‪ -‬ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫( فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعه ) ‪ -‬ومبــا أن املدعــي‬\n      ‫ليــس بأولــى بهــذه األرض مــن املدعــى عليــه ألن كالهما مجاور لها ‪ -‬ملا‬\n      ‫تقــدم صــدر احلكــم بصــرف النظــر عــن الدعــوى لعــدم ثبــوت موجبهــا‪-‬‬\n      ‫اعتــرض املدعــي علــى احلكــم بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة قلــوة وبنــاء علــى‬\n      ‫املعاملــة احملالــة ملكتبنــا برقــم ‪ 34134568‬وتاريــخ ‪1434/03/22‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34713517‬وتاريــخ ‪ 1434/03/22‬ه ـ املتعلقة‬\n      ‫بدعــوى ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n      ‫ضــد ‪.......‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬ففــي يــوم األربعــاء‬\n      ‫امل ـ ـ ــوافق‪ 1434/05/15‬ه ـ افتتحــت اجللســة الـ ــساع ـ ـ ــة ‪ 10 : 30‬وفيهــا‬\n      ‫ا أن لــي ارضـ ًا‬ ‫حضــر الطرفــان وبســؤال املدعــي عــن دعــواه ادعــى قائـ ً‬\n      ‫زراعيــه تقــع يف وادي نيــرا ويالصقهــا مــن اجلهــة الشــمالية ‪.......‬وهــو مــن‬\n      ‫جماعتنــا وال يفصــل بــن املزرعتــن ســوى عقــم صغيــر وقــد قــام ‪.....‬‬\n\n‫‪379‬‬\n\f‫املذكــور ببيــع هــذا الركيــب علــى املدعــى عليــه وحيــث أننــي أحــق‬\n‫بهــذا الركيــب مــن املدعــى عليــه حيــث أنــه ليــس مــن جماعتنــا فإنــي‬\n‫أطالــب بحــق الشــفعة يف هــذا الركيــب هــذه دعــواي وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه أن لــه أرضـ ًا زراعيــه تقــع‬\n‫يف وادي نيــرا ويالصقهــا مــن اجلهــة الشــمالية ‪.......‬وال يفصــل بينهمــا‬\n‫ســوى عقــم صغيــر واننــي اشــتريت ركيــب ‪ .....‬هــذا كلــه صحيــح‬\n‫و‪ ...........‬املذكــور هــو خالــي وقــد اشــتريت الركيــب املذكــور قبــل‬\n‫خمســة عشــر ســنه بخمســن الــف ري ــال الن لــي ركيبـ ًا زراعيـ ًا مالصــق‬\n‫لركيــب خالــي املذكــور مــن اجلهــة الشــرقية واشــتريت ركيــب خالــي‬\n‫ألمتكــن مــن فتــح طريــق مــن خاللــه إلــى ركيبــي ألن طريقــي األول‬\n‫إلــى ركيبــي بعيــد وفيــه مشــقه لــي وأنــا أرفــض مــا طالــب بــه املدعــي‬\n‫مــن الشــفعة ألنــه ليــس أولــى منــي يف ركيــب ‪ .....‬وكالنــا مجــاور لــه‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى عليــه‬\n‫أن لــه ركيب ـ ًا مالصق ـ ًا لركيــب خالــه مــن اجلهــة الشــرقية صحيــح‬\n‫ولكــن يفصــل بينهمــا عــراق وشــبك ومــا ذكــره انــه اشــتراه قبــل خمــس‬\n‫عشــرة ســنه بخمســن الــف ري ــال فهــذا ال أعلــم عنــه شــيئ ًا هكــذا قــرر‬\n‫ـكل‬\n ‫وبســؤال املدعــي هــل ركيبــه وركيــب ‪ ....‬لهــا مســقى واحــد أم لـ ٍ‬\n‫منهمــا مســقى قــال لــكل منهمــا مســقى هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي لــكل مــن ركيبــه و‪.......‬‬\n‫مســقى مســتقل صحيــح هكــذا قــرر ورفعــت اجللســة للتأمــل ويف جلســة‬\n‫اخــرى وفيهــا حضــر الطرفــان وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n‫وحيــث اقــر املدعــي أن للمدعــى عليــه أرضــا مالصقــة لــأرض محــل‬\n‫الدعــوى مــن جهتهــا الشــرقية واقــر بــأن لــكل مــن أرضــه واالرض محــل‬\n\n\n                                                                                       ‫‪380‬‬\n\f      ‫الدعــوى مســقى مســتقل وأقــر أن أرضــه وأرض املدعــى عليــه واألرض‬\n      ‫أراض واضحــه املعالــم‬‫ٍ‬      ‫محــل الدعــوى مفصــول بعضهــا عــن بعــض وهــي‬\n      ‫بينــة احلــدود وملــا رواه البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه‬\n      ‫وســلم قــال (فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعه ) واملدعــي‬\n      ‫ليــس بأولــى بهــذه األرض مــن املدعــى عليــه ألن كالهمــا مجــاور لهــا‬\n      ‫ومــا ذكــره املدعــي مــن أن املدعــى عليــه ليــس مــن جماعتهــم وبالتالــي‬\n      ‫يكــون هــو أحــق بــاألرض منــه كالم يف غيــر محلــه وال وجاهــة لــه البتــه‬\n      ‫الن هــذا الوصــف واحلــال مــا ذكــر ال يبطــل حــق املدعــى عليــه يف بيــع‬\n      ‫شــرعي مســتكمل لشــروطه وأركانــه لذلــك كلــه فقــد صرفــت النظر‬\n      ‫عــن دعــوى املدعــي لعــدم ثبــوت موجبهــا وبــه حكمــت وبعــرض ذلــك‬\n      ‫علــى املدعــي قــرر عــدم قناعتــه وقــررت تســليمه نســخه مــن احلكــم يف‬\n      ‫هــذه اجللســة وأفهمــت أن لــه مــدة وقدرهــا ثالثــون يومـ ًا لتقــدمي اعتراضــه‬\n      ‫واذا لــم يتقــدم باعتراضــه خــال هــذه املــدة فيســقط حقــه يف طلــب‬\n      ‫االســتئناف ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة‬\n      ‫‪ 09:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/06‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪.......‬رئيــس احملكمــة العامــة مبحافظــة قلــوة واملســجل بعــدد‬\n      ‫‪ 34232609‬وتــاري ــخ ‪1434/6 /6‬ه ـ املتضمــن دعــوى ‪.......‬ضــد ‪.......‬يف‬\n                                               ‫أرض احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n\n\n‫‪381‬‬\n\f‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا‬\n                                            ‫محم ــد وعل ــى آل ــه وصحب ــه وس ــلم‪.‬‬\n\n\n\n\n                                                                                             ‫‪382‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                   ‫املوضوع‬                       ‫التصنيف‬       ‫م‬\n\n         ‫منازعة يف تنفيذ عقد فرش وديكور‪ ،‬ويطالب‬\n         ‫املدعي بندب خبير إلحصاء األعمال التي قام‬\n  ‫‪5‬‬      ‫بها املدعى عليه وإلزامه بإكمال النواقص إن‬   ‫عقد مقاولة‬      ‫‪1‬‬\n                            ‫وجدت‬\n\n         ‫مدع بقيمة أعمال مقاولة واملدعى عليه‬\n                                         ‫مطالبة ٍ‬\n  ‫‪11‬‬              ‫يدفع بالسداد وال بينة له‬           ‫عقد مقاولة‬      ‫‪2‬‬\n\n         ‫مطالبة بإكمال أعمال مقاولة وغرامة شرط‬\n  ‫‪15‬‬         ‫جزائي يف عقد مقاولة ذي جهالة‬            ‫عقد مقاولة‬      ‫‪3‬‬\n\n          ‫مطالبة بإعادة جزء من عوض جعالة لم ينفذ‬\n  ‫‪27‬‬     ‫مطالبة بقيمة العامل املدعى عليه فيه املطلوب مع مرور املدى‬   ‫‪4‬‬\n                ‫الزمني املتفق عليه إلنهاء املطلوب‬        ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة سمسرة(سعي)متعارف عليها يف‬\n  ‫‪33‬‬                ‫قيمة أرض من البائع‬                               ‫‪5‬‬\n                                                   ‫أتعاب‬\n\n          ‫مطالبة بأتعاب تعقيب يف عقد وكالة بأجرة‬     ‫مطالبة بقيمة‬\n  ‫‪40‬‬                                                                 ‫‪6‬‬\n                                                        ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة سمسرة عقار من مشتر غائب لم‬\n  ‫‪57‬‬               ‫يحضر الدعوى مع تبلغه‬                              ‫‪7‬‬\n                                                    ‫أتعاب‬\n\n           ‫مطالبة بأتعاب محاماة لدى القاضي ناظر‬      ‫مطالبة بقيمة‬\n  ‫‪65‬‬                  ‫الدعوى األصل‬                                   ‫‪8‬‬\n                                                        ‫أتعاب‬\n\n          ‫مطالبة بأثر شرط جزائي يف عقد جعالة أو‬      ‫مطالبة بقيمة‬\n  ‫‪84‬‬         ‫إجارة على استخراج حجة استحكام‬                           ‫‪9‬‬\n                                                        ‫أتعاب‬\n\n                   ‫مطالبة بأتعاب محاماة‬              ‫مطالبة بقيمة‬\n  ‫‪92‬‬                                                                 ‫‪10‬‬\n                                                        ‫أتعاب‬\n\f‫الصفحة‬                    ‫املوضوع‬                        ‫التصنيف‬      ‫م‬\n\n               ‫إلزام مدعى عليه بأجرة محاماة‬            ‫مطالبة بقيمة‬\n  ‫‪98‬‬                                                                  ‫‪11‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة سمسرة (سعي) لفسخ‬          ‫مطالبة بقيمة‬\n ‫‪104‬‬             ‫البيع وإقالة املشتري منه‬                             ‫‪12‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة ورثة بأتعاب محاماة مورثهم من ورثة‬     ‫مطالبة بقيمة‬\n ‫‪110‬‬                       ‫متوفى‬                                      ‫‪13‬‬\n                                                          ‫أتعاب‬\n\n         ‫مطالبة بإعادة أجرة سمسرة (داللة) يف شراء‬      ‫مطالبة بقيمة‬\n ‫‪201‬‬                     ‫عقار لم يتم‬                                  ‫‪14‬‬\n                                                          ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة باسترداد أجرة سمسرة (داللة) لبطالن‬\n ‫‪209‬‬                      ‫عقد البيع‬                                   ‫‪15‬‬\n                                                      ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة استقدام خادمة أعيدت‬\n         ‫ملكتب املدعى عليه المتناعها عن العمل فترة‬     ‫مطالبة بقيمة‬\n ‫‪221‬‬                                                                  ‫‪16‬‬\n                     ‫التجربة املتفق عليها‬                 ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة أعمال تعقيب لم تنجز‪،‬‬\n           ‫والعقد بني الطرفني ينص على استحقاق‬          ‫مطالبة بقيمة‬\n ‫‪227‬‬                                                                  ‫‪17‬‬\n              ‫األجرة يف حال فسخها من املدعي‬               ‫أتعاب‬\n\n          ‫احلكم بأجرة املثل ملدع انتحل صفة احملامي‬     ‫مطالبة بقيمة‬\n ‫‪241‬‬       ‫ويطالب بأتعاب محاماته من املدعى عليه‬                       ‫‪18‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة بباقي أتعاب عقد استشارات إدارية‬       ‫مطالبة بقيمة‬\n ‫‪260‬‬                      ‫وتربوية‬                                     ‫‪19‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة عاملة منزلية بتنفيذ العقد أو دفع ما‬   ‫مطالبة بقيمة‬\n ‫‪272‬‬            ‫غرمه املدعي ألجل استقدامها‬                            ‫‪20‬‬\n                                                          ‫أتعاب‬\n\f‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬      ‫م‬\n\n          ‫إلزام بالتحكيم يف منازعة يف أجرة محاماة‬\n           ‫اتفق الطرفان يف العقد بينهما على معاجلة‬    ‫مطالبة بقيمة‬\n ‫‪276‬‬                                                                 ‫‪21‬‬\n                       ‫النزاع بينهما به‬                  ‫أتعاب‬\n\n          ‫دعوى خادمة منزلية بباقي رواتبها‪ ،‬واملدعى‬    ‫مطالبة بقيمة‬\n ‫‪289‬‬             ‫عليه يدفع بحسمه ملا أتلفته‬                          ‫‪22‬‬\n                                                         ‫أتعاب‬\n\n            ‫مطالبة بأتعاب محاماة يف دعوى ال تزال‬      ‫مطالبة بقيمة‬\n ‫‪294‬‬                       ‫منظورة‬                                    ‫‪23‬‬\n                                                         ‫أتعاب‬\n\n          ‫مطالبة محام باحلجز التحفظي على أمالك‬        ‫مطالبة بقيمة‬\n ‫‪301‬‬     ‫للمدعى عليها حفظا ألتعابه يف محاماته عنها‬                   ‫‪24‬‬\n                                                         ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأتعاب محاماة من مدعى عليهم لتعاقد‬\n ‫‪305‬‬                  ‫مورثهم مع املدعي‬                               ‫‪25‬‬\n                                                      ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة عمل تعقيب من املدعى عليه وال‬\n ‫‪316‬‬                     ‫بينة للمدعي‬                                 ‫‪26‬‬\n                                                      ‫أتعاب‬\n\n           ‫مطالبة بأجرة محاماة‪ ،‬واملدعى عليه يدفع‬\n          ‫بأن املتفق عليه من أتعابه على املستحصل ال‬   ‫مطالبة بقيمة‬\n ‫‪322‬‬                                                                 ‫‪27‬‬\n                          ‫املستحق‬                        ‫أتعاب‬\n\n          ‫مطالبة عاملة منزلية بالرجوع إلى العمل لدى‬\n ‫‪330‬‬     ‫مطالبة بقيمة املدعي باقي مدة العقد بينهما أو دفع ما غرمه‬    ‫‪28‬‬\n                     ‫لقاء استقدامه لها‬                  ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بإعادة أجرة أعمال تعقيب جتديد إقامة‬\n ‫‪335‬‬               ‫عامل لعدم إجناز العمل‬                             ‫‪29‬‬\n                                                       ‫أتعاب‬\n\n         ‫مطالبة بالشفعة يف شراء مزرعة مجاورة ملزرعة‬\n ‫‪343‬‬                       ‫املدعي‬                        ‫شفعة‬        ‫‪30‬‬\n\f‫الصفحة‬                   ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة مدع بالشفعة وإلزام مدعى عليه مبا‬\n         ‫حسم له نتيجة توسط املدعى عليه الشتراطه‬\n ‫‪359‬‬      ‫على املدعى عليه أن يختار جاره وأن ال يبيع‬    ‫شفعة‬     ‫‪31‬‬\n         ‫على أحد إال بإذنه‪ ،‬والعني ليست بيد املدعى‬\n                       ‫عليه حال الدعوى‬\n\n          ‫تأخر مدع يف إثبات شفعته يف شراء مزرعة‬\n ‫‪367‬‬             ‫يدعي شركاته مع بائعها‬                 ‫شفعة‬     ‫‪32‬‬\n\n          ‫مطالبة مدع بحق الشفعة يف أرض مستقلة‬\n ‫‪378‬‬                 ‫مجاورة مللكه‬                      ‫شفعة‬     ‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":378,"source_page_end":386,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"da83bd3b0bd081b181d0ba5b4496c1c50a51589855c69e2a386f412bb30278a7","normalized_text_hash":"0420f5c2df7ad3dca520d85263f3ce96d6fcb9c8de6b29562e3447aa23a1f011","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p378-34232609"},{"id":"400e07db-1cba-5f44-b4fd-85ce0ef7d6dc","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -طلب إعادة وقف إلى مستحقيه -نقل وقف إلى جمعية خيرية إعتقاد ا بانقطاع الوقف -ظهور مستحقني للوقف -رجوع القاضي عن حكمه إذا ثبت لديه عدم انقطاع الوقف -عدم جواز الوقف فيما يخالف الشرع -وزارة املالية صاحبة الوالية يف حفظ أموال الغيب -وزارة الشئون اإلسامية صاحبة الوالية يف حفظ أموال األوقاف العامة.","document_number":"33439487","case_number":"6102","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة ويف يوم الثالثاء املوافق 1429/12/25ه حضر ( )","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"وقف -طلب إعادة وقف إلى مستحقيه -نقل وقف إلى جمعية خيرية إعتقاد ا بانقطاع الوقف -ظهور مستحقني للوقف -رجوع القاضي عن حكمه إذا ثبت لديه عدم انقطاع الوقف -عدم جواز الوقف فيما يخالف الشرع -وزارة املالية صاحبة الوالية يف حفظ أموال الغيب -وزارة الشئون اإلسامية صاحبة الوالية يف حفظ أموال األوقاف العامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1433/10/28 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33439487 :‬‬\n                             ‫َر ْق ُم الدعوى‪6102 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34604528‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n     ‫وقــف ‪ -‬طلــب إعــادة وقــف إلــى مســتحقيه ‪ -‬نقــل وقــف إلــى جمعيــة‬\n     ‫خيريــة إعتقــاد ًا بانقطــاع الوقــف ‪ -‬ظهــور مســتحقني للوقــف ‪ -‬رجــوع‬\n     ‫القاضــي عــن حكمــه إذا ثبــت لديــه عــدم انقطــاع الوقــف ‪ -‬عــدم جــواز‬\n     ‫الوقــف فيمــا يخالــف الشــرع ‪ -‬وزارة املاليــة صاحبــة الواليــة يف حفــظ‬\n     ‫أمــوال الغيــب ‪ -‬وزارة الشــئون اإلســامية صاحبــة الواليــة يف حفــظ‬\n                                                       ‫أمــوال األوقــاف العامــة‪.‬‬\n\n\n\n\n     ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                         ‫حكمه‪.‬‬\n\n\n\n     ‫أقــام رجــل دعــوى أصالــة عــن نفســه وبوكالــة عــن غيــره دعــوى علــى‬\n     ‫اجلمعيــة (‪ ).....‬بصفتهــا اجلهــة القائمــة واملســتفيدة مــن وقــف امــرأة‬\n     ‫بحجــة أن وقــف املــرأة قــد انقطــع مســتحقه وقــد ســلم الوقــف املذكــور‬\n     ‫للجمعيــة (‪ ).....‬مبوجــب صــك صــادر مــن ناظــر القضيــة وطلــب املدعــي‬\n     ‫بإعــادة الوقــف ملســتحقه مــن األقربــن‪ ،‬طلبــت احملكمــة منــه حتديــد‬\n     ‫مــن آل إليهــم االســتحقاق يف الوقــف املذكــور فأبــرز صــك الوقفيــة فــإذا‬\n     ‫فيــه أنــه يــؤول مــن بعــد املوقفــة إلــى بنــت ابنهــا ثــم مــن بعدهــا ينحصــر‬\n\n‫‪5‬‬\n\f‫يف أوالدهــا وذريتهــا حتــى االنقــراض قــد أثبــت املدعــي أن املدعيــن‬\n‫هــم مــن ذريــة بنــت ابــن املوقفــة‪ ،‬نفــى املدعــى عليــه علمــه بالدعــوى‬\n‫وذكــر أنــه ال مانــع لــدى اجلمعيــة مــن إعــادة الوقــف إلــى مســتحقه إذا‬\n‫ثبــت اســتحقاقه‪ ،‬اطلعــت احملكمــة علــى الوصايــا اخلاصــة يف هــذا‬\n‫الوقــف ومــن ألــت إليــه صكــوك حصــر الورثــة وكيــف يقســم الريــع‬\n‫علــى مســتحقه كمــا اطلعــت علــى الصــك الصــادر مــن الناظــر الســابق‬\n‫علــى الوقــف والــذي تنــازل فيــه عــن الوقــف املذكــور لصالــح اجلمعيــة‬\n‫(‪ ).....‬بحيــث تتملكــه اجلمعيــة أو تتصــرف فيــه ملصلحتهــا‪ ،‬حكمــت‬\n‫احملكمــة باســتحقاق املدعيــن لوقــف بنــت ابــن املوقفــة وقــدره ســتة‬\n‫قراريــط وثلثــان مــن القيــراط وتســليم هــذا الوقــف لهــم كمــا رجعــت‬\n‫احملكمــة عمــا حكمــت بــه ســابق ًا مــن تســليم الوقــف جلمعيــة (‪،).....‬‬\n                                   ‫صــدق احلكــم ن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي باحملكمــة العامــة‬\n‫باملدينة ويف يوم الثالثاء املوافق ‪1429/12/25‬هـ حضر (‪ )......‬ســعودي‬\n‫اجلنسية أصالة عن نفسه ووكالة عن (‪ )......‬مبوجب الوكالة الصادرة‬\n‫مــن املدينــة يف ‪1433/2/10‬ه ـ جلــد ‪ 144‬حــال وكالتــه عــن كل مــن‬\n‫جميعهــم بالوكالــة الصــادرة مــن املدينــة يف ‪1423/2/18‬ه جلــد وأدعــى‬\n‫علــى احلاضــر معــه (‪ )......‬ســعودي اجلنســية الوكيــل الشــرعي بصفتــه‬\n‫رئيــس اجلمعيــة (‪ )......‬مبوجــب قــرار وزيــر الشــؤون اإلســامية واألوقــاف‬\n‫والدعــوة واإلرشــاد ‪/‬ق‪/‬م يف ‪1425/5/22‬ه ـ مبوجــب الوكالــة‬\n‫الصــادرة يف ‪1428/10/16‬ه ـ وقــدم املدعــي دعــواه احملــررة والتــي‬\n\n                                                                                 ‫‪6‬‬\n\f    ‫جــاء فيهــا انــه صــدر مــن فضيلتكــم صــك برقــم ‪ 10/1239/59‬يف‬\n    ‫‪1427/8/5‬ه ـ بتحويــل الوقــف العائــد لصالــح اجلمعيــة اخليريــة لتحفيــظ‬\n    ‫القــران الكــرمي مــن الناظــر املتنــازل املدعــو (‪ )......‬وهــو غيــر صحيــح‬\n    ‫لآلتــي‪ -1 :‬أن مــا ذكــره الناظــر (‪ )......‬يف أصــل التنــازل غيــر صحيــح‬\n    ‫مــن كونــه مــن ذريــة املــرأة املوقــف عليهــا وربــط نســبه بهــا علــى أن لديــه‬\n    ‫اليقــن وليــس لديــه بينــه أو صــك شــرعي يثبــت نســبه بهــا وأعطــى نفســه‬\n    ‫حــق التنــازل دون الرجــوع ألصحــاب احلــق املســتفيدين بــل نفــى وجــوب‬\n    ‫أنــه يســتطيع ربــط نســبه باملــرأة املوقــف عليهــا املذكــورة ونحــن نســبنا‬\n    ‫مثبــت بالصــك الصــادر مــن هــذه احملكمــة يف ‪1365/10/26‬هــ‪-2 .‬‬\n    ‫أن نظــارة اجلمعيــة للوقــف مخالفــه لشــرط الواقفــة حيــث أن الواقفــة‬\n    ‫حصــرت النظــر والواليــة علــى الواقــف املذكــور وإجــراء خيراتــه علــى‬\n    ‫نفســها مــدة حياتهــا ومــن بعدهــا للمصونــة (‪ )......‬املذكــورة ثــم مــن بعــد‬\n    ‫(‪ )......‬ينحصــر النظــر ألوالد (‪ )......‬وذريتهــا إلــى االنقــراض ثــم االقــرب‬\n    ‫فاألقــرب مــن اقاربهــا ملــن لهــم نظــر والواليــة لكائن مــن كان اخليار بني‬\n    ‫االســتغالل والســكني مبوجــب شــرط الواقفــة بالصــك عــام ‪1279‬ه ـ‬\n    ‫وعلــى مــا تقــدم نأمــل اعــادة النظــر يف نقــل الوقــف للجمعيــة حيــث أن‬\n    ‫الوقــف املذكــور لــه مســتحقون يصــرف عليهــم حســب شــرط الواقفــة‬\n    ‫حيــث أن صــرف ريعهــا علــى مســتحقيها وهــم مــن االقربــن أولــى وابلــغ‬\n    ‫يف الثــواب للواقفــة وملــا فيــه صلــة رحــم وصدقــه هكــذا قــرر دعــواه‬\n    ‫وبســؤاله حتريــر ًا لدعــواه عمــن آل لهــم االســتحقاق يف هــذا لوقــف قــال‬\n    ‫أن صــك الوقفيــة نــص علــى أنــه يــؤول مــن بعد املوقفة إلــى املصونة (‪)......‬‬\n    ‫ثــم مــن بعــد (‪ )......‬ينحصــر يف أوالد (‪ )......‬وذريتهــا حتــى االنقــراض وقــد‬\n    ‫توفيــت (‪ )......‬عــن عاصبهــا (‪ )......‬وأن تــويف عــن أختــه (‪ )......‬وأن (‪)......‬‬\n\n\n‫‪7‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":5,"source_page_end":7,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"150560ea1acf9697db9957d05bc625925e79cf84828b9fff7b4c3c375d07ddd1","normalized_text_hash":"31640c37be53763ee55b97d37f34fd3bf0732accdda43151753010cb2a9f21db","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p5-33439487"},{"id":"c614da37-156a-5762-bdc8-7d4187783ffb","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -كيفية توزيع غلة الوقف -اضطراب النظار يف كيفية توزيع نصيب من توفى عقيم ا وال ولد له -تدخل أحد املستحقني يف الدعوى لتضرره من إعادة التقسيم -عدم وجود نص يحدد كيفية إعادة تقسيم من ال ولد له -نصيب العقيم يعود إلى أصل الغلة عند عدم النص.","document_number":"3418295","case_number":"32175869","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"وقف -كيفية توزيع غلة الوقف -اضطراب النظار يف كيفية توزيع نصيب من توفى عقيم ا وال ولد له -تدخل أحد املستحقني يف الدعوى لتضرره من إعادة التقسيم -عدم وجود نص يحدد كيفية إعادة تقسيم من ال ولد له -نصيب العقيم يعود إلى أصل الغلة عند عدم النص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418295 :‬‬\n                   ‫َر ْق ُم الدعوى‪32175869 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34216589‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫وقــف ‪ -‬كيفيــة توزيــع غلــة الوقــف ‪ -‬اضطــراب النظــار يف كيفيــة‬\n‫توزيــع نصيــب مــن توفــى عقيمـ ًا وال ولــد لــه ‪ -‬تدخــل أحــد املســتحقني‬\n‫يف الدعــوى لتضــرره مــن إعــادة التقســيم ‪ -‬عــدم وجــود نــص يحــدد‬\n‫كيفيــة إعــادة تقســيم مــن ال ولــد لــه ‪ -‬نصيــب العقيــم يعــود إلــى أصــل‬\n                                                    ‫الغلــة عنــد عــدم النــص‪.‬‬\n\n\n\n\n‫‪ .1‬قــال يف تنقيــح احلامديــة املنصــوص عليــه يف اإلســعاف وغيــره « أنــه‬\n‫إذا ســكت عــن مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف الغلــة أي‬\n                  ‫ينقســم علــى جميــع املســتحقني أ‪.‬هــ‪ ».‬تنقيــح احلامديــة‪.‬‬\n‫‪ .2‬قــال يف اإلســعاف (ولــو قــال كلمــا حــدث املــوت علــى أحــد منهــم‬\n‫ا كان نصيبــه منهــا راجعـ ًا البطــن الــذي فوقــه‬   ‫ولــم يتــرك ولــد ًا أونسـ ً‬\n‫ومــات واحــد منهــم ولــم يكــن فوقــه أحــد أو لــم يذكــر يف ســهم مــن‬\n‫ميــوت عــن غيــر ولــد وال نســل شــيئ ًا فيكــون نصيبــه راجع ـ ًا إلــى أصــل‬\n                          ‫الغلــة وجاري ـ ًا مجراهــا)‪ .‬اإلســعاف الطرابلســي‪.‬‬\n\n\n\n\n‫أقــام رجــل دعــوى علــى ناظــر وقــف يطالبــه بإعطائــه جــزء مــن نصيــب‬\n‫احــد املســتحقني مــن الطبقــة األولــى لوفاتــه‪ ،‬صــادق املدعــى عليــه علــى‬\n\n                                                                                      ‫‪30‬‬\n\f     ‫الدعــوى ورفــض طلــب املدعــى ألن النظــار الســابقني كانــوا علــى نفــس‬\n     ‫الطريقــة فمــن مــات مــن املســتحقني مــن الطبقــة األولــى رجــع نصيبــه إلى‬\n     ‫ورثتــه ولــم يتطرقــوا إلــى مــن ال وارث لــه كالعقيــم الــذي يطالــب املدعــي‬\n     ‫بإعطائــه جــزء مــن نصيبــه وذكــر أن هــذا الوقــف علــى ثالثــة فــروع‬\n     ‫واملدعــي مــن أوالد أحــد الفــروع واملتوفــى هــو أحــد الفــروع وهــي امــرأة‬\n     ‫عقيــم والناظــر الســابق كان يقســم بــن أوالد الظهور والبطون بالســوية‬\n     ‫ومــن مــات بغيــر ولــد رجــع نصيبــه إلخوتــه وأن صــك الوقــف لــم يتطــرق‬\n     ‫للعقمــاء وأن نصيــب املــرأة العقيــم التــي هــي أحــد الفــروع يعطــى ألخيهــا‬\n     ‫الشــقيق واملدعــي يطالــب بإرجاعــه إلــى األصــل فيكــون الوقــف علــى‬\n     ‫فرعــن فقــط ال علــى ثالثــة‪ ،‬ثــم جــرى مداولــة بــن األطــراف يف تقســيم‬\n     ‫الغلــة وأصــر املدعــي أنــه يطالــب بــأن يعــاد نصيــب الفــرع العقيــم ألصــل‬\n     ‫الغلــة ويقســم بينهــم بالســوية وحضــر املشــرف علــى الوقــف بوصفــه أحــد‬\n     ‫املســتحقني للوقــف وطلــب إدخالــه يف الدعــوى وبعــد اطــاع احملكمــة‬\n     ‫علــى صــك الوقــف تبــن عــدم وجــود شــرط للواقــف وأن الغلــة تقســم‬\n     ‫أثالث ـ ًا وأن حصــة كل مســتحق تنتقــل ألوالده بعــد وفاتــه وألن الناظــر‬\n     ‫قــرر أن النظــار الســابقني كانــوا مضطربــن يف حصــة مــن توفــى عقيمـ ًا‬\n     ‫فأحيانــا يقســمونها بــن الورثــة وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن‬\n     ‫الراجــح عنــد العلمــاء أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع‬\n     ‫إليــه عنــد االختــاف فــإن حصــة مــن توفــى مــن غيــر ولــد تعــود إلــى أصــل‬\n     ‫الغلــة وبنــاء عليــه حكمــت احملكمــة بــأن حصــة مــن مــات بغيــر ولــد مــن‬\n     ‫املســتحقني تعــود إلــى أصــل الغلــة ويعــاد قســمتها بــن جميع املســتحقني‪،‬‬\n                                                   ‫صــدق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫‪31‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬مســاعد رئيــس احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم وتاريــخ ‪1432/05/15‬ه املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫‪1432/05/15‬ه ففــي يــوم االحــد املوافــق ‪1433/01/30‬ه ـ أفتتحــت‬\n‫اجللســة الســاعة (‪ )10 : 30‬وفيهــا حضــر (‪ )......‬ســجل مدنــي رقــم (‪)......‬‬\n‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ســجل مدنــي رقــم بصفتــه‬\n‫ناظــرا علــى وقــف مبوجــب صــك النظــارة الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 3/27/168‬يف ‪1429/12/18‬ه ـ قائــا يف تقريــر دعــواه إن‬\n‫املدعــى عليــه الناظــر يقــوم بصــرف مــا كان عائــدا لعمتــي (‪)......‬‬\n‫املتوفــاة عام‪1406‬ه ـ ألوالد أخيهــا (‪ )......‬وحرمنــا نحــن أوالد أخيهــا‬\n‫(‪ )......‬علمــا بــأن الناظــر الســابق كان يقســم مــا كان عائــدا لعمتنــا‬\n‫(‪ )......‬مــن الوقــف بــن ورثــة أخيهــا (‪ )......‬املتوفــى عام‪1400‬ه ـ وأنــا‬\n‫احدهــم وأخيهــا (‪ )......‬والــذي توفــى عام‪1411‬ه ـ علمــا بــأن الطبقــة‬\n‫العليــا قبلنــا قــد انقرضــت بوفــاة (‪ )......‬املتوفــاة عام‪1429‬ه ـ وانتقــل‬\n‫االســتحقاق للطبقــة التــي تليهــا وهــي طبقتنــا ل ـ ــذا اطلــب إلــزام املدعــى‬\n‫عليــه بقس ــمة االســتحقاق بالتســاوي بيننــا نحــن أوالد (‪ )......‬و(‪)......‬‬\n‫ولــدي (‪ )......‬النقــراض الطبقــة العليــا وانتقــال االســتحقاق للطبقــة التــي‬\n‫تليهــا هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه قــال إن الوقــف‬\n‫مــكان نظارتــي مقســم علــى ثالثــة فــروع فــرع (‪ )......‬ولــه الثلــث وفــرع‬\n‫(‪ )......‬ولــه الثلــث وفــرع (‪ )......‬الثلــث واملدعــي فرعــه (‪ )......‬وملــا اســتلمت‬\n‫الوقــف ودفاتــره وجــدت الناظــر الســابق كان يقســم بــن أوالد الظهــور‬\n\n                                                                                           ‫‪32‬‬\n\f     ‫وأوالد البطــون بالســوية ومــن مــات عــن وغيــر ولــد رجــع نصيبــه ألخوتــه‬\n     ‫وبعــد االطــاع علــى الصــك رقــم ‪ 569‬يف‪1378/4/15‬ه ـ الصــادر مــن‬\n     ‫هــذه احملكمــة اتضــح أن العمــل يف الوقــف جــار علــى انتقــال نصيــب‬\n     ‫كل مســتحق ألوالده ولــم يتطــرق للعقمــاء وأنــا اصــرف نصيــب (‪)......‬‬\n     ‫ألوالد (‪ )......‬دون أوالد (‪ )......‬حســب عمــل الناظــر الســابق يف إعــادة‬\n     ‫نصيــب العقيــم ألخيــه يف فــرع (‪ )......‬فقمــت بإعطــاء عائــد (‪ )......‬إلــى‬\n     ‫أوالد أخيهــا (‪ )......‬توحيــدا لإلجــراء علمــا بــأن الناظــر الســابق كان‬\n     ‫يعطــي عائــد (‪ )......‬ألوالد (‪ )......‬و(‪ )......‬بالســوية بينهــم علمــا بأنــه ال‬\n     ‫يوجــد شــرط واقــف وإمنــا جريــان عمــل هـ ــكذا أجــاب وقــد جــرى‬\n     ‫االطــاع علــى الصــك رقــم ‪ 569/568‬يف ‪1378/4/15‬ه ـ الصــادر مــن‬\n     ‫هــذه احملكمــة فوجــد يتضمــن اإلنهــاء بــان العــزل اخلمســة الكائنــة‬\n     ‫بــ(‪ )......‬احملــروس كانــت منحصــرة يف املرحــوم الشــيخ (‪ )......‬ومــن‬\n     ‫بعــده يف أوالده إلــى أن انحصــر يف ثــاث مــن ذريتــه وهــم (‪ )......‬ويف‬\n     ‫(‪ )......‬املذكــور ويف (‪ )......‬وان كان العمــل جــاري علــى قســمة هــذا‬\n     ‫الوقــف بــن مســتحقني يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى‬\n     ‫أوالده وقــد عمــل بهــذا العمــل جملــة من نظار هــذا الوقف وهم (‪)00000‬‬\n     ‫و(‪ )......‬و(‪ )......‬وقــد انحصــر الوقــف املذكــور واآلن يف املكرمــن‬\n     ‫الشــيخ (‪ )......‬واملصونــة (‪ )......‬املذكــور و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬أوالد املرحــوم (‪ )......‬ويف الشــيخ (‪ )......‬و(‪ )......‬و(‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬أوالد املرحــوم (‪ )......‬و(‪ )......‬املذكــورة و(‪ )......‬و(‪)......‬‬\n     ‫ابنــي املرحــوم (‪ )......‬فانتقــل نصيــب كل مــن (‪ )......‬و(‪ )00000‬ولــدي‬\n     ‫(‪ )......‬و(‪ )......‬ألوالده ‪.‬أ‪.‬ه ـ ويف جلســة أخــرى لــدي أنــا (‪ )......‬القائــم‬\n     ‫بعمــل مكتــب مســاعد رئيــس احملكمــة العامــة (‪ )......‬بنــاء علــى خطاب‬\n\n\n‫‪33‬‬\n\f‫فضيلــة رئيــس احملكمــة برقــم ‪ 33619201‬يف ‪1433/4/3‬ه ـ حضــر‬\n‫املدعــي كمــا حضــر املدعــى عليــه نظــارة وجــرى تــاوة الســابق ضبطــه‬\n‫علــى الطرفــن فصادقــا عليــه فطلبــت مــن املدعــى عليــه صــك النظــارة‬\n‫وجميــع صكــوك الوقــف املوجــودة لديهــم فأبــرز الصــك الصــادر مــن‬\n‫محكمــة مكــة برقــم ‪ 569/568‬يف ‪1330/4/15‬ه ـ وباالطــاع عليــه‬\n‫وجــد انــه يتضمــن اإلنهــاء بــان العــزل اخلمســة الكائنــة بالطائــف‬\n‫احملــروس كانــت منحصــرة يف املرحــوم الشــيخ (‪ )......‬ومــن بعــده يف‬\n‫أوالده إلــى أن انحصــر يف ثــاث مــن ذريتــه وهــم (‪ )......‬ويف (‪ )......‬ويف‬\n‫(‪ )......‬وان كان العمــل جــاري علــى قســمة هــذا الوقــف بــن مســتحقني‬\n‫يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا‬\n‫العمــل جملــة مــن نظــار هــذا الوقــف وهــم (‪ )......‬و(‪ )......‬و(‪ )......‬وقــد‬\n‫انحصــر الوقــف املذكــور واآلن يف املكرمــن الشــيخ (‪ )......‬واملصونــة‬\n‫(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد املرحــوم‬\n‫(‪ )......‬ويف الشــيخ (‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬أوالد املرحــوم (‪ )......‬و‬\n‫(‪ )......‬املذكــورة و(‪ )......‬و (‪ )......‬ابنــي املرحــوم (‪ )......‬فانتقــل نصيــب‬\n‫كل مــن (‪ )......‬و(‪ )......‬ولــدي (‪ )......‬و(‪ )......‬ألوالده ‪ .‬ثــم أقــام فضيلــة‬\n‫حاكمــه (‪ )......‬ناظــر علــى هــذا الوقــف إ‪-‬ه ـ كمــا ابرز الصــك الصادر‬\n‫مبحكمــة الطائــف برقــم ‪ 59/2‬يف ‪1377/3/5‬ه ـ وباالطــاع عليــه‬\n‫وجــدت فضيلــة حاكمــه قــد أشــار إلــى عمــل النظــار املــدون يف الصــك‬\n‫املشــار إليــه بعاليــة رقــم ‪ 569‬يف ‪1330/4/15‬ه ـ ثــم أقــام (‪ )......‬ناظــرا‬\n‫علــى هــذا الوقــف و(‪ )......‬مشــرفا عليــه أ‪.‬ه ـ كمــا أبــرز الصــك الصــادر‬\n‫مــن احملكمــة العامــة بــ(‪ 3/27/168 )......‬يف ‪1429/12/18‬ه ـ‬\n‫وباالطــاع عليــه وجــدت أن فضيلــة حاكمــه اطلــع علــى الصــك املشــار‬\n\n\n                                                                                          ‫‪34‬‬\n\f     ‫إليــه بعاليــة رقــم ‪ 59‬يف ‪1377/3/5‬ه واملشــار فيــه إلــى عمــل النظــار‬\n     ‫املــدون بالصــك رقــم ‪ 569‬يف‪1330/4/15‬ه ـ ثــم أقــام (‪ )......‬ناظــرا عــن‬\n     ‫هــذا الوقــف (‪ )......‬مشــرفا عليــه أ‪.‬ه ـ فجــرى ســؤال الناظــر هــل يوجــد‬\n     ‫صكــوك أخــرى للوقــف أو دعــاوى مــن املســتحقني ســابقه فيــه فقــال ال‬\n     ‫يوجــد ســوى هــذه الصكــوك وال يوجــد دعــاوى مــن املســتحقني ســابقه‬\n     ‫هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــال صحيــح مــا ذكــره املدعــى‬\n     ‫عليــه نظــار فــا يوجــد ســوى هــذه الصكــوك كمــا جرى ســؤال املدعى‬\n     ‫عليــه نظــارة عــن عمــل النظــار الســابقني بخصــوص مــن كان عقيمــا‬\n     ‫مــن املســتحقني فقــال فيــه تفصيــل وأبــرز ورقــة نصها (جوابنــا بخصوص‬\n     ‫النظــر يف عمــل النظــار الســابقني لطريقــة تقســيم حصــة العقيــم يف‬\n     ‫وقــف (‪ )......‬ب ــالـ(‪ )......‬أو ًال ‪ .‬قــد تولــت نظــارة هــذا الوقــف (‪ )......‬يف‬\n     ‫‪1330/4/15‬ه ـ إلــى حــن وفاتهــا عــام ‪1356‬ه ـ ولــم نعلــم شــيء مــن‬\n     ‫دفاتــره او ًال طريقــة تقســيم (‪ )......‬يف زمانهــا عبــر ســؤال كبــار‬\n     ‫املســتحقني يف هــذا الوقــف ثاني ـ ًا ‪ :‬أهمــل الوقــف مــن بعــد وفاتهــا وقــد‬\n     ‫اســتولى بعــض املســتأجرين علــى هــذا الوقــف إلــى أن قــام (‪ )......‬و (‪)......‬‬\n     ‫بإعــادة هــذا الوقــف وإجرائــه يف مجــراه حســب صــك هــذه الوقفيــة‬\n     ‫وبالرجــوع إلــى بعــض الدفاتــر املتفرقــة التــي ســألنا عنهــا أخيــرا عنــد‬\n     ‫أبنــاء الناظــر الســابق فوجدنــا طريقــة تقســيم هــذا الوقــف كالتالــي ‪.‬‬\n     ‫تقســم الغلــة إلــى ثالثــة أثــاث الثلــث األول ألبنــاء (‪ )......‬وهــم (‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬فمــات (‪ )......‬عقيــم فأعطــى حصتــه ألخيــه (‪ )......‬ورقيــة‬\n     ‫وتسلســل يف العطــاء ألبنائهمــا بإعطــاء كل مــن مــات عــن ولــد فلولــده‪.‬‬\n     ‫ثــم جمــع نصيــب العقمــاء التســعة ووزع مبالغهــم علــى نصفــن نصــف‬\n     ‫منهــا لــ(‪ )0000‬مــن طــرف (‪ )0000‬والنصــف اآلخــر ألبنــاء (‪ )0000‬وهــم‬\n\n\n‫‪35‬‬\n\f‫(‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬و(‪ .)......‬علمـ ًا بــأن العقمــاء التســعة ســبعة‬\n‫منهــم مــن طــرف (‪ )......‬واثنــان مــن طــرف (‪ )......‬ومــع ذلــك كلــه قــام‬\n‫بجمــع التســعة العقمــاء وقســمتها علــى نصفــن ويف هــذا نظــر‪ .‬والثلــث‬\n‫الثانــي ألبنــاء (‪ )......‬وهــم (‪ )......‬و (‪ )......‬و (‪ )......‬فماتــت (‪ )......‬عــن‬\n‫(‪ )......‬وماتــت (‪ )......‬وأعطــت حصتهــا إلــى بنــت خالهــا (‪ )......‬والــى‬\n‫خالتهــا (‪ )......‬وذلــك باعتبــار إرجــاع حصتهــا ألصــل هــذا الفــرع وبعــد أن‬\n‫أخــذ يف توزيــع املبلــغ علــى مســتحقيها األحيــاء منهــم واألمــوات بــان‬\n‫يعطــي كل مــن مــات عــن ولــد لولــده جمــع نصيــب العقمــاء الســبعة وقــام‬\n‫بتوزيعهــا علــى اخلمســة األحيــاء بالســوية بينهــم‪ .‬وهــذا خــاف مــا قــام بــه‬\n‫يف فــرع (‪ )......‬أعــاه حيــث أعطــى نصــف مــال جميــع العقمــاء (‪ )......‬مــن‬\n‫طــرف (‪ )......‬والنصــف اآلخــر للخمســة األحيــاء مــن ورقــة (‪ . )......‬ويف‬\n‫هــذا نظــر أيضــا ألن املتوفــن عقمــاء يف طــرف (‪ )......‬ســتة عقمــاء بينمــا‬\n‫يف طــرف (‪ )......‬عقيمــة واحــدة فكيــف تكــون هنــا املســاواة‪ .‬والثلــث‬\n‫الثالــث ألبنــاء (‪ )......‬وهــم (‪ )......‬و(‪ )......‬و(‪ )......‬فماتــت (‪ )......‬وأعطــى‬\n‫نصيبهــا ألخويهــا الشــقيقني ووزع املبالــغ علــى كل املســتحقني األحيــاء‬\n‫منهــم واألمــوات ثــم جمــع نصيــب العقمــاء الثالثــة أثنــن منهــم مــن طــرف‬\n‫(‪ )......‬وواحــدة مــن طــرف (‪ )......‬وقــام بتوزيــع مبالــغ الثالثــة العقمــاء‬\n‫ووزعهــا علــى نصفــن النصــف األول لورثــة (‪ )......‬مــن فــرع (‪)......‬‬\n‫والنصــف الثانــي لورثــة (‪ )......‬و(‪ )......‬مــن فــرع (‪ )......‬ثــم قــام بتوزيــع‬\n‫حصــة (‪ )......‬العقيــم مــن فــرع (‪ )......‬لورثــة (‪ )......‬ولورثــة (‪ )......‬األحيــاء‬\n‫منهــم دون ترتيــب يف ذلــك وتوالــت االضطرابــات كمــا هــو موجــود‬\n‫لديكــم يف صــورة الدفتــر لعــام ‪1415‬ه ـ ) أ‪ .‬ه ـ وبعــرض الورقــة علــى‬\n‫املدعــي رده بورقــة هــذا نصهــا ( بعــد االطــاع علــى جميــع مــا قدمــه‬\n\n\n                                                                                             ‫‪36‬‬\n\f     ‫الناظــر علــى الوقــف (‪ )......‬أفيدكــم مبــا يلــي ‪ /1‬حســب مــا يدعيــه مــن‬\n     ‫وجــود اضطرابــات يف عمــل الناظــر الســابق (لــم يتــم العمــل علــى تعديلهــا‬\n     ‫وال زال العمــل بهــا مســتمر إلــى اآلن ) ‪ /2‬حســب إفادتــه الســابقة (أنــه‬\n     ‫مــن دفتــر الناظــر الســابق مــن لــم يكــن لــه إخــوة فيرجــع نصيبــه إلــى‬\n     ‫ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم) لــم يتــم العمــل بذلــك بــل ومت‬\n     ‫حرماننــا‪ / 3 .‬إقــرار املشــرف بأنــه املتســبب يف خطــأ التقســيم بحرمــان‬\n     ‫ورثــة املرحــوم (‪ )......‬مــن نصيــب املرحومــة (‪ )......‬وانتقالــه إلــى ورثــة‬\n     ‫(‪ )......‬ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل النظــار ومتاشــي ًا مــع‬\n     ‫العــرف املتبــع علــى أن (مــن مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي‬\n     ‫طبقتــه أو ألصــل الغلــة) وذلــك لعمــوم الفائــدة علــى بقيــة املســتحقني‬\n     ‫اآلخريــن فانــي أهيــب بفضيلتكــم املوقــرة إلــزام الناظــر احلالــي إعــادة‬\n     ‫تقســيم مــا يخــص عائلــة (‪ )......‬بالتســاوي بينهــم نظــرا لوفــاة جميــع‬\n     ‫أصحــاب الطبقــة الســابقة بوفــاة آخــر املســتحقني فيهــا وهــي (‪ )......‬يف‬\n     ‫عــام ‪1429‬ه ـ ونشــوء طبقــة جديــدة وهــم أبنــاء (‪ )......‬و (‪ ))......‬إ‪ -‬ه ـ‬\n     ‫وبعــرض هــذه الورقــة علــى املدعــى عليــه نظــارة ابــرز رده بورقــه هــذا‬\n     ‫نصهــا (أجيــب فضيلتكــم علــى دعــوى املدعــي (‪ )......‬واملقيــدة لديكــم‬\n     ‫برقــم (‪ )......‬وتاريــخ ‪1432/5/15‬ه ـ علــى مــا قدمه يف جلســة يوم االثنني‬\n     ‫‪1433/6/23‬ه يف مــا يلــي ‪ :‬أو ًال بخصــوص طلبــه إعــادة تقســيم ما يخص‬\n     ‫عائلــة (‪ )......‬فــرع (‪ )......‬يف هــذا الوقــف بقســمته بــن ابنــي (‪ )......‬و‬\n     ‫(‪ )......‬بالتســاوي بينهــم حســب مــا ميثلونــه مــن طبقــة جديــدة مــن‬\n     ‫املســتحقني‪ .‬أفيــد فضيلتكــم بــأن هــذا الوقــف غيــر طبقــي فــا نقــض‬\n     ‫للقســمة هنــا لعــدم النقــض يف شــرط الوقــف ولعــدم النقــض يف عمــل‬\n     ‫النظــار الســابقني وإمنــا كان تقســيم غلــة هــذا الوقــف علــى النحــو‬\n\n\n‫‪37‬‬\n\f‫التالــي‪( -:‬أ)‪ :‬حســب صــك الوقــف رقــم (‪ )569‬فى‪1330/4/15‬ه ـ‬\n‫الصــادر مــن محكمــة مكــة املكرمــة والــذي جــاء فيــه (أن الوقــف‬\n‫منحصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده إلــى أنــا نحصــر إلــى ثــاث‬\n‫مــن ذريتــه وهــم ‪ )......( :‬ويف (‪ )......‬ويف ســلم(‪ )......‬وأنــه كان العمــل‬\n‫جــارى علــى قســمة هــذا الوقــف بــن مســتحقيه يف كل زمــان بانتقــال‬\n‫نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا الصــك جملــة مــن‬\n‫نظــار هــذا الوقــف)‪(.‬ب)‪ :‬أن يســتمر يف تقســيم الغلــة إلــى ثالثــة أثــاث‬\n‫الثلــث األول مــن الغلــة لورثــة (‪ )......‬والثلــث الثانــي لورثــة (‪ )......‬والثلــث‬\n‫الثالــث لورثــة (‪( .)......‬ج)‪ :‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور‬\n‫وأوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق (وأن مــن مــات‬\n‫عــن غيــر ولــد فنصيبــه إلخوتــه حســب مــا جــاء يف صفحتــي ‪ 10‬و ‪ 11‬مــن‬\n‫دفتــر الناظــر الســابق لفــرع (‪ )......‬وبعــد مشــاورتي للمشــرف علــى تطبيق‬\n‫هــذا التقســيم لفــرع (‪ )......‬وفــرع (‪ )......‬بــدال مــن االضطرابــات التــي‬\n‫وقــع فيهــا الناظــر الســابق (‪ )......‬يرحمــه اهلل ‪ -‬ولتطابــق هــذا يف كثيــر‬\n‫مــن شــروط الواقفــن أيدنــى علــى ذلــك وعــدم إغفالنــا ملــن لــم يكــن لــه‬\n‫إخــوة فيرجــع نصيبــه إلــى ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا‬\n‫جــاء يف الدفتــر ص‪ ) 8‬وحيــث أن املســتحقني لفــرع (‪ )......‬انحصــر يف‬\n‫أوالد (‪ )......‬وعددهم تســعة أشــخاص ويف أوالد (‪ )......‬وعددهم خمســة‬\n‫أشــخاص‪ ،‬وأن وفــاة (‪ )......‬كان قبــل وفــاة أختــه (‪ )......‬وقــد انتقــل‬\n‫نصيبهــا إلــى أخيهــا (‪ )......‬ممــا زاد يف حصــص املســتحقني مــن أوالد‬\n‫(‪ )......‬وأن عددهــم أقــل مــن عــدد أوالد (‪ )......‬ممــا جعــل نصيــب املدعــي‬\n        ‫أقل من نصيب أوالد عمه (‪ )......‬هذا ما دفع املدعى إلقامة دعواه‬\n‫ثانيـاً‪ :‬علــى املدعــى التأمــل يف تطبيــق طريقــة القســمة مــن عدمهــا أعــاه‬\n\n\n                                                                                          ‫‪38‬‬\n\f     ‫ليتأكــد مــن أن هــذه االضطرابــات قــد أزيلــت أم ال ؟ عليــه نرجــوا مــن‬\n     ‫فضيلتكــم التوجيــه مبــا ترونــه حيــال حصــة العقيــم) وبعــرض ذلــك‬\n     ‫علــى املدعــي ابــرز رده بورقــه هــذا نصهــا بعــد االطــاع والتأمــل يف جميــع‬\n     ‫الــردود التــي قدمهــا الناظــر علــى الوقــف أفيدكــم باعتراضــي وعــدم‬\n     ‫قناعتــي الن جميــع أعمالــه يف قســمة عائلــة مــن تلقــاء نفســه دون الرجــوع‬\n     ‫إلــى أي اســتناد وكمــا تعلمــون فضيلتكــم أنــه ال يوجــد شــرط للوقــف‬\n     ‫وهــذا خــاف مــا يدعيــه يف جميــع ردوده ‪ ،‬وحتى بعــد املراجعة والتدقيق‬\n     ‫يف عمــل الناظــر الســابق يف قســمة عائلــة (‪ )......‬لــم يوجــد حرمــان بــل‬\n     ‫وزعــت حصــة العقيــم بالتســاوي واســتمر بالعمــل علــى ذلــك حتــى مــن‬\n     ‫بعــد وفاتــه ‪.‬لذلــك ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل النظــار‬\n     ‫ومتاشــيا مــع العــرف املتبــع يف كثيــر مــن شــروط الواقفــن علــى أن «مــن‬\n     ‫مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي طبقتــه أو ألصــل الغلــة «ولعمــوم‬\n     ‫الفائــدة ولتحيــق العدالــة بيننــا‪ ،‬فإنــي أطلــب مــن فضيلتكــم املوقــرة‬\n     ‫إلــزام الناظــر احلالــي إعــادة تقســيم مــا يخــص عائلــة (‪ )......‬بالتســاوي‬\n     ‫بينهــم نظــرا لوفــاة جميــع أصحــاب الطبقــة الســابقة بوفــاة أخــر‬\n     ‫املســتحقني فيهــا وهــي يف عــام ‪1429‬ه ونشــوء طبقــة جديــدة وهــم أبنــاء‪.‬‬\n     ‫كمــا حضــر (‪ )......‬ســجل مدنــي رقــم (‪ )......‬وهــو املشــرف علــى والناظر‬\n     ‫مبوجب الصك الصادر من احملكمة العامة (‪ )......‬برقم ‪3/27/168‬يف‬\n     ‫‪1429/12/18‬ه كمــا حضــر بالســجل املدنــي رقــم (‪ )......‬بالســجل‬\n     ‫املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم‬\n     ‫(‪ )......‬وقــرروا جميعــا قائلــن أننــا مــن املســتحقني يف هــذا الوقــف ونقــرر‬\n     ‫بــان حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني ســواء كان عقيمــا أو‬\n     ‫لــم يتــزوج فإنهــا تصــرف إلخوانــه مــن املســتحقني هكــذا قــرروا جميعــا‬\n\n\n‫‪39‬‬\n\f‫إ‪.‬ه ـ ثــم قــرر املدعــى عليــه نظــاره أن جميــع املســتحقني مــن الفــروع‬\n‫الثالثــة يقــررون أن حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني تكون‬\n‫إلخوانــه ولكنهــم ال يســتطيعون احلضــور لديكــم واطلــب إمهالــي‬\n‫إلحضــار إقــرارا منهــم بذلــك هكــذا قــرر وبعــرض ذلــك علــى املدعــي‬\n‫قــال أنــي ال أوافــق علــى مــا قــرره الناظــر واحلاضــرون مــن املســتحقني الن‬\n‫حصــة العقيــم والــذي ليــس لــه ذريــة مــن املســتحقني يرجــع ألصــل الثلــث‬\n‫وليــس إلخــوة امليــت هكــذا قــرر ويف جلســة أخــرى حضــر املدعــي (‪)......‬‬\n‫أصالــة كمــا حضــر املدعــى عليــه (‪ )......‬نظــارة كمــا حضــر كل مــن‬\n‫(‪ )......‬الســجل املدني رقم (‪ )......‬و (‪ )......‬بالســجل املدني (‪ )......‬و(‪)......‬‬\n‫وقــرروا جميعــا قائلــن إننــا أوالد ونحــن مــن املســتحقني يف هــذا الوقــف‬\n‫وكان والدنــا وعمنــا (‪ )......‬وعمتنــا (‪ )......‬مســتحقني يف الوقــف‬\n‫ويســتلمون اســتحقاقهم مــن الناظــر الســابق (‪ )......‬يــوزع عليهــم‬\n‫االســتحقاق بالتســاوي بينهــم وملــا توفيــت (‪ )......‬عقيمــا كان يقســم‬\n‫اســتحقاقها علــى أخويهــا (‪ )......‬و(‪ )......‬واســتمر العمــل علــى ذلــك بعــد‬\n‫وفــاة والدنــا وعمنــا ثــم تولــى هــذا الناظــر النظــارة واســتمر علــى هــذا‬\n‫العمــل ملــدة ســنتني وبعــد ذلــك اختلفــت القســمة وأصبــح يعطــى كامــل‬\n‫حصــة عمتنــا (‪ )......‬ألوالد عمنــا (‪ )......‬ويحرمنــا منهــا وملــا اعترضنــا‬\n‫عليــه قــال إن (‪ )......‬توفيــت بعــد والدكــم وحصتهــا تكــون ألخيهــا‬\n‫الــذي تــويف بعدهــا وهــو (‪ )......‬وأمــا مــن تــويف قبلهــا فــا يأخــذ شــيئا‬\n‫وبنــاء علــى ذلــك تقــدم أخونــا ‪ .....‬بهــذه الدعــوى ونحــن نطلــب إعــادة‬\n‫القســمة علــى مــا كانــت عليــه بقســمة حصــة العقيــم علــى أخــوة امليــت‬\n‫بالتســاوي هكــذا قــرروا وبعــرض ذلــك علــى املدعــى عليــه نظــارة‬\n‫فالصحيــح مــا ذكــره املدعــي وإخوانــه احلضــور فقــد كان الناظــر‬\n\n\n                                                                                     ‫‪40‬‬\n\f     ‫الســابق مضطــرب يف العمــل يف هــذا الفــرع وهــو فــرع (‪ )......‬كان‬\n     ‫يصــرف حصــة العقيــم إلــى أصــل الثلــث ويوزع بالتســاوي بني املســتحقني‬\n     ‫بينمــا يف الفرعــن اآلخريــن وهمــا فــرع (‪ )......‬وفــرع (‪ )......‬حيــث كان‬\n     ‫يجعــل حصــة العقيــم إلخوانــه فقــط دون بقيــة املســتحقني يف الفــرع هــذا‬\n     ‫إذا كان للعقيــم إخــوة وإذا لــم يكــن لــه إخــوة أعــاد حصــة العقيم ألصل‬\n     ‫الثلــث وقســمه بالتســاوي بــن املســتحقني وملــا توليــت النظــارة اســتمريت‬\n     ‫علــى هــذا العمــل ملــدة ســنة واحدة فقط وقمت بعمل شــباكا الســتحقاق‬\n     ‫مــن واقــع الدفاتــر لــكل فــرع وظهــر لــي االضطــراب وجعلــت عمــل‬\n     ‫الناظــر الســابق يف فرعــي (‪ )......‬و(‪ )......‬هــو األصــل وعملــت بــه يف فــرع‬\n     ‫(‪ )......‬الــذي ينتمــي إليــه املدعــي وإخوانــه وبنــاء عليــه وملــا كان والــد‬\n     ‫املدعــن قــد تــويف قبــل أختــه (‪ )......‬العقيمــة فإنــه ال يســتحق شــيئا مــن‬\n     ‫اســتحقاقها وإمنــا يكــون اســتحقاقها ألخيهــا (‪ )......‬الــذي توفيــت وهــو‬\n     ‫حــي ولــذا فــإن اســتحقاقها أصبــح ألوالد (‪ )......‬وحدهم دون أوالد (‪)......‬‬\n     ‫هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــي واخوانــه قالــوا إننــا نطلــب‬\n     ‫أعــادة قســمة حصــة العقيــم (‪ )......‬علــى إخوانهــا فمــن كان حيــا اخــذ‬\n     ‫حصتــه ومــن كان ميتــا أعطيــت حصتــه ألوالده هكــذا قــرروا ثــم ابــرز‬\n     ‫املدعــى عليــه نظــارة أوراق إقــرارات مــن املســتحقني يف الوقــف وهــذا‬\n     ‫نصهــا (نقــر نحــن املســتحقني لوقــف (‪ )......‬بالطائــف فــرع (‪ )......‬وفــرع‬\n     ‫(‪ )......‬بــأن يكــون تقسيـ ــم غلــة الوقــف علــى النحــو التالــي‪ -:‬أ‪ -‬حســب‬\n     ‫صــك الوقــف رقــم ‪569‬يف‪1330/4/15‬ه الصــادر مــن محكمــة (‪)......‬‬\n     ‫والــذي جــاء فيــه أن الوقــف منحصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده‬\n     ‫إلــى أن انحصــر إلــى ثــاث مــن ذريتــه وهــم (‪ )......‬ويف (‪ )......‬ويف (‪)......‬‬\n     ‫وانــه كان جــاري علــى قســمة هــذا الوقــف بــن مســتحقيه يف كل زمــان‬\n\n\n‫‪41‬‬\n\f‫بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا الصــك جملــة‬\n‫مــن نظــار هــذا الوقــف ب‪ -‬أن يســتمر يف تقســيم الغلــة إلــى ثــاث أثــاث‬\n‫الثلــث األول مــن الغلــة لورثــة (‪ )......‬والثلــث الثانــي لورثــة (‪ )......‬والثلــث‬\n‫لورثــة (‪ . )......‬ت‪ -‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور وأوالد‬\n‫البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق وان مــن مــات مــن غيــر‬\n‫ولــد فنصيبــه ألخواتــه حســب مــا جــاء يف صفحتــي (‪10‬و‪ )11‬مــن دفتــر‬\n‫الناظــر الســابق لفــرع (‪ )......‬ومــن لــم يكــن لــه إخــوة فيرجــع نصيبــه إلــى‬\n‫ثلــث ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا جــاء يف الدفتــر ص‪8‬‬\n‫‪.‬املســتحقني املوقعــن هــم (‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و‬\n‫(‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و‬\n‫(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و(‪ )......‬و (‪ )......‬و‬\n‫(‪)......‬و (‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬أوالد (‪)......‬‬\n‫و (‪ )......‬و (‪ )......‬بنتــي (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪ )......‬أوالد (‪.)......‬‬\n‫و(‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬ابنــي (‪ )......‬و‬\n‫(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و (‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و (‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬أوالد و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و و(‪)......‬‬\n‫أوالد (‪ ) )......‬أ‪.‬ه ـ وبعــرض هــذه اإلقــرارات علــى املدعــي قــال اطلــب‬\n‫تزويــدي بصــورة منهــا وإمهالــي لالطــاع عليهــا وجــرى تســليم املدعــي‬\n\n\n                                                                                                ‫‪42‬‬\n\f     ‫صــورة منهــا ثــم قــرر احلاضــر (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد‬\n     ‫(‪ )......‬بأننــا نــوكل أخانــا املدعــي يف مواصلــة هــذه الدعــوى وحضــور‬\n     ‫جميــع اجللســات واملرافعــة واملدافعــة وتقــدمي البينــات والــرد عليهــا‬\n     ‫والقناعــة واالعتــراض وتقــدمي الالئحــة االعتراضيــة حتــى اكتســاب‬\n     ‫احلكــم القطعيــة هكــذا قــرروا وقــرر احلاضــر ‪ .....‬موافقتــه علــى ذلــك‪.‬‬\n     ‫ويف جلســة أخــرى حضــر املدعــي أصالــة ووكالــة كمــا حضــر املدعــى‬\n     ‫عليــه نظــارة حــال حضــور (‪ )......‬وقــرر رفقــي أن الناظــر الســابق كان‬\n     ‫مضطربــا يف تقســيم حصــة العقيــم أو الــذي توفــى عــن غيــر ولــد فأحيانا‬\n     ‫يعيدهــا إلــى أصــل الغلــة كمــا فعــل يف (‪ )000‬ومــن قبلهــا مــن العقمــاء‬\n     ‫حيــث كان يجمــع حصــة العقمــاء ويعيــد قســمتها علــى املســتحقني‬\n     ‫بالتســاوي وحينمــا توفيــت (‪ )......‬لــم يفعــل ذلــك وإمنــا أعطــى اســتحقاقها‬\n     ‫ألختهــا الشــقيقة (‪ )......‬ولــم يعــط بقيــة املســتحقني شــيئا هكــذا قــرر‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــي واملدعــى عليــه قــاال صحيــح مــا ذكــره‬\n     ‫احلاضــر (‪ )0......‬فالناظــر الســابق كان مضطربــا يف قســمة حصــة‬\n     ‫العقيــم ومــن لــم يخلــف أوالد ًا هكــذا قــررا‪ .‬وبســؤال الطرفــن هــل‬\n     ‫لديهــم مــا يضيفانــه يف هــذه القضيــة فقــاال ليــس لدينــا ســوى مــا قدمنــاه‬\n     ‫‪.‬هكــذا قــاال ويف جلســة أخــرى حضــر املدعــي كمــا حضــر املدعــي‬\n     ‫عليــه نظــارة وبســؤال الطرفــن هــل لديهمــا مــا يضيفانه يف هــذه القضية‬\n     ‫فقــال املدعــي أننــي ســبق أن ذكــرت يف دعــواي إننــي اطلــب إعــادة‬\n     ‫قســمة الغلــة بــن املســتحقني بالتســاوي وتبــن لــي أن عمــل النظــارة‬\n     ‫الســابقني هــو إعطــاء حصــة كل مســتحق ألوالده ولــذا فــا مطالبــة لــي‬\n     ‫فيمــا يخــص ذلــك وإمنــا مطالبتــي هــي فيمــا يخــص حصــة العقيــم بــأن ال‬\n     ‫تصــرف ألحــد دون أحــد مــن املســتحقني وإمنــا تعــود ألصــل الغلــة هكــذا‬\n\n\n‫‪43‬‬\n\f‫قــرر وبعــرض ذلــك علــى املدعــي عليــه نظــارة قــال ليــس لــدي ســوى مــا‬\n‫قدمتــه بــأن حصــة العقيــم قــد اضطــرب فيهــا النظــار الســابقون ففــي‬\n‫ثلثــن تعطــى حصــة العقيــم ومــن توفــى عــن غيــر ولــد إلخوانــه ويف الثلــث‬\n‫الــذي ينتمــي إليــه املدعــي فــإن الناظــر الســابق كان يعطــي حصــة‬\n‫العقيــم ومــن مــات عــن غيــر ولــد إلخوانــه ثــم بعــد ذلــك إعــادة إلــى أصــل‬\n‫الغلــة ثــم رجــع وأعطــاه إلخــوة املتــويف حســب مــا بينتــه لكــم ســابقا‬\n‫هكــذا قــرر وقــد حضــر املشــرف علــى الناظــر (‪ )......‬ســجل مدنــي رقــم‬\n‫(‪ )0......‬مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪3/27/168‬‬\n‫يف ‪1429/12/18‬ه ـ وقــرر قائــا إننــي اطلــب إدخالــي يف هــذه القضيــة‬\n‫وأنــا أطلــب العمــل بإعطــاء حصــة مــن توفــى عــن غيــر ولد من املســتحقني‬\n‫إلخوتــه يف كل ثلــث ألنــه ال يوجــد شــرط واقــف يف هــذا الوقــف وإمنــا‬\n‫أكثــر عمــل النظــار علــى ذلــك هكــذا قــرر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وبعــد اإلطــاع علــى صكــوك هــذا الوقــف وألنــه‬\n‫تبــن عــدم وجــود شــرط واقــف لــدى نظــار هــذا الوقــف وأن غلــة هــذا‬\n‫الوقــف تقســم أثالث ـ ًا علــى الوصــف املشــار إليــه بعاليــه وأن حصــة كل‬\n‫مســتحق تنتقــل إلــى أوالده وألن الناظــر قــرر أن النظــار الســابقني كانوا‬\n‫مضطربــن يف حصــة مــن تــويف عقيمــا أوعــن غيــر ولــد فأحيانــا كانــوا‬\n‫يقســمونها بــن إخوتــه وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن الراجــح‬\n‫عنــد أهــل العلــم أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع إليــه‬\n‫عنــد االختــاف فــإن حصــة مــن توفــى عــن غيــر ولــد تعــود ألصــل الغلــة‬\n‫قــال يف تنقيــح احلامديــة املنصــوص عليــه عندنــا يف االســعاف وغيــره أنــه‬\n‫إذا ســكت عــن حكــم مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف‬\n‫الغلــة أي ينقســم علــى جميــع املســتحقني أ‪.‬ه ـ ينظــر تنقيــح احلامديــة‬\n\n\n                                                                                       ‫‪44‬‬\n\f     ‫‪ 382/2‬واالســعاف يف أحــكام األوقــاف للطرابلســي صحيفــة ‪106‬‬\n     ‫وقــال يف االســعاف ولــو قــال كلمــا حــدث املــوت علــى احــد منهــم ولــم‬\n     ‫ا كان نصيبــه منهــا راجعــا البطــن الــذي فوقــه ومــات‬  ‫يتــرك ولــدا أو نسـ َ‬\n     ‫واحــد منهــم ولــم يكــن فوقــه احــد أو لــم يذكــر يف ســهم مــن ميــوت عــن‬\n     ‫غيــر ولــد وال نســل شــيئا فيكــون نصيبــه راجعــا إلــى أصــل الغلــة وجاريــا‬\n     ‫مجراهــا أ‪.‬ه ـ لذلــك كلــه حكمــت بــأن حصــة مــن مــات عــن غيــر ولــد‬\n     ‫مــن املســتحقني يف كل ثلــث تعــود إلــى أصــل الثلــث ويعــاد قســمتها بــن‬\n     ‫جميــع املســتحقني وبعــرض ذلــك علــى الطرفــن قــرر املدعــي واملدعــي‬\n     ‫عليــه نظــارة القناعــة وقــرر املشــرف عــدم القناعــة وطلــب رفعــه حملكمة‬\n     ‫االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة ومت إفهامــه بالتعليمــات ‪،‬‬\n     ‫حــرر بتاريــخ ‪1434/1/14‬ه ـ ‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمد وعلى آله وصحبه وسلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافق‪1433/8/27‬ه ـ‬\n     ‫حضــر املدعــي أصالــة كمــا حضــر املدعــى عليــه نظــارة وبســؤال‬\n     ‫املدعــى عليــه نظــارة عــن رده عــن مــا قدمــه املدعــي يف اجللســة املاضيــة‬\n     ‫فأبــرز ورقــه هــذا نصهــا (أجيــب فضيلتكــم علــى دعــوى املدعــي (‪)......‬‬\n     ‫واملقيــدة لديكــم برقــم (‪ )......‬وتاريــخ ‪1432/5/15‬ه ـ علــى مــا قدمــه‬\n     ‫يف جلســة يــوم االثنــن ‪1433/6/23‬ه يف مــا يلــي ‪:‬أوال بخصــوص طلبــه‬\n     ‫إعــادة تقســيم مــا يخــص عائلــة (‪ )......‬فرع (‪ )......‬يف هذا الوقف بقســمته‬\n     ‫بــن ابنــي (‪ )......‬و (‪ )......‬بالتســاوي بينهــم حســب مــا ميثلونــه مــن طبقــة‬\n     ‫جديــدة مــن املســتحقني‪ .‬أفيــد فضيلتكــم بــأن هــذا الوقــف غيــر طبقــي‬\n     ‫فــا نقــض للقســمة هنــا لعــدم النقــض يف شــرط الوقــف ولعــدم النقــض‬\n     ‫يف عمــل النظــار الســابقني وإمنــا كان تقســيم غلــة هــذا الوقــف علــى‬\n\n\n‫‪45‬‬\n\f‫النحــو التالــي ‪( :‬أ)‪ :‬حســب صــك الوقــف رقــم (‪ )569‬فى‪1330/4/15‬ه ـ‬\n‫الصــادر مــن محكمــة مكــة املكرمــة والــذي جــاء فيــه ) أن الوقــف مــن‬\n‫حصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده إلــى أن نحصــر إلــى ثــاث مــن‬\n‫ذريتــه وأنــه كان العمــل جــاري علــى قســمة هــذا الوقــف بــن مســتحقيه‬\n‫يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا‬\n‫الصــك جملــة مــن نظــار هــذا الوقــف) ‪( .‬ب)‪ :‬أن يســتمر يف تقســيم الغلــة‬\n‫إلــى ثالثــة أثــاث ‪ :‬الثلــث األول مــن الغلــة لورثــة والثلــث الثانــي لورثــة‬\n‫والثلــث الثالــث لورثــة‪( .‬ج)‪ :‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور‬\n‫و أوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق ( وأن مــن مــات‬\n‫عــن غيــر ولــد فنصيبــه إلخوتــه حســب مــا جــاء يف صفحتــي (‪( 10‬و (‪)11‬‬\n‫مــن دفتــر الناظــر الســابق لفــرع (‪ )......‬وبعــد مشــاورتي للمشــرف علــى‬\n‫تطبيــق هــذا التقســيم لفــرع (‪ ).....‬و فــرع (‪ ).....‬بــدال مــن االضطرابــات‬\n‫التــي وقــع فيهــا الناظــر الســابق ‪ -‬يرحمــه اهلل ‪ -‬ولتطابــق هــذا يف كثيــر‬\n‫مــن شــروط الواقفــن أيدنــى علــى ذلــك وعــدم إغفالنــا ملــن لــم يكــن لــه‬\n‫إخــوة فيرجــع نصيبــه إلــى ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا‬\n‫جــاء يف الدفتــر (ص ‪ ) 8‬وحيــث أن املســتحقني لفــرع (‪ )......‬انحصــر يف‬\n‫أوالد (‪ )......‬وعددهــم ( تســعة ) أشــخاص ويف أوالد (‪ )......‬وعددهــم‬\n‫(خمســة) أشــخاص ‪ ،‬وأن وفــاة (‪ )......‬كان قبــل وفــاة أختــه (‪ )......‬وقــد‬\n‫انتقــل نصيبهــا إلــى أخيهــا (‪ )......‬ممــا زاد يف حصــص املســتحقني مــن‬\n‫أوالد (‪ )......‬وأن عددهــم أقــل مــن عــدد أوالد (‪ )......‬ممــا جعــل نصيــب‬\n‫املدعــي أقــل مــن نصيــب أوالد عمــه (‪ )......‬هــذا مــا دفــع املدعــى إلقامــة‬\n                                                                         ‫دعــواه ‪.‬‬\n‫ثانيـاً‪ :‬علــى املدعــى التأمــل يف تطبيــق طريقــة القســمة مــن عدمهــا أعــاه‬\n\n\n                                                                                      ‫‪46‬‬\n\f     ‫ليتأكــد مــن أن هــذه االضطرابــات قــد ازيلــت أم ال؟ عليــه نرجــوا مــن‬\n     ‫فضيلتكــم التوجيــه مبــا ترونــه حيــال حصــة العقيــم) وبعــرض ذلــك على‬\n     ‫املدعــي قــال أطلــب إمهالــي لالطــاع علــى مــا قدمــه الناظــر‪ ،‬وطلــب‬\n     ‫الطرفــان موعــد بعــد رمضــان‪ .‬ولــذا رفعــت اجللســة إلــى يــوم الســبت‬\n     ‫املوافق‪1433/10/21‬ه ـ الســاعة العاشــرة صباحــا ‪ .‬وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                     ‫‪1433/8/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1433/10/21‬هـ‬\n     ‫ويف متــام الســاعة احلاديــة عشــر والنصــف حضــر املدعــي كمــا حضــر‬\n     ‫املدعــى عليــه نظــارة وبســؤال املدعــي عمــا اســتمهل ألجلــه يف اجللســة‬\n     ‫املاضيــة فابــرز ورقــة هــذا نصهــا بعــد االطــاع والتأمــل يف جميــع‬\n     ‫الــردود التــي قدمهــا الناظــر علــى الوقــف أفيدكــم باعتراضــي وعــدم‬\n     ‫قناعتــي الن جميــع أعمالــه يف قســمة عائلــة (‪ )......‬مــن تلقــاء نفســه دون‬\n     ‫الرجــوع إلــى أي اســتناد وكمــا تعلمــون فضيلتكــم أنــه ال يوجــد شــرط‬\n     ‫للوقــف وهــذا خــاف مــا يدعيــه يف جميــع ردوده ‪ ،‬وحتــى بعــد املراجعــة‬\n     ‫والتدقيــق فيعمــل الناظــر الســابق يف قســمة عائلــة (‪ )......‬لــم يوجــد‬\n     ‫حرمــان بــل وزعــت حصــة العقيــم بالتســاوي واســتمر بالعمــل علــى ذلــك‬\n     ‫حتــى مــن بعــد وفاتــه‪ .‬لذلــك ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل‬\n     ‫النظــار ومتاشــي ًا مــع العــرف املتبــع يف كثيــر مــن شــروط الواقفــن علــى‬\n     ‫أن» مــن مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي طبقتــه أو ألصــل الغلــة‬\n     ‫«ولعمــوم الفائــدة ولتحيــق العدالــة بيننــا ‪ ،‬فإنــي أطلــب مــن فضيلتكــم‬\n     ‫املوقــرة إلــزام الناظــر احلالــي إعــادة تقســيم مــا يخــص عائلــة (‪)......‬‬\n     ‫بالتســاوي بينهــم نظــرا لوفــاة جميــع أصحــاب الطبقــة الســابقة بوفــاة‬\n\n\n‫‪47‬‬\n\f‫أخــر املســتحقني فيهــا وهــي (‪ )......‬يف عــام ‪1429‬ه ـ ونشــوء طبقــة جديدة‬\n‫وهــم أبنــاء (‪ )......‬و (‪.)......‬كمــا حضــر بالســجل املدنــي رقــم (‪ )......‬وهــو‬\n‫املشــرف علــى والناظــر مبوجــب الصــك الصــادر مــن احملكمــة العامــة‬\n‫(‪ )......‬برقــم ‪3/27/168‬يف ‪1429/12/18‬ه ـ كمــا حضــر بالســجل‬\n‫املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و(‪ )......‬بالســجل املدنــي‬\n‫رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬وقــرروا جميعــا قائلــن أننــا مــن‬\n‫املســتحقني يف هــذا الوقــف ونقــرر بــان حصــة مــن مــات عــن غيــر ولــد‬\n‫مــن املســتحقني ســواء كان عقيمــا أو لــم يتــزوج فإنهــا تصــرف إلخوانــه‬\n‫مــن املســتحقني هكــذا قــرروا جميعــا إ‪.‬ه ـ ثــم قــرر املدعــى عليــه نظــاره‬\n‫أن جميــع املســتحقني مــن الفــروع الثالثــة يقــررون أن حصــة مــن مــات‬\n‫عــن غيــر ولــد مــن املســتحقني تكــون إلخوانــه ولكنهــم ال يســتطيعون‬\n‫احلضــور لديكــم واطلــب إمهالــي إلحضــار إقــرارا منهــم بذلــك هكــذا‬\n‫قــرر وبعــرض ذلــك علــى املدعــي قــال أنــي ال أوافــق علــى مــا قــرره الناظــر‬\n‫واحلاضــرون مــن املســتحقني الن حصــة العقيــم والــذي ليــس لــه ذريــة‬\n‫مــن املســتحقني يرجــع ألصــل الثلــث وليــس إلخــوة امليــت هكــذا قــرر‬\n‫وإلحضــار اإلقــرارات التــي ذكرهــا الناظــر وعليــه رفعــت اجللســة إلــى‬\n‫يــوم الســبت املوافــق ‪1433/11/13‬ه ـ الســاعة العاشــرة ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف متــام‬\n                       ‫الســاعة الثانيــة عشــر والنصــف يف ‪1433/10/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافق‪1433/11/13‬ه ـ‬\n‫حضــر املدعــي أصالــة كمــا حضــر املدعــى عليــه نظــارة كمــا حضــر‬\n‫كل مــن (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و (‪ )......‬بالســجل املدنــي‬\n‫رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و بالســجل املدنــي رقــم (‪)......‬‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫بالســجل املدنــي رقــم (‪ )......‬وقــرروا جميعــا قائلــن إننــا أوالد ونحــن مــن‬\n     ‫املســتحقني يف هــذا الوقــف وكان والدنــا وعمنــا (‪ )......‬وعمتنــا (‪)......‬‬\n     ‫مســتحقني يف الوقــف ويســتلمون اســتحقاقهم مــن الناظــر الســابق يــوزع‬\n     ‫عليهــم االســتحقاق بالتســاوي بينهــم وملــا توفيــت عقيمــا كان يقســم‬\n     ‫اســتحقاقها علــى أخويهــا واســتمر العمــل علــى ذلــك بعــد وفــاة والدنــا‬\n     ‫وعمنــا ثــم تولــى هــذا الناظــر النظــارة واســتمر علــى هــذا العمــل ملــدة‬\n     ‫ســنتني وبعــد ذلــك اختلفــت القســمة وأصبــح يعطــى كامــل حصــة‬\n     ‫عمتنــا (‪ )......‬ألوالد عمنــا (‪ )......‬ويحرمنــا منهــا وملــا اعترضنــا عليــه قــال‬\n     ‫إن (‪ )......‬توفيــت بعــد والدكــم وحصتهــا تكــون ألخيهــا الــذي تــويف‬\n     ‫بعدهــا وهــو (‪ )......‬وأمــا مــن تــويف قبلهــا فــا يأخــذ شــيئا وبنــاء علــى‬\n     ‫ذلــك تقــدم أخونــا (‪ )......‬بهــذه الدعــوى ونحــن نطلــب إعــادة القســمة‬\n     ‫علــى مــا كانــت عليــه بقســمة حصــة العقيــم علــى أخــوة امليــت بالتســاوي‬\n     ‫هكــذا قــرروا وبعــرض ذلــك علــى املدعــى عليــه نظــارة قــال صحيــح مــا‬\n     ‫ذكــره املدعــي وإخوانــه احلضــور فقــد كان الناظــر الســابق مضطــرب‬\n     ‫يف العمــل ففــي هــذا الفــرع هــو فــرع (‪ )......‬كان يصــرف حصــة العقيــم‬\n     ‫إلــى أصــل الثلــث ويــوزع بالتســاوي بــن املســتحقني بينمــا يف الفرعــن‬\n     ‫اآلخريــن وهمــا فــرع (‪ )......‬وفــرع (‪ )......‬حيــث كان يجعــل حصــة‬\n     ‫العقيــم إلخوانــه فقــط دون بقيــة املســتحقني يف الفــرع هــذا إذا كان‬\n     ‫للعقيــم إخــوة وإذا لــم يكــن لــه إخــوة أعــاد حصــة العقيــم ألصــل الثلــث‬\n     ‫وقســمه بالتســاوي بــن املســتحقني وملــا توليــت النظــارة اســتمريت علــى‬\n     ‫هــذا العمــل ملــدة ســنة واحــدة فقــط وقمــت بعمــل شــباك االســتحقاق‬\n     ‫مــن واقــع الدفاتــر لــكل فــرع وظهــر لــي االضطــراب وجعلــت عمــل‬\n     ‫الناظــر الســابق يف فرعــي (‪ )......‬و (‪ )......‬هــو األصــل وعملــت بــه يف‬\n\n\n‫‪49‬‬\n\f‫فــرع (‪ )......‬الــذي ينتهــي إليــه املدعــي وإخوانــه وبنــاء عليــه وملــا كان‬\n‫والــد املدعــن قــد تــويف قبــل أختــه (‪ )......‬العقيمــة فإنــه ال يســتحق شــيئ ًا‬\n‫مــن اســتحقاقها وامنــا يكــون اســتحقاقها ألخيهــا (‪ )......‬الــذي توفيــت‬\n‫وهــو حــي ولــذا فــأن اســتحقاقها أصبــح ألوالد (‪ )......‬وحدهــم دون أوالد‬\n‫(‪ )......‬هكــذا قــرروا‪ .‬ثــم وبعــرض ذلــك علــى املدعــي واخواتــه قالــوا اننا‬\n‫نطلــب اعــادة قســمة حصــة العقيــم (‪ )......‬علــى اخوانهــا فمــن كان حيــا‬\n‫اخــذ حصتــه ومــن كان ميتــا اعطيــت حصتــه ألوالده هكــذا قــرروا‬\n‫ثــم ابــرز املدعــى عليــه نظــارة أوراق إقــرارات مــن املســتحقني يف الوقــف‬\n‫وهــذا نصهــا ( نقــر نحــن املســتحقني لوقــف (‪ )......‬فــرع و(‪ )......‬وفــرع‬\n‫(‪ )......‬بــأن يكــون تقسيـ ــم غلــة الوقــف علــى النحــو التالــي‪ :‬أ‪ -‬حســب‬\n‫صــك الوقــف رقم‪569‬يف‪1330/4/15‬ه ـ الصــادر مــن محكمــة (‪)......‬‬\n‫والــذي جــاء فيــه ان الوقــف مــن حصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده‬\n‫إلــى أن انحصــر إلــى ثــاث مــن ذريتــه وهــم وانــه كان جــاري علــى قســمة‬\n‫هــذا الوقــف بــن مســتحقيه يف كل زمــان بانتقــال نصيــب كل مســتحق‬\n‫إلــى أوالده وقــد عمــل بهــذا الصــك جملــة مــن نظــار هــذا الوقــف ب‪ -‬ان‬\n‫يســتمر يف تقســيم الغلــة الــى ثــاث اثــاث الثلــث االول مــن الغلــة لورثــة‬\n‫والثلــث الثانــي لورثــة (‪ )......‬والثلــث لورثــة‪ )......( .‬ان يســتمر التقســيم‬\n‫يف ذلــك ألوالد الظهــور وأوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر‬\n‫الســابق وان مــن مــات مــن غيــر ولــد فنصيبــه ألخواتــه حســب مــا جــاء‬\n‫يف صفحتــي (‪ )10‬و(‪ )11‬مــن دفتــر الناظــر الســابق لفــرع (‪ )......‬ومــن‬\n‫لــم يكــن لــه اخــوة فيرجــع نصيبــه إلــى ثلــث ثلــث الغلــة املنتمــي إليهــا‬\n‫ذلــك العقيــم كمــا جــاء يف الدفتــر ص‪. 8‬املســتحقني املوقعــن هــم اوالد‬\n‫‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬و اوالد ‪ .....‬اوالد ‪ .....‬اوالد‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ ).....‬ا‪ -‬ه ــو بعــرض‬\n     ‫هــذه اإلقــرارات علــى املدعــي قــال اطلــب تزويــدي بصــورة منهــا وامهالــي‬\n     ‫لالطــاع عليهــا وجــرى تســليم املدعــي صــورة منهــا ثــم قرر احلاضــر أوالد‬\n     ‫بأننــا نــوكل اخانــا املدعــي يف مواصلــة هــذه الدعــوى وحضــور جميــع‬\n     ‫اجللســات واملرافعــة واملدافعــة وتقــدمي البينــات والــرد عليهــا والقناعــة‬\n     ‫واالعتــراض وتقــدمي الالئحــة االعتراضيــة حتــى اكتســاب احلكــم‬\n     ‫القطعيــة هكــذا قــرروا وقــرر احلاضــر (‪ )......‬موافقتــه علــى ذلــك ‪.‬‬\n     ‫ول ـ ــذا رفعــت اجللســة إلــى يــوم الســبت املوافــق ‪1433/11/27‬ه ـ الســاعة‬\n     ‫التاســعة صباحــا‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/11/13‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق‪1433/11/ 27‬هـ‬\n     ‫حضــر املدعــي أصالــة ووكالــة كمــا حضــر املدعــى عليــه نظــارة حــال‬\n     ‫حضور وقرر (‪ )......‬أن الناظر الســابق كان مضطربا يف تقســيم حصة‬\n     ‫العقيــم أو الــذي تــويف عــن غيــر ولــد فأحيانــا يعيدهــا إلــى أصــل الغلــة‬\n     ‫كمــا فعــل يف (‪ )......‬ومــن قبلهــا مــن العقمــاء حيــث كان يجمــع حصــة‬\n     ‫العقمــاء ويعيــد قســمتها علــى املســتحقني بالتســاوي وحينمــا توفيــت‬\n     ‫(‪ )......‬لــم يفعــل ذلــك وإمنــا أعطــى اســتحقاقها ألختهــا العقيمــة (‪ )......‬ولم‬\n     ‫يعــط بقيــة املســتحقني شــيئا هكــذا قــرر ‪ .‬وبعــرض ذلــك علــى املدعــي‬\n     ‫واملدعــى عليــه قــاال صحيــح مــا ذكــره احلاضــر (‪ )......‬فالناظــر الســابق‬\n     ‫كان مضطربــا يف قســمة حصــة العقيــم ومــن لــم يخلــف أوالدا هكــذا‬\n     ‫قــررا ‪ .‬وبســؤال الطرفــن هــل لديهــم مــا يضيفانــه يف هــذه القضيــة فقــاال‬\n     ‫ليــس لدينــا ســوى مــا قدمنــاه ‪ ،‬والتأمــل القضيــة رفعــت اجللســة إلــى يــوم‬\n     ‫الثالثــاء املوافــق ‪1434/1/6‬ه الســاعة التاســعة والنصــف صباحــا وبــاهلل‬\n\n\n‫‪51‬‬\n\f‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪1433/11/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ‬\n‫ويف متــام الســاعة العاشــرة والربــع صباحـ ًا افتتحــت اجللســة ولــم يحضــر‬\n‫املدعــي أو وكيــل شــرعي عنــه ولــم يتقــدم بعــذر عــن تخلفــه كمــا لــم‬\n‫يحضــر املدعــي عليــه لــذا فقــد شــطب القضيــة للمــرة األولــى حســب‬\n‫التعليمــات حــرر يف الســاعة العاشــرة والربــع بتاريــخ ‪1434/1/6‬هــ‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األربعــاء املوافــق ‪1434/1/14‬ه ـ‬\n‫ويف متــام الســاعة (‪ )9.30‬صباحــا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫كمــا حضــر املدعــي عليــه نظــارة وبســؤال الطرفــن هــل لديهمــا مــا‬\n‫يضيفانــه يف هــذه القضيــة فقــال املدعــي أننــي ســبق أن ذكــرت يف‬\n‫دعــواي إننــي اطلــب إعــادة قســمة الغلــة بــن املســتحقني بالتســاوي وتبــن‬\n‫لــي أن عمــل النظــارة الســابقني هــو إعطــاء حصــة كل مســتحق ألوالده‬\n‫ولــذا فــا مطالبــة لــي فيمــا يخــص ذلــك وإمنــا مطالبتــي هــي فيمــا يخــص‬\n‫حصــة العقيــم بــأن ال تصــرف ألحــد دون أحــد مــن املســتحقني وإمنــا تعــود‬\n‫ألصــل الغلــة هكــذا قــرر وبعــرض ذلــك علــى املدعــي عليــه نظــارة قــال‬\n‫ليــس لــدي ســوى مــا قدمتــه بــأن العقيــم قــد اضطــرب فيهــا النظــار‬\n‫الســابقون ففــي ثلثــن تعطــى حصــة العقيــم ومــن توفــى عــن غيــر ولــد‬\n‫إلخوانــه ويف الثلــث الــذي ينتمــي إليــه املدعــي فــإن الناظــر الســابق كان‬\n‫يعطــي حصــة العقيــم ومــن مــات عــن غيــر ولــد إلخوانــه ثــم بعــد ذلــك‬\n‫إعــادة إلــى أصــل الغلــة ثــم رجــع وأعطــاه إلخــوة املتــويف حســب مــا بينتــه‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫لكــم ســابقا هكــذا قــرر وقــد حضــر املشــرف علــى الناظــر ســجل‬\n     ‫مدنــي رقــم (‪ )......‬الصــك الصــادر مــن هــذه احملكمــة برقــم (‪ )......‬يف‬\n     ‫‪1429/12/18‬ه ـ وقــرر قائــا إننــي اطلــب إدخالــي يف هــذه القضيــة وأنــا‬\n     ‫أطلــب العمــل بإعطــاء حصــة مــن توفــى غيــر ولــد مــن املســتحقني إلخوتــه‬\n     ‫يف كل ثلــث ألنــه ال يوجــد شــرط واقــف يف هــذا الوقــف وإمنــا أكثــر‬\n     ‫عمــل النظــار علــى ذلــك هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وبعــد اإلطــاع علــى صكــوك هــذا الوقــف وألنــه تبــن عــدم‬\n     ‫وجــود شــرط واقــف لــدى نظــار هــذا الوقــف وأن غلــة هــذا الوقــف تقســم‬\n     ‫أثالثــا علــى الوصــف املشــار إليــه بعاليــه وأن حصــة كل مســتحق تنتقــل‬\n     ‫إلــى أوالده وألن الناظــر قــرر أن النظــار الســابقني كانــوا مضطربــن يف‬\n     ‫حصــة مــن تــويف عقيمــا أو عــن غيــر ولــد فأحيانــا كانــوا يقســمونها بــن‬\n     ‫إخوتــه وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن الراجــح عنــد أهــل العلــم‬\n     ‫أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع إليــه عنــد االختــاف‬\n     ‫فــإن حصــة مــن توفــى عــن غيــر ولــد تعــود ألصــل الغلــة قــال يف تنقيــح‬\n     ‫احلامديــة املنصــوص عليــه عندنــا يف االســعاف وغيــره أنــه إذا ســكت‬\n     ‫عــن حكــم مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف الغلــة أي‬\n     ‫ينقســم علــى جميــع املســتحقني أ‪.‬ه ـ ينظــر تنقيــح احلامديــة واالســعاف‬\n     ‫يف أحــكام األوقــاف للطرابلســي صحيفــة ‪106‬وقــال يف االســعاف ولــو‬\n     ‫ا كان‬     ‫قــال كلمــا حــدث املــوت علــى احــد منهــم ولــم يتــرك ولــدا أو نسـ َ‬\n     ‫نصيبــه منهــا راجع ـ ًا البطــن الــذي فوقــه ومــات واحــد منهــم ولــم يكــن‬\n     ‫فوقــه احــد أو لــم يذكــر يف ســهم مــن ميــوت عــن غيــر ولــد وال نســل شــيئا‬\n     ‫فيكــون نصيبــه راجعــا الــى أصــل الغلــة وجاريــا مجراهــا أ‪.‬ه ـ لذلــك‬\n     ‫كلــه حكمــت بــأن حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني يف‬\n\n\n‫‪53‬‬\n\f‫كل ثلــث تعــود الــى أصــل الثلــث ويعــاد قســمتها بــن جميــع املســتحقني‬\n‫وبعــرض ذلــك علــى الطرفــن قــرر املدعــي واملدعــي عليــه نظــارة القناعــة‬\n‫وقــرر املشــرف عــدم القناعــة وطلــب رفعــه حملكمــة اإلســتئناف واســتعد‬\n‫بتقــدمي الئحــة اعتراضيــة ومت إفهامــه بالتعليمــات ‪ ،‬حــرر يف الســاعة‬\n‫(‪ )10.00‬صباحـ ًا بتاريــخ ‪1434/1/14‬ه ـ ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n                              ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة بشــرح فضيلة رئيــس احملكمة‬\n‫برقــم يف ‪1434/4/24‬ه علــى خطــاب محكمــة االســتئناف بخطابهــم‬\n‫رقــم يف ‪1434/4/9‬ه ـ مرفقــا بــه القــرار الصــادر مــن دائــرة االحــوال‬\n‫الشــخصية االولــى برقــم يف ‪1434/3/22‬ه ـ املتضمــن وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــه حاكمهــا‬\n‫حيــث جــاء يف الالئحــة االعتراضيــة يف جميــع فقراتهــا مــا يســتدعي‬\n‫النظر الشرعي واملناقشة بحضور اطراف القضية أو اجلواب بالتفصيل‬\n‫ومــن ذلــك مــا ورد يف الفقــرة ثاني ـاً‪ ،‬وكذلــك مــا ذكــره املعتــرض يف‬\n‫الئحتــه يف الفقــرة رابعـ ًا بشــأن جوابــه علــى مــا ذكــره أطــراف القضيــة‬\n‫ومســتنده علــى ذلــك ويتعــن اجــراء الوجــه الشــرعي نحــو ذلــك وإذا‬\n‫ثبــت مــا ذكــره املشــرف علــى الوقــف يف الئحتــه فيلــزم إعــادة النظــر‬\n‫يف احلكــم‪ .‬وبــاهلل التوفيــق أ‪.‬ه ـ وعليــه أجيــب علــى مــا جــاء يف قــرار‬\n‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف بأننــي ســبق أن اطلعــت‬\n‫علــى الالئحــة االعتراضيــة ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت‬\n‫بــه وقــد دونــت ذلــك علــى الالئحــة املرفقــة بــاألوراق ويف ضبــط القضيــة‬\n‫مــع احاطــة أصحــاب الفضيلــة بــأن كل مــا ذكــره املشــرف يف الالئحــة‬\n‫ســبق أن ذكــره يف اجللســات ومتــت مناقشــته قبــل احلكــم ولــم يظهــر لــي‬\n\n\n                                                                                   ‫‪54‬‬\n\f     ‫أن فيمــا ذكــره أثــر علــى احلكــم ولــذا فليــس لــدي ســوى مــا حكمــت‬\n     ‫بــه وأمــرت بإحلاقــه بالصــك وســجله ورفعــه حملكمــة االســتئناف لتقريــر‬\n     ‫مــا تــراه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/4/30‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بشــرح فضيلــة الرئيــس برقــم يف ‪1434/6/6‬ه ـ علــى خطــاب رئيــس‬\n     ‫محكمــة االســتئناف مبنطقــة املكلــف برقــم يف ‪1434/5/29‬ه ـ‬\n     ‫برفقهــا قــرار التصديــق مبوجــب القــرار رقــم ‪1434/5/‬ه ـ وهــذا نصــه‬\n     ‫‪ -:‬احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف‬\n     ‫والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n     ‫خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة رقــم وتاريــخ‬\n     ‫‪1434/5/5‬ه ـ املشــتملة علــى الصــك وتاريــخ ‪1434/1/20‬ه ـ الصــادر‬\n     ‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة واملتضمــن دعــوى ضــد‬\n     ‫بصفتــه ناظــر ًا علــى وقــف يف اســتحقاق مــن الوقــف وبدراســة الصــك‬\n     ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n     ‫احلكــم بعــد اجلــواب األخيــر لفضيلتــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬قاضــي اســتئناف (‪)......‬‬\n     ‫ختــم وتوقيــع قاضــي اســتئناف (‪ )......‬ختــم وتوقيــع رئيــس الدائــرة لــي‬\n     ‫وجهــة نظــر (‪ )......‬ختــم وتوقيــع‪ ،‬ل ـ ــذا جــرى التهميــش مبوجبــه ‪ .‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                           ‫حــرر يف ‪1434/6/14‬ه ـ‬\n\n\n‫‪55‬‬\n\f‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة جــرى منــا االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة رقــم وتاريــخ ‪1434/5/5‬ه ـ املشــتملة علــى الصــك رقــم وتاريــخ‬\n‫‪1434/1/20‬ه ـ الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامة‬\n‫املتضمن دعوى (‪ )......‬ضد (‪ )......‬بصفته ناظر ًا على وقف يف استحقاق‬\n‫مــن الوقــف وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم بعــد اجلــواب األخيــر لفضيلتــه واهلل‬\n          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":30,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2d973159b171c64cb8d482ad8b7da838f52b5354c50147bad7c4451e66bec724","normalized_text_hash":"10161daa1537339ebf1ef60d2b1ae214269964c0173e23314f875e4e7bd4a549","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p30-3418295"},{"id":"0712707e-a572-5824-9388-88740a02d105","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -إفراغ مسجد -إثبات وقفيته -رفض املدعى عليه ،حجته شرائه املزرعة باملسجد وأنه مسجد عائلي -ثبوت قيام املالك السابق بإيقاف املسجد قبل شراء املدعى عليه املزرعة -إقرار املدعى عليه أن املسجد كان قائم ا قبل شرائه املزرعة -الوقف ال يباع وال يوهب -احلكم بثبوت وقفية املسجد -إفهام املدعى عليه الرجوع على من باعه إذا كان غره.","document_number":"32297345","case_number":"32486362","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/11/5","year":"1434","subject":"وقف -إفراغ مسجد -إثبات وقفيته -رفض املدعى عليه ،حجته شرائه املزرعة باملسجد وأنه مسجد عائلي -ثبوت قيام املالك السابق بإيقاف املسجد قبل شراء املدعى عليه املزرعة -إقرار املدعى عليه أن املسجد كان قائم ا قبل شرائه املزرعة -الوقف ال يباع وال يوهب -احلكم بثبوت وقفية املسجد -إفهام املدعى عليه الرجوع على من باعه إذا كان غره.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1432/11/5 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪32297345 :‬‬\n                        ‫َر ْق ُم الدعوى‪32486362 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 348289‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n     ‫وقــف ‪ -‬إفــراغ مســجد ‪ -‬إثبــات وقفيتــه ‪ -‬رفــض املدعــى عليــه ‪ ،‬حجتــه‬\n     ‫شــرائه املزرعــة باملســجد وأنــه مســجد عائلــي ‪ -‬ثبــوت قيــام املالــك‬\n     ‫الســابق بإيقــاف املســجد قبــل شــراء املدعــى عليــه املزرعــة ‪ -‬إقــرار‬\n     ‫املدعــى عليــه أن املســجد كان قائم ـ ًا قبــل شــرائه املزرعــة ‪ -‬الوقــف ال‬\n     ‫يبــاع وال يوهــب ‪ -‬احلكــم بثبــوت وقفيــة املســجد ‪ -‬إفهــام املدعــى عليــه‬\n                                        ‫الرجــوع علــى مــن باعــه إذا كان غــره‪.‬‬\n\n\n\n\n     ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (ال يبــاع أصلهــا وال توهــب وال تــورث)‬\n                                                                      ‫متفــق عليــه‪.‬‬\n     ‫‪ -2‬قــال القرطبــي رحمــه اهلل يف املفهــم (ال خــاف بــن األئمــة يف‬\n                                     ‫حتبيــس املســاجد والقناطــر ) ‪.600/4‬‬\n     ‫‪ -3‬جــاء يف كشــاف القنــاع (يــزول ملــك الواقــف عــن العــن املوقوفــة‬\n     ‫مبجــرد الوقــف وينتقــل امللــك فيهــا إلــى اهلل تعالــى) ‪.104/10-34/10‬‬\n     ‫‪ -4‬جــاء يف كشــاف القنــاع‪« 104/10 :‬الوقــف عقــد الزم ‪ ..‬ويحــرم وال‬\n                                       ‫يصــح بيعــه وال هبتــه وال املناقلــة بــه»‪.‬‬\n     ‫‪ -5‬جــاء يف كشــاف القنــاع‪ « :‬ويلــزم الوقــف مبجــرد القــول دون حكــم‬\n                                                                 ‫حاكــم» ‪.104/10‬‬\n\n\n\n‫‪57‬‬\n\f‫أقامــت (‪ )000‬دعــوى علــى رجــل قــام بهــدم جــزء مــن مســجد يف مزرعتــه‬\n‫فتعطلــت الصلــوات فيــه وطالبــت املدعــى عليــه بإعــادة بنــاء املســجد‬\n‫وإزالــة العوائــق التــي بناهــا وإفــراغ املســجد وملحقاتــه واألرض املقــام‬\n‫عليــه لصالــح وزارة الشــؤون اإلســامية‪ ،‬بعــرض الدعــوى علــى املدعــى‬\n‫عليــه أفــاد بــأن املســجد املذكــور هــو مســجد عائلــي وداخــل مزرعتــه‬\n‫وأنــه اشــترى املزرعــة ومــن ضمنهــا املســجد املذكــور وأنــه قــام ببعــض‬\n‫التعديــات اخلاصــة يف مزرعتــه أدت إلــى إزالــة بعــض جــدران املســجد‬\n‫ودورات امليــاه فتعطــل املســجد ورفــض إفــراغ املســجد وملحقاتــه لــوزارة‬\n‫الشــؤون اإلســامية ثــم ســألته احملكمــة هــل كان املســجد قائمـ ًا عنــد‬\n‫شــراءه للمزرعــة أجــاب قائــا نعــم وأن الــذي بنــاه املالــك الســابق (‪).....‬‬\n‫فجــرى اطــاع احملكمــة علــى إقــرار املالــك الســابق للتنازل عن املســجد‬\n‫وتســليمه لألوقــاف كمــا طلبــت احملكمــة أســاس صــك العقــار فرفــض‬\n‫املدعــى عليــه تســليمه ثــم ســألت احملكمــة وزارة الشــؤون اإلســامية‬\n‫عــن حــدود املســجد وأطوالــه فحددتهــا الــوزارة ثــم رجــع املدعــى عليــه‬\n‫وقــال إن ســبب إزالتــه لبعــض أجــزاء املســجد وتعطيلــه تصرفــات بعــض‬\n‫مريــدي املســجد التــي أســاءت لــه حيــث أصبحــوا يكشــفون منزلــه‬\n‫وإلقــرار املدعــى عليــه لــدى احملكمــة بــأن املســجد املذكــور كان‬\n‫قائــم قبــل شــرائه للمزرعــة تصلــى فيــه الصلــوات اخلمــس وأن الــذي بنــاه‬\n‫املالــك الســابق الــذي أقــر بوقفيتــه وألنــه يــزول ملــك الواقــف عــن العــن‬\n‫املوقوفــة وألنــه ال يجــوز بيــع األوقــاف وألن النظــام جعــل لــوزارة الشــؤون‬\n‫اإلســامية احلــق يف اإلشــراف علــى املســاجد فقــد ثبــت لــدى احملكمــة‬\n\n                                                                                     ‫‪58‬‬\n\f     ‫وقفيــة املســجد املذكــور يف الدعــوى وملحقاتــه واألرض املقــام عليهــا‬\n     ‫باحلــدود واألطــوال املشــار إليهــا بالدعــوى‪ ،‬وأفهمــت احملكمــة املدعــى‬\n     ‫عليــه بــأن لــه الرجــوع علــى مــن باعــه إن كان قــد غــره‪ ،‬اعتــرض املدعى‬\n                                                      ‫عليــه‪ ،‬وصــدق احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n     ‫ـاء‬\n     ‫وبعــد لــدي أنــا (‪ )0000‬رئيــس محاكــم منطقــة جنــران املســاعد وبنـ ً‬\n     ‫علــى املعاملــة احملالــة لنــا برقــم ‪ 1622‬يف ‪1431/9/5‬ه ـ واحملدثــة بقيــد‬\n     ‫احملكمــة رقــم ‪ 321357605‬وتاريــخ ‪1432/10/29‬ه واحملالــة برقــم‬\n     ‫‪ 32486362‬يف ‪1432/10/29‬ه ـ حضــر (‪ )000‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ )000‬منــدوب فــرع وزارة الشــؤون‬\n     ‫اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران مبوجــب‬\n     ‫خطابهــم رقــم (‪ )000‬يف ‪1431/6/8‬ه ـ وادعــى علــى احلاضر معه (‪)000‬‬\n     ‫ا يف دعــواه‬ ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )000‬قائ ـ ً‬\n     ‫لقــد ســبق وأن قــام املواطــن ببنــاء مســجد (‪ )000‬علــى جــزء مــن مزرعتــه‬\n     ‫وتنــازل عــن املســجد وملحقاتــه وحرمــه ودورات امليــاه التابعــة لــه لوجــه‬\n     ‫اهلل تعالــى وذلــك يف ‪1417/9/1‬ه ـ حســب إقــراره املرفــق باملعاملــة ولــم‬\n     ‫يتــم إفــراغ املســجد يف حينــه ثــم مت بيــع األرض عــدة مــرات إلى أن وصلت‬\n     ‫إلــى املدعــى عليــه احلاضــر ومنــذ ذلــك التاريــخ وحتــى اآلن واملســجد‬\n     ‫باســتالم فــرع وزارة الشــؤون اإلســامية واالوقــاف والدعــوة واإلرشــاد‬\n     ‫مبنطقــة جنــران وتقــام فيــه الصلــوات اخلمــس وفيــه مــؤذن وإمــام بشــكل‬\n     ‫رســمي ثــم قــام املدعــى عليــه باالعتــداء علــى املســجد وذلــك ببنــاء ســور‬\n\n‫‪59‬‬\n\f‫يحجــز املســجد عــن الشــارع العــام كمــا قــام أخيــر ًا بإقفــال دورات امليــاه‬\n‫وكذلــك إقفــال أحــد أبــواب املســجد وقــام كذلــك بإزالــة اجلــدار‬\n‫اجلنوبــي حلــرم املســجد وإزالــة خــزان امليــاه وإزالــة لوحــة املســجد أطلــب‬\n‫إفــراغ املســجد وملحقاتــه واألرض املقــام عليهــا لصالــح فــرع وزارة‬\n‫الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة وذلــك‬\n‫مبســاحة إجماليــة قدرهــا (‪232‬م‪ )2‬مائتــان واثنــان وثالثــون متــر ًا مربعـ ًا‬\n‫كمــا أطلــب بإزالــة اجلــدار الــذي أقامــه املدعــى عليــه بــن املســجد‬\n‫والشــارع العــام وكذلــك إعــادة بنــاء اجلــدار الــذي أزالــه املدعــى عليــه‬\n‫مــن اجلهــة اجلنوبيــة وكذلــك إعــادة خــزان امليــاه الــذي أزالــه املدعــى عليه‬\n‫وكل ذلــك علــى حســابه هــذه دعــواي وبســؤال املدعــى عليــه أجــاب‬\n‫ا لقــد قمــت بشــراء املزرعــة مــن املواطــن (‪ )000‬يف عــام ‪1424‬ه ـ‬          ‫قائ ـ ً‬\n‫وقــد ســألته عــن املســجد املوجــود فيهــا فقــال لــي إنــه مســجد عائلــي وهــو‬\n‫داخــل املزرعــة ويف حاللــك وقــد قمــت بتلبيــس حجــر لســور املزرعــة ومــن‬\n‫ضمنهــا املســجد وأمــا اجلــدار اجلنوبــي فأنــا الــذي أقمتــه منــذ فتــرة ثــم‬\n‫أزلتــه وأغلقــت دورات امليــاه والبــاب الــذي يوصــل إليهــا كمــا قمــت‬\n‫بإزالــة خــزان امليــاه وذلــك للضــرر الــذي حلقنــي بســببها حيــث يقــوم‬\n‫األوالد باإلطــال علــى املزرعــة ومحارمــي فيهــا مــن خــال نوافــذ دورات‬\n‫امليــاه وكذلــك مــن خــال الصعــود للخــزان وأمــا لوحــة املســجد فلــم أقــم‬\n‫بإزالتها وأرفض طلب فرع وزارة الشــؤون اإلســامية واألوقاف والدعوة‬\n‫واإلرشــاد مبنطقــة جنــران إفــراغ املســجد وملحقاتــه هكــذا أجــاب‬\n‫فجــرى ســؤال املدعــى عليــه هــل كان املســجد قائم ـ ًا عنــد شــرائه‬\n‫ا نعــم لقــد كان املســجد قائم ـ ًا تصلــى فيــه‬        ‫للمزرعــة فأجــاب قائ ـ ً‬\n‫الصلــوات اخلمــس واليــزال وأخبرنــي البائــع أن الــذي بنــاه هــو ولــم يقــم‬\n\n\n                                                                                         ‫‪60‬‬\n\f     ‫ا وليــس فيــه ذكــر‬   ‫أحــد بإفــراغ املســجد وقــد اشــتريت الصــك كام ـ ً‬\n     ‫للمســجد هكــذا أجــاب فجــرى االطــاع علــى أوراق املعاملــة ومنهــا‬\n     ‫صــورة إقــرار (‪ )000‬املرفــق باملعاملــة وهــذا نصــه (احلمــد هلل رب العاملــن‬\n     ‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد هــذا إقــرار منــي بالتنــازل‬\n     ‫عــن املســجد الــذي أقمتــه علــى جــزء مــن أرضــي بــ(‪ )000‬هــو وأرضــه‬\n     ‫وحرمــه ودورات امليــاه التابعــة لــه هلل تعالــى وســلمته إدارة األوقــاف‬\n     ‫لتشــرف عليــه وتقــوم بواجباتــه هــذا واهلل مــن وراء القصــد حــرر يف‬\n     ‫‪1417/9/1‬ه ـ املقــر (‪( )000‬وتوقيعــه ) أ‪.‬ه كمــا جــرى اإلطــاع علــى‬\n     ‫خطــاب مديــر فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة‬\n     ‫واإلرشــاد مبنطقــة جنــران رقــم ‪ 11263‬يف ‪1432/3/13‬ه ـ املتضمــن أن‬\n     ‫التعليمــات تنــص علــى أن حــرم املســجد إذا كان احمليــط للمســجد‬\n     ‫مبنــى أو مواقــف أو جــار هــو متريــن وبطلــب أســاس الصــك مــن املدعــى‬\n     ‫عليــه لالطــاع عليــه قــال صــورة الصــك موجــودة يف املعاملــة وأما أســاس‬\n     ‫الصــك فلــن أســلمه ألحــد هكــذا أجــاب كمــا جــرى ســؤال منــدوب‬\n     ‫فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة‬\n     ‫جنــران عــن حــدود املســجد وأطوالــه فقــال ســأحضر بياناتهــا يف اجللســة‬\n     ‫القادمــة ويف جلســة أخــرى حضــر الطرفــان وبســؤال منــدوب فــرع وزارة‬\n     ‫الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران عــن‬\n     ‫ا إن حــدود وأطــوال املســجد‬        ‫حــدود وأطــوال املســجد أجــاب قائ ـ ً‬\n     ‫كالتالــي مــن الشــمال باقــي الصــك الــذي ميلكــه املدعــى عليــه رقــم‬\n     ‫‪ 3/35‬بطــول خمســة عشــر متــر ًا وســبعني ســنتيمتر ًا ومــن اجلنــوب باقــي‬\n     ‫الصــك الــذي ميلكــه املدعــى عليــه رقــم ‪ 3/35‬بطــول خمســة عشــر متــر ًا‬\n     ‫وخمســة وتســعني ســنتيمتر ًا ومــن الشــرق شــارع اســفلت بطــول يبــدأ مــن‬\n\n\n‫‪61‬‬\n\f‫الشــمال خمســة أمتــار وســتني ســنتيمتر ًا ثــم ينكســر جنــوب غــرب‬\n‫بطــول ســبعة أمتــار وأربعــة عشــر ســنتيمتر ًا ثــم ينكســر جنــوب غــرب‬\n‫بطــول متــر وتســعني ســنتيمتر ًا بطــول إجمالــي للشــرق أربعــة عشــر متــر ًا‬\n‫وأربعــة وســتون ســنتيمتر ًا ومــن الغــرب باقــي الصــك الــذي ميلكــه رقــم‬\n‫‪ 35/3‬بطــول ثالثــة عشــر متــر ًا وتســعة ســنتيمتر مبســاحة إجماليــة‬\n‫قدرهــا ‪232‬م‪ 2‬مائتــان واثنــان وثالثــون متــر ًا مربع ـ ًا هكــذا أجــاب‬\n‫وجــرى ســؤال املدعــى عليــه مــر ًة أخــرى عــن املســجد مــن الــذي بنــاه وهــل‬\n‫ا إن الــذي‬   ‫كان قائم ـ ًا يصلــى فيــه عنــد شــرائه للمزرعــة فأجــاب قائ ـ ً‬\n‫بنــاه هــو (‪ )000‬حســب مــا ذكــر لــي ابــن (‪ )000‬الــذي اشــتريت منــه‬\n‫املزرعــة وقــد اشــتريتها واملســجد قائــم تصلــى فيــه الصلــوات اخلمــس‬\n‫واليــزال وســيبقى كذلــك علم ـ ًا أن اجلــدار الــذي يفصــل املســجد عــن‬\n‫الشــارع موجــود قبــل شــرائي للمزرعــة ووزارة الشــؤون اإلســامية لــم‬\n‫تقــم بإضافــة أي شــيء للمســجد ولــم تتصــرف فيــه طيلــة هــذه املــدة ألنهــا‬\n‫ال متلكــه هكــذا أجــاب ثــم أبــرز ورقـ ًة هــذا نصهــا (بســم اهلل الرحمــن‬\n‫الرحيــم صاحــب الفضيلــة رئيــس احملكمــة العامــة املســاعد حفظــه اهلل‬\n‫الســام عليكــم ورحمــة اهلل وبركاتــه أقــدم إلتماســي هــذا أمــام‬\n‫ا إحقــاق احلــق مفيــد ًا فضيلتكــم بــأن لي مزرعـ ًة خاصة‬      ‫فضيلتكــم آمـ ً‬\n‫أســكن فيهــا وفيهــا مســجد داخــل صكــي الشــرعي وجــزء مــن‬\n‫ـزء مــن منزلــي وقــد فتحــت لــه بــاب مــن‬\n                                           ‫أمالكــي وهــذا املســجد يعتبــر جـ ً‬\n‫اخلــارج ألجــل يصلــي فيــه مــن يرغــب فضيلــة الرئيــس لقــد أخــذ بعــض‬\n‫مريــدي املســجد إســاءة اســتعمال بعــض مرافــق املســجد حتــى أصبــح‬\n‫يكشــف علــى منزلــي لهــذا قمــت بهــدم العــازل لــدورة امليــاه مــن حــوش‬\n‫املســجد وذلــك بهــدف ســتر بيتــي حتــى ال يســتطيع أحــد أن يكشــف‬\n\n\n                                                                                      ‫‪62‬‬\n\f     ‫بيتــي مــن جهــة دورة امليــاه فضيلــة الرئيــس فوجئــت باســتدعائي مــن قبــل‬\n     ‫الشــرطة وإيداعــي الســجن بحجــة أن هنــاك قضيــة ضــدي مــن قبــل هيئــة‬\n     ‫التحقيــق واالدعــاء العــام فضيلــة الرئيــس لــم أرتكــب أي جــرم أســجن‬\n     ‫عليــه وقــد تصرفــت يف جــزء بســيط مــن ملكــي وإذا كانــت وزارة‬\n     ‫الشــؤون اإلســامية ترغــب أن تنــزع جــزء مــن ملكــي فــا يحــق لهــا ذلــك‬\n     ‫إال مبوجــب نظــام نــزع امللكيــة املبلــغ بتعميــم صاحــب الســمو امللكــي‬\n     ‫رئيــس ديــوان رئاســة مجلــس الــوزراء البرقــي رقــم ‪/8‬ب‪ 12662/‬تاريــخ‬\n     ‫‪1424/3/17‬ه ـ املصــادر عليــه باملرســوم امللكــي م‪ 15/‬تاريــخ‬\n     ‫‪1424/3/11‬ه ـ والتــي تنــص مادتهــا األولــى علــى أنــه يجــوز للــوزارات‬\n     ‫واملصالــح احلكوميــة وغيرهــا مــن األجهــزة ذوات الشــخصية املعنويــة‬\n     ‫العامــة نــزع ملكيــة العقــار للمنفعــة العامــة لقــاء تعويــض عــادل بعــد‬\n     ‫التحقــق مــن عــدم توفــر األراضــي والعقــارات احلكوميــة التــي تفــي‬\n     ‫بحاجــة املشــروع وال يجــوز نــزع ملكيــة عقــار إال لتنفيــذ مشــروع معتمــد‬\n     ‫يف امليزانيــة صاحــب الفضيلــة أوالً‪ :‬إن الظلــم ظلمــات حرمــه اهلل علــى‬\n     ‫نفســه وجعلــه بــن عبــاده محرمـ ًا أرجــو إطــاق ســراحي بالكفالــة حتــى‬\n     ‫يبــت يف قضيتــي شــرع ًا ثاني ـاً‪ :‬إلــزام اجلهــة املدعيــة بتعويضــي تعويض ـ ًا‬\n     ‫عــاد ًال فيمــا يســتقطع مــن ملكــي أو إعطائــي التصــرف يف ملكــي دون‬\n     ‫اعتــراض هــذا واهلل يحفظكــم مقدمــه) أ‪.‬ه ـ ثــم جــرى ســؤال الطرفــن‬\n     ‫هــل ألحدهمــا مــا يضيفــه فأجــاب كل واحــد منهمــا قائــا ليــس لــدي‬\n     ‫ســوى مــا ذكــرت هكــذا قــررا ورفعــت اجللســة حلضــور وقــت الصــاة‬\n     ‫ويف جلســة أخــرى حضــر الطرفــان وجــرى االطــاع علــى خطــاب رئيــس‬\n     ‫كتابــة عــدل جنــران املكلــف رقــم ‪ 2865‬يف ‪1432/10/30‬هـ املتضمن‬\n     ‫أن الصــك رقــم ‪ 3/35‬ســاري املفعــول وال يوجــد عليــه مالحظــة حتــى‬\n\n\n‫‪63‬‬\n\f‫تاريخــه كمــا جــرى االطــاع علــى صــورة ســجل الصــك املشــار إليــه‬\n‫املرفقــة بخطــاب رئيــس كتابــة عــدل جنــران املكلــف املشــار إليــه‬\n‫واملتضمنــة انتقــال ملكيــة الصــك للمدعــى عليــه كمــا جــرى االطــاع‬\n‫علــى أســاس إقــرار الواقــف فوجدتــه مطابق ـ ًا لصورتــه املــدون نصهــا‬\n‫ســابق ًا ثــم جــرى ســؤال الطرفــن هــل لــدى أحدهمــا مــا يضيفــه فأجــاب‬\n‫ا ليــس لــدي ســوى مــا ذكــرت هكــذا‬        ‫كل واحــد منهمــا مبفــرده قائـ ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n                                                                       ‫قــررا فبنـ ً‬\n‫يف مجلــس احلكــم بــأن املســجد محــل الدعــوى كان قائمـ ًا قبــل شــرائه‬\n‫للمزرعــة تصلــى فيــه الصلــوات اخلمــس والزال كذلــك وأن الــذي بنــاه‬\n‫هــو (‪ )000‬وملــا جــاء يف إقــرار الواقــف وملــا تقــرر شــرع ًا مــن اســتحباب‬\n‫بنــاء املســاجد ووقفهــا قــال القرطبــي رحمــه اهلل يف املفهــم (ال خــاف‬\n‫بــن األئمــة يف حتبيــس املســاجد والقناطــر )‪ 600/4‬ولعــدم جــواز بيــع‬\n‫األوقــاف لقولــه صلــى اهلل عليــه وســلم (ال يبــاع أصلهــا وال توهــب وال‬\n‫تــورث) متفــق عليــه وجــاء يف كشــاف القنــاع (يــزول ملــك الواقــف عــن‬\n‫العــن املوقوفــة مبجــرد الوقــف وينتقــل امللــك فيهــا إلــى اهلل تعالــى)‬\n‫‪ 34/10‬وجــاء يف كشــاف القنــاع (الوقــف عقــد الزم ‪ ...‬ويحــرم وال يصح‬\n‫بيعــه وال هبتــه وال املناقلــة بــه) ‪ 104/10‬وجــاء يف كشــاف القنــاع) ويلزم‬\n‫الوقــف مبجــرد القــول بــدون حكــم حاكــم) ‪ 104/10‬وألن النظــام قــد‬\n‫جعــل لــوزارة الشــؤون اإلســامية حــق اإلشــراف علــى املســاجد وجلميــع‬\n‫مــا تقــدم فقــد حكمــت بثبــوت وقفيــة املســجد املذكــور يف الدعــوى‬\n‫وملحقاتــه واألرض املقــام عليهــا باحلــدود واألطــوال واملســاحة املشــار‬\n‫إليهــا يف الدعــوى تشــرف عليــه وزارة الشــؤون اإلســامية واألوقــاف‬\n‫والدعــوة واإلرشــاد وأفهمــت املدعــى عليــه بــأن لــه الرجــوع علــى مــن باعه‬\n\n\n                                                                                       ‫‪64‬‬\n\f     ‫إن كان قــد غــره وبعــرض احلكــم علــى الطرفــن قــرر منــدوب فــرع‬\n     ‫وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران‬\n     ‫القناعــة وقــرر املدعــى عليــه االعتــراض وتقــدمي الئحــة اعتراضيــة‬\n     ‫فأجيــب لطلبــه وأفهــم باملراجعــة غــد ًا الثالثــاء الســتالم نســخة مــن‬\n     ‫احلكــم وأن مــدة االعتــراض هــي ثالثــون يوم ـ ًا مــن تاريــخ اإلســتالم‬\n     ‫وبعدهــا يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة ففهــم‬\n     ‫ذلــك وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                  ‫‪1432/11/5‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n     ‫وبرفــع القضيــة حملكمــة االســتئناف مبنطقــة عســير عــادت بقــرار‬\n     ‫املالحظــة الصــادر دائــرة األحــوال الشــخصية رقــم ‪ 3398428‬وتاريــخ‬\n     ‫‪1433/02/23‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n     ‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أوالً‪ :‬لــم جنــد‬\n     ‫أن فضيلتــه اســتلحق الواقــف (‪ )000‬وأخــذ إقــراره بالضبــط علم ـ ًا بــأن‬\n     ‫إجابــة املدعــى عليــه غيــر مالقيــة لدعــوى املدعــي حيث لم يســأل املدعى‬\n     ‫عليــه عــن صحــة احلــدود واألطــوال واملســاحة املذكــورة بدعــوى منــدوب‬\n     ‫األوقــاف ثاني ـ ًا تطبــق حــدود وأطــوال ومســاحة املســجد وملحقاتــه مــن‬\n     ‫قبــل البلديــة علــى الطبيعــة حتــى ال يحصــل اختــاف عــن إفــراغ املســجد‬\n     ‫ثالث ـ ًا لــم يتطــرق فضيلتــه يف حكمــه بإفــراغ املســجد بعــد أن أثبــت‬\n     ‫وقفيتــه حســب دعــوى منــدوب األوقــاف فلمالحظــة مــا ذكــر وإحلــاق‬\n     ‫مــا يســتجد بالضبــط وصورتــه والصــك وســجله واهلل املوفــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف (‪ )000‬ختمــه‬\n     ‫وتوقيعــه قاضــي اســتئناف (‪ )000‬ختمــه وتوقيعــه رئيــس الدائــرة (‪)000‬‬\n\n\n‫‪65‬‬\n\f‫(ختمــه وتوقيعــه ) أ ‪ .‬ه ـ وعليــه فقــد حضــر (‪ )000‬ســعودي اجلنســية‬\n‫مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪ )000‬وبســؤاله عمــا لديــه بشــأن‬\n‫ا إننــي كنــت أملــك املزرعــة‬    ‫وقفــه للمســجد مــدار الدعــوى قــرر قائ ـ ً‬\n‫املذكــورة يف دعــوى األوقــاف وقــد قمــت ببنــاء املســجد املذكــور وقفـ ًا‬\n‫هلل تعالــى مبنافعــه وحرمــه بواقــع متريــن مــن كل جهــة وعنــد بيعــي‬\n‫ا يف‬  ‫للمزرعــة علــى املدعــو (‪ )000‬اشــترطت عليــه أن املســجد ليــس داخـ ً‬\n‫املبيــع وأنــه وقــف هلل تعالــى مــع جميــع ملحقاتــه وحرمــه علمـ ًا بأننــي قــد‬\n‫ســلمت املســجد لألوقــاف قبــل بيعــي للمزرعــة هكــذا قــرر لــذا جــرى‬\n‫إثباتــه كمــا جــرى منــي مخاطبــة أمانــة منطقــة جنــران لتطبيــق حــدود‬\n‫وأطــوال ومســاحة املســجد وملحقاتــه واملصادقــة علــى الكروكــي‬\n‫وذلــك بخطاباتنــا رقــم ‪ 33468818‬يف ‪1433/03/12‬ه ـ ورقــم‬\n‫‪ 33817271‬يف ‪1433/05/04‬ه ـ ورقــم ‪ 33993693‬يف ‪1433/5/25‬ه ـ‬\n‫ورقــم ‪ 331195109‬يف ‪1433/06/24‬ه ـ ورقــم ‪ 331380128‬يف‬\n‫‪1433/07/23‬ه ـ ورقــم ‪ 331708163‬يف ‪1433/09/16‬ه ـ إال أننــا لــم‬\n‫جنــد جتاوب ـ ًا مــن قبــل األمانــة مبــا مت طلبــه وملــا جــاء يف خطــاب أمــن‬\n‫منطقــة جنــران رقــم ‪ 13009‬يف ‪1433/09/19‬ه ـ مــن أنــه طاملــا أن‬\n‫الكروكــي أعــد مــن قبــل مكتــب هندســي متخصــص وقُ ـ ِّـدم مــن قبــل‬\n‫جهــة حكوميــة فإنــه ميكــن األخــذ بــه دون احلاجــة إلــى تطبيقــه ولعــدم‬\n‫جتــاوب املدعــى عليــه ومماطلتــه وإلحلاقــه الضــرر الظاهــر باملســجد‬\n‫ومنافعــه ممــا أدى إلــى تعطيــل منافــع املســجد وهجــران املصلــن لــه‬\n‫ولوقوفنــا علــى املســجد وحلضــور الواقــف وإقــراره بوقفيتــه للمســجد‬\n‫ولــكل مــا ذكــر فلــم يظهــر لــي ســوى مــا حكمــت بــه ســابق ًا مــن إثبــات‬\n‫وقفيــة املســجد املذكــور يف الدعــوى وإفــراغ اجلــزء املقــام عليــه حــال‬\n\n\n                                                                                       ‫‪66‬‬\n\f     ‫تصديــق احلكــم مــن االســتئناف وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1433/10/09‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n     ‫وبعــد وقــد عــادت املعاملــة بكتــاب فضيلــة رئيــس محكمــة االســتئناف‬\n     ‫مبنطقــة عســير رقــم ‪ 33/1906843‬وتاريــخ ‪1434/02/06‬ه ـ وشــفعها‬\n     ‫قــرار التصديــق الصــادر مــن دائــرة األحــوال الشــخصية مبحكمــة‬\n     ‫االســتئناف مبنطقــة عســير برقــم ‪ 348289‬يف ‪1434/1/11‬ه ـ املظهــر‬\n     ‫مبوجبــه علــى صــك احلكــم ونــص احلاجــة منــه (وحيــث ســبق دراســة‬\n     ‫الصــك وصــورة ضبطــه والالئحة االعتراضيــة وأوراق املعاملة وباالطالع‬\n     ‫ـاء علــى‬‫علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنـ ً‬\n     ‫قــرار الدائــرة رقــم وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى‬\n     ‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n     ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ) أ‬\n     ‫‪ .‬ه ـ ومبوجبــه أمــرت بالتهميــش بذلــك علــى الصــك وســجله وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/02/13‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n     ‫بتدقيــق قضايــا األحــوال الشــخصية واألوقــاف والوصايــا والقصــار‬\n     ‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة لهــذه احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة الشــيخ‬\n     ‫(‪ ).....‬برقــم وتاريــخ ‪1433/10/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n     ‫فضيلتــه واملســجل برقــم (‪ ).....‬وتاريــخ ‪1432/11/5‬ه ـ واخلاصــة بدعــوى‬\n\n\n‫‪67‬‬\n\f‫فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد ضــد بشــأن‬\n‫إفــراغ مســجد علــى الصفــة املوضحــة بالصــك واملتضمن حكــم فضيلته‬\n‫مبــا هــو مــدون بباطنــه وحيــث ســبق دراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫ـاء علــى قــرار الدائــرة رقــم‬\n                              ‫فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنـ ً‬\n‫وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n‫دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n‫وبعــد وقــد عــادت املعاملــة بكتــاب فضيلــة رئيــس محكمــة االســتئناف‬\n‫مبنطقــة عســير رقــم ‪ 331906843‬وتاريــخ ‪1434/2/6‬ه ـ وشــفعها قــرار‬\n‫التصديــق الصــادر مــن دائــرة األحــوال الشــخصية مبحكمــة االســتئناف‬\n‫مبنطقــة عســير برقــم ‪ 348289‬يف ‪1434/1/11‬ه ـ املظهــر مبوجبــه‬\n‫علــى صــك احلكــم ونــص احلاجــة منــه (وحيــث ســبق دراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنــاء علــى قــرار‬\n‫الدائــرة رقــم ‪ 3398428‬وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه)‬\n‫أ‪.‬ه ـ ومبوجبــه أمــرت بالتهميــش علــى الصــك وســجله وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/13‬هــ‪.‬‬\n\n\n                                                                                   ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":57,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93d88e7d9b1e971ce95b52b623ad0eac8939adc7507a0a8f5f9aae40b2906234","normalized_text_hash":"ab60b79e0fa39408128ade691e33052067ea5c66d2382b3f79a6972f18cc713e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p57-32297345"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"fb28b985-ad93-5c71-b896-84373e88114a","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -شرط موافقة املدعي على املشتري اجلار- نقض الشرط وإمتام البيع دون موافقة املدعي -الدعوى باملطالبة بالشفعة تقام على من بيده العن -عدم وجود مرفق مشترك بن املدعي واجلار -صرف النظر عن الدعوى .","document_number":"3460931","case_number":"33342513","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف بفتح هذه اجللسة","circuit":"الدائرة بصرف النظر عن دعوى املدعي جتاه املدعى عليه وأخلت","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"شفعة -شفعة جار -شرط موافقة املدعي على املشتري اجلار- نقض الشرط وإمتام البيع دون موافقة املدعي -الدعوى باملطالبة بالشفعة تقام على من بيده العن -عدم وجود مرفق مشترك بن املدعي واجلار -صرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/11 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3460931 :‬‬\n                         ‫َر ْق ُم الدعوى‪33342513 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34214373‬تاريخه‪1434/5/18:‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬شــرط موافقــة املدعــي علــى املشــتري اجلــار‪-‬‬\n      ‫نقــض الشــرط وإمتــام البيــع دون موافقــة املدعــي‪ -‬الدعــوى باملطالبــة‬\n      ‫بالشــفعة تقــام علــى مــن بيــده العــن‪ -‬عــدم وجــود مرفــق مشــترك بــن‬\n                                ‫املدعــي واجلــار‪ -‬صــرف النظــر عــن الدعــوى ‪.‬‬\n\n\n\n      ‫حديــث جابــر ‪ -‬رضــي اهلل عنــه ‪»:-‬أن النبــي صلــى اهلل عليــه وســلم قضى‬\n      ‫بالشــفعة يف كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق‬\n                                                ‫فــا شــفعة» أخرجــه البخــاري‪.‬‬\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صديقــه وملــا علــم بأنــه‬\n      ‫يبحــث عــن منــزل وأن جــاره عــرض منزلــه للبيــع فشــفع املدعــي لــه لــدى‬\n      ‫البائــع فحســم خمســن ألــف ريــال ألجــل شــفاعته كمــا أعفــاه عــن‬\n      ‫أجــرة الســعي املســتحقة لــه بشــرط أال يبيــع املنــزل علــى أحــد إال بإذنــه‬\n      ‫وموافقتــه ليختــار اجلــار املناســب وأنــه وافــق علــى هــذا الشــرط‪ -‬حيــث‬\n      ‫إن املدعــى عليــه لــم يلتــزم بهــذا الشــرط فقــد أقــام عليــه دعــوى بطلــب‬\n      ‫الشــفعة يف العقــار وإلزامــه بدفــع مــا حســمه البائــع ألجــل شــفاعته لــه‬\n      ‫خمســن ألــف ريــال ‪ -‬أقــر املدعــى عليــه بشــراء املنــزل وأنكــر أنــه‬\n      ‫اشــتراه بــدون ثمــن املثــل وطلــب رد دعــوى املدعــي لكونــه غيــر ذي صفــة‬\n‫‪359‬‬\n\f‫فليــس مالــكا للمنــزل وأن املدعــي اســتلم أجــرة الســعي بحكــم مــن‬\n‫احملكمــة اجلزائيــة ‪ -‬أقــر املدعــي بصــدور حكــم لــه بأجــرة الســعي‬\n‫واســتالمه للمبلــغ ‪ -‬قــرر املدعــي بــأن بائــع املنــزل لــم يوكلــه يف املطالبــة‬\n‫باخلمســن ألــف ريــال ولــم يتنــازل لــه بهــا ولــم يشــترط البائــع علــى‬\n‫املدعــى عليــه ذلــك ‪ -‬عليــه وملــا قــرره املدعــي أن مبلــغ اخلمســن ألــف‬\n‫ريــال التــي تنــازل عنهــا بائــع املنــزل للمدعــى عليــه لــم تكــن مشــروطة‬\n‫علــى املدعــى عليــه أال يبيعهــا علــى مــن ال يرتضــي املدعــي جيرتــه وأن‬\n‫بائــع املنــزل لــم يوكلــه يف مطالبــة املدعــى عليــه باملبلــغ املذكــور وإقــرار‬\n‫املدعــي أن املنــزل محــل النــزاع يف حــي ســكني ال يوجــد بينهمــا حــق‬\n‫مشــترك مــن طريــق خــاص ونحــوه‪ ،‬وحلديــث جابــر رضــي اهلل عنــه عنــد‬\n‫البخــاري أن النبــي صلــى اهلل عليــه وســلم «قضــى بالشــفعة يف كل مــا‬\n‫لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة» كمــا أن‬\n‫املطالبــة بالشــفعة تقــام علــى مــن بيــده العــن جلميــع ذلــك فقــد حكمــت‬\n‫الدائــرة بصــرف النظــر عــن دعــوى املدعــي جتــاه املدعــى عليــه وأخلــت‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعوى‪-‬بعــرض ذلــك علــى الطرفــن قــرر‬\n‫املدعــى عليــه القناعــة وأمــا املدعــي فقــرر عــدم القناعــة وطلــب رفعــه‬\n‫حملكمــة االســتئناف بالئحــة اعتراضيــة ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n\n                                                                                        ‫‪360‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....................‬املــازم القضائــي لــدى‬\n      ‫فضيلــة الشــيخ ‪ .........................‬القاضــي باحملكمــة العامــة بالريــاض‬\n      ‫واملكلــف بفتــح هــذه اجللســة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪33342513‬‬\n      ‫وتاريــخ ‪1433/05/17‬ه املقيــدة باحملكمــة برقــم ‪33933734‬‬\n      ‫وتاريــخ ‪1433/05/17‬ه ففــي يــوم الســبت املوافق‪1433/08/17‬ه ـ‬\n      ‫حضــر املدعــي ‪ ......................‬ســعودي اجلنســية ســجل مدنــي رقــم‬\n      ‫………………‪ ..‬ولــم يحضــر املدعــى عليــه وال وكيــل عنــه ووردنــا‬\n      ‫محضــر التبليــغ رقــم ‪ 33933734‬يف ‪1433/5/24‬ه ـ املتضمــن أنــه مت‬\n      ‫تبليــغ املدعــى عليــه لشــخصه وتســلم صــورة مــن ورقــة التبليــغ مبوعــد‬\n      ‫اجللســة ولكــون املدعــى عليــه تبلــغ لشــخصه فقــد قــررت ســماع الدعوى‬\n      ‫غيابيــا وبســؤال املدعــي عــن دعــواه قــدم مذكــرة نصهــا مــا يلــي دعــواي‬\n      ‫ضــد املدعــى عليــه بســبب نقضــه للشــرط الــذي مت بيننــا بعــدم بيــع املنــزل‬\n      ‫الــذي تشــفعت لــه بشــرائه لكــي يجاورنــي وذلــك ألي شــخص إال بعــد‬\n      ‫موافقتــي علــى املشــتري وأطلــب حقــي يف املبلــغ الــذي حســم مــن البيعــة‬\n      ‫الســابقة ألجلــي وقــدره خمســون ألــف ريــال لكــي تتــم البيعــة للمدعــو‬\n      ‫‪ ...‬وذلــك مــن املالــك الســابق املدعــو ‪ ...............‬حيــث غــدر بــي وعــدم‬\n      ‫وفائــه للشــرط والوعــد الــذي مت بيننــا بعــدم البيــع إال بعــد مشــاورتي يف‬\n      ‫املشــتري والرجــوع لــي باختيــار مــن يجاورنــي مثلمــا فعلــت عندمــا أراد‬\n      ‫هــو شــراء املنــزل الــذي يجاورنــي وتتمثــل الواقعــة أنــه يف شــهر جمــادي‬\n      ‫اآلخــرة مــن عــام ‪1432‬ه ـ طلــب منــي املذكــور التوســط يف شــراء املنــزل‬\n\n‫‪361‬‬\n\f‫الــذي يجاورنــي وطلــب منــي مســاعدته يف التشــفع لــدى مالــك املنــزل‬\n‫الــذي يجاورنــي مــن أجــل بيعــه للمدعــو ‪ ...‬وبالفعــل حــدث ذلــك ووافــق‬\n‫صاحــب املنــزل علــى بيعــه للمذكــور مببلــغ مليــون ومائتــا ألــف ريــال‬\n‫‪ 1.200.000‬ريــال مــع العلــم بــأن صاحــب املنــزل املدعــو ‪...................‬‬\n‫ـاء علــى تشــفعي لــه ألن الــذي يرغــب يف شــراء‬     ‫تقديــرا حلســن اجلــوار وبنـ ً‬\n‫املنــزل املدعــو ‪ ............‬صديــق لــي قــام بخصــم خمســن ألــف ريــال مــن‬\n‫ســعر ســوم منزلــه حيــث كان مســيوم مببلــغ مليــون ومائتــان وخمســون‬\n‫ألــف ريــال ‪ 1.250.000‬ريــال ومتــت البيعــة وكان نصيبــي مــن الســعي‬\n‫عشــرة آالف ريــال وقــد طلــب منــي املدعــو ‪ ..............‬التنــازل عــن ســعيي‬\n‫تقديــرا لــه وبالفعــل حــدث ذلــك مــن أجــل مســاعدته علــى الــزواج وإعانــة‬\n‫لــه علــى الســكن وتقديــرا للصداقــة التــي كانــت بيننــا ولكــن بشــرط‬\n‫أن يتــزوج ويســكن هــو بجــواري وإذا خالــف ذلــك يكــون ســعيي قائــم‬\n‫ويقدمــه لــي إذا رغــب البيــع وقــد وافــق علــى ذلــك واشــترطنا أن ال تتــم‬\n‫البيعــة إال بعــد مشــاورتي يف املشــتري الــذي يرغــب الســكن بجــواري‬\n‫حيــث كنــت أرغــب أن يكــون مــن منطقــة الريــاض ووافــق علــى ذلــك‬\n‫وبعــد مضــي ســتة أشــهر قــام املذكــور بعــرض املنــزل للبيــع بســبب أنــه‬\n‫لــم يكتــب لــه الــزواج حســب ادعائــه وقــد أخبرنــي بذلــك وتعهــد لــي بــأن‬\n‫ال تتــم البيعــة إال بعــد موافقتــي ومشــاروتي يف الشــخص الــذي يرغــب‬\n‫شــراءه حســب الشــرط املذكــور أعــاه وأن ســعيي محفــوظ وقــدره‬\n‫عشــرة آالف ريــال ولكــن املذكــور خــان عهــده ولــم يــويف حيــث قــام‬\n‫ببيــع املنــزل المــرأة فلســطينية حتمــل جنســية ســعودية ومتزوجــه مــن‬\n‫فلســطيني مببلــغ وقــدره مليــون وأربعمائــة وخمســون ألــف ريــال بــدون‬\n‫مشــاروتي يف املشــتري حســب االتفــاق الــذي مت بيننــا وتفاجــأت بذلــك‬\n\n\n                                                                                         ‫‪362‬‬\n\f      ‫وقمــت باالتصــال عليــه هاتفيــا حيــث أنكــر تعهــده ووعــده وكذلــك‬\n      ‫رفــض تســليمي الســعي املشــترط بيننــا وقــدره عشــرة آالف ريــال فضيلــة‬\n      ‫الشــيخ أطالــب مبــا يلــي ‪ -1‬حــق الشــفعة يف مــن يســكن بجــواري حيــث‬\n      ‫غــدر بــي املدعــو ‪ ...........‬ولــم يبلغنــي مبــن يرغــب يف شــراء املنــزل حيــث‬\n      ‫باعــه علــى امــرأة فلســطينية حتمــل جنســية ســعودية بالرغــم مــن تعهــده‬\n      ‫بعــدم بيعــه إال بعــد الرجــوع لــي وحيــث أن الشــفعة وجــدت إلعطــاء اجلــار‬\n      ‫احلــق يف شــراء منــزل جــاره الختيــار مــن يجــاوره حيــث تضــررت وكنــت‬\n      ‫أرغــب أن يجاورنــي شــخص مــن أبنــاء وطنــي لكي اســتأمن على عائلتي‬\n      ‫يف حالة عدم تواجدي يف املنزل ‪ -2‬املبلغ الذي مت حسمه من قبل جاري‬\n      ‫ســابقا املدعــو ‪ .............‬حيــث حســم مبلــغ وقــدره خمســن ألــف ريــال مــن‬\n      ‫مبلــغ ســوم املنــزل حيــث كان مســيوم مببلــغ مليــون ومائتــان وخمســون‬\n      ‫ألــف ريــال ولكــن تقديــرا منــه جليرتــي قــام بحســم املبلــغ املذكــور‬\n      ‫أعــاه تقديــرا لــي ولشــفاعتي لديــه مــن أجــل بيعــه للمدعــو‪..................‬‬\n      ‫فضيلــة الشــيخ آمــل إلزامــه بدفــع حقوقــي املذكــورة أعــاه واهلل عــز‬\n      ‫وجــل مطلــع علــى مــا حــدث بيننــا هــذه دعــواي ‪ .‬ا‪.‬ه ـ وجــرى رفــع اجللســة‬\n      ‫لتبليــغ املدعــى عليــه ويف جلســة أخــرى لــدي أنــا ‪ ......................‬القاضــي‬\n      ‫باحملكمــة العامــة بالريــاض حضــر املدعــي أصالــة ‪ ...................‬وحضــر‬\n      ‫حلضــوره ‪......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...................‬الوكيــل الشــرعي عــن ‪ .....................‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة عــدل محافظــة الدرعيــة برقــم ‪ 33355108‬يف‬\n      ‫‪1433/7/26‬ه ـ التــي تخولــه مراجعــة احملاكــم الشــرعية وكتابــة‬\n      ‫العــدل والبلديــة وبتــاوة الدعــوى علــى املدعــى عليــه وكالــة قــال ســبق‬\n      ‫وأن مت إرســال إجابــة موكلــي لفضيلتكــم مــن قبــل فضيلــة رئيــس‬\n\n\n‫‪363‬‬\n\f‫هــذه احملكمــة واملقيــدة برقــم ‪ 34/471300‬يف ‪1434/2/25‬ه ـ أطلــب‬\n‫مــن فضيلتكــم ضبطهــا وباالطــاع عليهــا وجدتهــا موقعــة مــن املدعــى‬\n‫عليــه أصالــة ونصهــا اآلتــي أطلــب مــن اهلل ثــم فضيلتكــم احلكــم بــرد‬\n‫الدعــوى املقامــة ضــدي مــن املدعــو ‪ ...........................‬بخصــوص دفــع‬\n‫فــرق القيمــة للفيــا املباعــة علـ ّـي مــن قبــل املدعــو ‪ .....................‬مببلــغ‬\n‫وقــدره خمســون ألــف ريــال حســب زعمــه وذلــك لألســباب اآلتيــة ‪/1‬‬\n‫الدعــوى مقامــة مــن غيــر ذي صفــة فاملدعــي ال ميلــك الفيــا وليــس‬\n‫وكيــا عــن صاحبهــا ‪ /2‬أنــا اشــتريت الفيــا بســعرها وقــت البيــع ومــا‬\n‫زعمــه املدعــي مــن أن صاحــب الفيــا باعنــي بأقــل مــن القيمــة بخمســن‬\n‫ألــف ريــال فعــار عــن الصحــة متامــا ‪ /3‬املدعــي رفــع علـ ّـي دعــوى مطالبــة‬\n‫بالســعي أمــام احملكمــة اجلزئيــة بالريــاض وانتهــت مبوجــب احلكــم‬\n‫الصــادر رقــم ‪ 33243920‬وتاريــخ ‪1433/5/12‬ه ـ املرفــق صورتــه لــدى‬\n‫القاضــي يف احملكمــة اجلزئيــة بالريــاض فضيلــة الشــيخ ‪...................‬‬\n‫املتضمــن اســتالمه لقيمــة مطالبتــه بالســعي ولــم يشــر يف دعــواه إلــى أنــه‬\n‫حصــل لــي علــى تخفيــض مــن قيمــة الفيــا ممــا يــدل علــى بطــان دعــواه‬\n‫‪ /4‬أنــا ضابــط مبــرور الريــاض وعملــي حســاس وســبب لــي مضايقــة يف‬\n‫عملــي وإربــاك باجلهــاز الــذي أعمــل بــه بســبب هــذه الدعــوى الباطلــة‬\n‫لــذا أطلــب مــن اهلل ثــم مــن فضيلتكــم إدخــال املدعــي العــام يف هــذه‬\n‫القضيــة لكــف شــره عنــي وعــن بقيــة النــاس وإذا لــم يــردع فســيتمادى‬\n‫يف غيــه كمــا أطلــب احلكــم بصــرف النظــر عــن دعــواه لعــدم إقامتهــا‬\n‫مــن ذي صفــة وأخــذ التعهــد اخلطــي الشــديد بعــدم مالحقتــي مســتقبال‬\n‫كمــا احتفــظ بحقــي يف طلــب تعويضــي عــن األضــرار املاديــة واملعنويــة‬\n‫التــي ســببها لــي املدعــي بســبب هــذه القضيــة الباطلــة هكــذا أجــاب‬\n\n\n                                                                                             ‫‪364‬‬\n\f      ‫وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى عليــه مــن اســتالمي‬\n      ‫ملبلــغ الســعي املذكــور فهــو صحيــح ومــا عــداه فغيــر صحيــح والصحيــح‬\n      ‫مــا ذكــرت وبســؤال املدعــي هــل مالــك الفيــا الذي اشــترى منــه املدعى‬\n      ‫عليــه أصالــة قــد وكلــه يف املطالبــة مببلــغ اخلمســن ألف املدعــى بها قال‬\n      ‫لــم يوكلنــي املالــك بذلــك إال أن هــذا املبلــغ حســم للمدعــى عليــه بســبب‬\n      ‫وســاطتي كمــا ســألت املدعــي هــل تنــازل املالــك للمدعــى عليــه عــن‬\n      ‫اخلمســن ألــف ريــال كان مشــروطا بالتــزام املشــتري املدعــى عليــه يف‬\n      ‫هــذه الدعــوى بــأن ال يســكن يف الفيــا وال يبيعهــا علــى مــن ال يرتضــي‬\n      ‫جيرتــه أجــاب املدعــي قائــا لــم يشــترط هــذا الشــرط علــى املدعــى عليــه‬\n      ‫إال يف العشــرة آالف ريــال التــي تنازلــت لــه عنهــا ثــم جــرى رفــع اجللســة‬\n      ‫وتأجلــت للنظــر والتأمــل ويف يــوم األربعــاء ‪1434/3/11‬هـ حضر املدعي‬\n      ‫أصالــة ‪...............‬واملدعــى عليــه وكالــة ‪................‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومــا قــرره املدعــي أن مبلــغ اخلمســن ألــف ريــال‬\n      ‫التــي تنــازل عنهــا بائــع الفيــا للمدعــى عليــه لــم تكــن مشــروطة علــى‬\n      ‫املدعــى عليــه أن ال يبيعهــا علــى مــن ال يرتضــي املدعــي جيرتــه وأن بائــع‬\n      ‫الفيــا لــم يوكلــه يف مطالبــة املدعــى عليــه باملبلــغ املذكــور وإقــرار‬\n      ‫املدعــي أن الفيــا محــل النــزاع يف حــي ســكني ال يوجــد بينهمــا حــق‬\n      ‫مشــترك مــن طريــق خــاص ونحــوه وحلديــث جابــر رضــي اهلل عنــه عنــد‬\n      ‫البخــاري أن النبــي صلــى اهلل عليــه وســلم (قضــى بالشــفعة يف كل مــا‬\n      ‫لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة ) هــذا إضافــة‬\n      ‫إلــى أن الدعــوى باملطالبــة بالشــفعة تقــام علــى مــن بيــده العــن جلميــع‬\n      ‫ذلــك فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي جتــاه املدعــى‬\n      ‫عليــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبعــرض ذلــك علــى‬\n\n\n‫‪365‬‬\n\f‫الطرفــن قــرر املدعــى عليــه القناعــة وأمــا املدعــي فقــرر عــدم القناعــة‬\n‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة وأفهمتــه باســتالم‬\n‫نســخة مــن احلكــم يف ‪1434/3/15‬ه ـ لتقــدمي اعتراضــه عليــه خــال‬\n‫ثالثــن يومــا وإال ســقط حقــه يف االعتــراض واكتســب احلكــم القطعية‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬ويف يــوم االثنــن ‪1434/6/5‬ه ـ‬\n‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قــرار الدائــرة الثانيــة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫رقــم ‪ 34214373‬يف ‪1434/5/18‬ه ـ املتضمــن مصادقتهــم علــى احلكــم‬\n                                          ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n‫‪ 33/933734‬وتاريــخ ‪1434/04/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪........................ /‬املســجل برقــم‬\n‫‪ 3460931‬وتاريــخ ‪1434/3/11‬ه اخلــاص بدعــوى ‪............................. /‬‬\n‫ضــد‪ ................./‬و بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫والالئحــة لــم يظهــر مــا يوجــب االعتــراض‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                              ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪366‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":359,"source_page_end":366,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"759cb735c85e68d0a88d19ab8a07c20491cb72f82f408b3d2ed41a19e88cbdb2","normalized_text_hash":"7a5265f75b55867c9919b65166b90ce4df1b9f35c9ec90abf87051da5d6aead5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p359-3460931"},{"id":"a978362a-49e4-5ebb-b199-e8dc2fdd2068","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع أرض زراعية -تأخر املدعي يف إقامة الدعوى رغم العلم بالبيع -طلب الشفعة على الفور -سقوط الشفعة عند التأخر يف طلبها بدون عذر -ما يدون على صك التملك حجة يعتمد عليه -رد دعوى املدعي لعدم ثبوتها .","document_number":"34289201","case_number":"34112070","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالقوارة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/6","year":"1434","subject":"شفعة -شفعة جار -بيع أرض زراعية -تأخر املدعي يف إقامة الدعوى رغم العلم بالبيع -طلب الشفعة على الفور -سقوط الشفعة عند التأخر يف طلبها بدون عذر -ما يدون على صك التملك حجة يعتمد عليه -رد دعوى املدعي لعدم ثبوتها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34289201 :‬‬\n                         ‫َر ْق ُم الدعوى‪34112070 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34332398‬تاريخه‪1434/10/18 :‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع أرض زراعيــة‪ -‬تأخــر املدعــي يف إقامــة الدعوى‬\n      ‫رغــم العلــم بالبيــع‪ -‬طلــب الشــفعة علــى الفــور‪ -‬ســقوط الشــفعة عنــد‬\n      ‫التأخــر يف طلبهــا بــدون عــذر‪ -‬مــا يــدون علــى صــك التملــك حجــة‬\n                              ‫يعتمــد عليــه‪ -‬رد دعــوى املدعــي لعــدم ثبوتهــا ‪.‬‬\n\n\n\n      ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( الشــفعة كحــل العقــال ) رواه ابــن‬\n                                                                       ‫ماجــه ‪.‬‬\n                        ‫‪ -2‬ما رواه عبدالرزاق عن شريح ( الشفعة ملن واثبها ) ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بإثبــات شــفعته لــأرض‬\n      ‫التــي اشــتراها ‪ -‬حيــث اشــترى املدعــى عليــه أرضـ ًا زراعيــة مــن شــقيق‬\n      ‫مــوكل املدعــي مببلــغ ثالثمائــة ألــف ريــال وكان يعتقــد املدعــي أن‬\n      ‫شــقيقه مجــرد وســيط يف األرض بــن البائــع واملشــتري املدعــى عليــه‬\n      ‫ولــم يعلــم موكلــه بــأن شــقيقه قــد اشــترى امللــك لنفســه ثــم باعــه علــى‬\n      ‫املدعــى عليــه إال يف العــام املاضــي ونظــر ًا لوجــود شــراكة بــن موكلــه‬\n      ‫وشــقيقه البائــع يطلــب إثبــات شــفعة موكلــه يف األرض ‪ -‬صــادق املدعى‬\n      ‫عليــه علــى شــراء األرض مــن شــقيق املدعــي وأنكــر شــراكة املدعــي‬\n      ‫لشــقيقه فاملالــك أفــرغ لشــقيق املدعــي ولــم يذكــر لــه شــريك ًا يف امللــك‬\n‫‪367‬‬\n\f‫ولــو كان شــريك ًا ملــوكل املدعــي لذكــر ذلــك يف اإلفــراغ كمــا قــد‬\n‫أقــر املدعــي وكالــة بــأن موكلــه قــد علــم حقيقــة البيــع بــأن شــقيقه‬\n‫اشــترى هــذا امللــك لنفســه وليــس مجــرد وســيط يف العــام املاضــي‬\n‫ولــم يتقــدم بهــذه الدعــوى إال اآلن والشــفعة يطالــب بهــا فــور ًا ويطلــب‬\n‫املدعــى عليــه رد الدعــوى ‪ -‬لــم يتقــدم املدعــي برفــع هــذه الدعــوى رغــم‬\n‫علمــه بعمليــة البيــع منــذ فتــرة ‪ -‬وحيــث إن امللــك الزراعــي املذكــور يف‬\n‫الدعــوى قــد همــش علــى صكــه بأنــه انتقــل لشــقيق املدعــي وليــس فيــه‬\n‫أي إشــارة إلــى شــراكة مــوكل املدعــي لــه وهــذا يناقــض الشــراكة‬\n‫املدعــى بهــا إذ أن مــا يــدون علــى الصــك يعتبــر حجــة يســتند عليــه وحتــى‬\n‫أن هنــاك شــراكة بــن‬     ‫لــو فــرض صحــة مــا ذكــره املدعــي وكالــة مــن َّ‬\n‫موكلــه وبــن شــقيقه فهــذا ال مينــع أن تكــون هنــاك أمــاك ًا يختــص‬\n‫أن املدعــي وكالــة قــد ذكــر‬    ‫بهــا كل واحــد منهمــا عــن اآلخــر وحيــث َّ‬\n‫يف دعــواه بــأن موكلــه قــد علــم بالبيــع واالفــراغ بتاريــخ ‪1433/7/11‬ه ـ‬\n‫أي قبــل ســنة تقريب ـ ًا ولــم يتقــدم بهــذه الدعــوى إال قبــل أربعــة أشــهر‬\n‫تقريب ـ ًا وهــذا يــدل علــى عــدم صحــة الدعــوى إذ لــو كان مــوكل‬\n‫املدعــي صادق ـ ًا ملــا تأخــر يف تقــدمي الدعــوى شــهور ًا بعــد أن علــم أن‬\n‫البيــع قــد مت قبــل عــدة ســنوات والشــفعة «ملــن واثبهــا» رواه عبدالــرزاق‬\n‫عــن شــريح وذكــره الفقهــاء يف كتبهــم والشــفعة كحــل العقــال رواه‬\n‫ابــن ماجــة بســند ضعيــف والفقهــاء قــد نصــوا علــى أن الشــفعة علــى‬\n‫الفــور وقــت علمــه فــإن لــم يطلبهــا بــا عــذر بطلــت وذلــك ألن التراخــي‬\n‫يف طلبهــا يضــر باملشــتري لكونــه ال يســتقر يف ملكــه املبيــع ومينعــه مــن‬\n‫التصــرف ومــا ذكــره املدعــي وكالــة أعــاه مبــرر ًا لتأخــر موكلــه يف‬\n‫تقــدمي الدعــوى ال يعتبــر عــذر ًا مقبــو ًال يف تأخيــر التقــدم بطلــب الشــفعة‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫وحيــث أن امللــك الزراعــي محــل النــزاع قــد أفــرغ باســم املدعــى عليــه‬\n      ‫منــذ تســع ســنوات وخــال كل هــذه الســنوات كان امللــك محــل النــزاع‬\n      ‫بحــوزة املدعــى عليــه ويبعــد أن متــر كل هــذه الســنوات ولــم يعلــم مــوكل‬\n      ‫املدعــي بــأن شــقيقه اشــترى هــذا امللــك ثــم باعــه على املدعــى عليه إ ّال يف‬\n      ‫‪1433/7/11‬ه ‪ -‬صــدر احلكــم بــرد دعــوى املدعــي لعــدم ثبوتهــا ‪ -‬قنــع‬\n      ‫املدعــى عليــه واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n                    ‫احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة العامــة بالقــوارة‬\n      ‫وبناء على املعاملة احملالة لنا برقم ‪ 34112070‬وتاريخ ‪1434/03/08‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34589268‬وتاريــخ ‪ 1434/03/08‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/05/04‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫العاشــرة وأربعــن دقيقــة ‪ 10 : 40‬وفيهــا حضــر ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬الشــرعي عــن ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬وذلــك مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل بريــدة الثانيــة‪ 37667‬يف ‪1433/07/13‬ه ـ املخــول‬\n      ‫للوكيــل فيهــا حــق املطالبــة واملخاصمــة واملدافعــة واملرافعــة والشــفعة‬\n      ‫وإقامــة الدعــاوي وحتريرهــا والــرد عليهــا وتقــدمي الالئحــة االعتراضيــة‬\n      ‫وإقامــة البينــة واالنــكار وطلــب حتليــف اليمــن وقبولهــا ورفضهــا‬\n      ‫والدفــع وقبــول احلكــم ونفيــه و االعتــراض عليــه وطلــب االســتئناف‬\n      ‫والصلــح‪ ..‬الــخ فادعــى علــى احلاضــر معــه لدينــا ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ......‬قائــا يف دعــواه عليــه انــه بتاريــخ‬\n\n‫‪369‬‬\n\f‫‪1425/8/13‬ه ـ بــاع شــقيق موكلــي ‪ ...... ......‬ملــكا زراعيــا يقــع يف‬\n‫بلــدة الصلبيــة مملــوك لــه مبوجــب الصــك الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 17‬يف ‪1419/11/29‬ه ـ وحــدوده وأطوالــه ومســاحته كمــا يلــي‬\n‫مــن الشــمال يحــده بقيــة امللــك بطــول أربعمائــة متــر ومــن اجلنــوب يحــده‬\n‫شــارع عرضــه خمســة وعشــرون متــرا بطــول اربعمائــة متــر وشــرقا‬\n‫يحــده بقيــة امللــك بطــول اربعمائــة متــر وغربــا شــارع عرضــه عشــرون‬\n‫متــر بطــول اربعمائــة متــر ومجمــوع مســاحته مائــة وســتون الــف متــر‬\n‫مربــع بــاع شــقيق موكلــي هــذا امللــك علــى املدعــي عليــه هــذا احلاضــر‬\n‫بثمــن قــدره ثالثمائــة الــف ريــال وأفــرغ هــذا امللــك باســم املدعــي عليــه‬\n‫وكان موكلــي يعتقــد حــن العقــد املــؤرخ بالتاريــخ املذكــور اعــاه‬\n‫بــأن شــقيقه ‪ ......‬مجــرد وســيط بهــذا البيــع بــن املالــك االول لهــذا امللــك‬\n‫وهــو ‪ ......‬وبــن املدعــي عليــه وقــد ذكــر شــقيق موكلــي ملوكلــي بأنــه‬\n‫مجــرد وســيط بينهمــا ولــم يعلــم موكلــي بــان شــقيقه ‪ ......‬قــد اشــترى‬\n‫هــذا امللــك لنفســه مــن ‪ ......‬ثــم باعــه علــى املدعــي عليــه ‪ ......‬اال يف العــام‬\n‫املاضــي فقــط ونظــرا الن موكلــي شــريك لشــقيقه ‪ ......‬يف امالكــه‬\n‫وجتارتــه لــذا فانــي اطلــب اثبــات شــفعة موكلــي يف عقــد البيــع املبــرم‬\n‫بــن شــقيق موكلــي وبــن املدعــي عليــه بنفــس الثمــن فموكلــي ســيدفع‬\n‫للمشــتري وهــو املدعــى عليــه ثالثمائــة الــف ريــال وهــو ثمــن شــرائه‬\n‫للملــك املذكــور يف الدعــوى هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n‫دعــوى املدعــي وكالــة اجــاب بقولــه ســأجيب عــن الدعــوى يف اجللســة‬\n‫القادمــة هكــذا أجــاب علمــا بأنــه قــد أنتهــى وقت اجللســة ولــذا رفعت يف‬\n‫الســاعة احلاديــة عشــرة والنصــف وحــدد للطرفــن موعــد يف يــوم الثالثــاء‬\n‫املوافــق ‪1434/5/28‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n                                                                                            ‫‪370‬‬\n\f      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/04‬ه‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/05/28‬ه ـ‬\n      ‫افتتحــت اجللســة الثانيــة يف الســاعة العاشــرة وفيهــا حضــر املدعــي‬\n      ‫وكالــة واملدعــى عليــه وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالة‬\n      ‫أبــرز إجابتــه يف ثــاث أوراق مت إرفاقهــا يف املعاملــة وأجــاب املدعــى عليــه‬\n      ‫بقولــه إن مضمــون إجابتــي يتلخــص فيمــا يلــي أوالـ مــا ذكــره املدعــي‬\n      ‫وكالــة بــأن شــقيق موكلــه ‪ ......‬بــاع علــي امللــك املذكــور يف الدعــوى‬\n      ‫بثــاث مائــة ألــف ريــال وأنــه أفرغــه لــي فهــذا كلــه صحيــح وقــد أفرغــه‬\n      ‫لــي يف التاريــخ املذكــور يف الدعــوى أمــا مــا ذكــره يف بقيــة دعــواه فغيــر‬\n      ‫صحيــح فقولــه أن موكلــه كان يعتقــد أن شــقيقه ‪ ......‬كان مجــرد‬\n      ‫وســيط يف البيــع املــؤرخ يف ‪1425/8/13‬ه ـ غيــر صحيــح كمــا أن مــا‬\n      ‫ذكــره مــن أن موكلــه شــريك لشــقيقه ‪ ......‬يف امللــك املذكــور كل‬\n      ‫هــذا غيــر صحيــح فامللــك قــد أفــرغ لشــقيق مــوكل املدعــي ‪...... ......‬‬\n      ‫ولــم يذكــر لــه شــريك يف امللــك إذ لــوكان شــريكا ملــوكل املدعــي‬\n      ‫لذكــر ذلــك يف اإلفــراغ ومعلــوم أن الصكــوك ســندات رســمية تثبــت‬\n      ‫صحــة مــا حتتــوي عليــه وإال لكانــت الصكــوك عبثــا كمــا أن املدعــي‬\n      ‫وكالــة قــد أقــر بــأن شــقيق موكلــه قــد اشــترى امللــك لنفســه وهــذا‬\n      ‫ينفــي الشــراكةـ ثانيــا ـ قــد أقــر املدعــي وكالــة بــأن موكلــه قــد علــم‬\n      ‫حقيقــة البيــع بــأن شــقيقه ‪ ......‬اشــترى هــذا امللــك لنفســه وليــس مجــرد‬\n      ‫وســيط يف العــام املاضــي ولــم يتقــدم بهــذه الدعــوى إال اآلن والشــفعة‬\n      ‫يطالــب بهــا فــورا وال تؤخــر لقولــه صلــى اهلل عليه وســلم (الشــفعة كحل‬\n      ‫العقــال) والبــد أن تكــون علــى الفــور ثالث ـاـ الشــراكة التــي ادعــى بهــا‬\n      ‫املدعــي وكالــة حتتــاج الــى إثبــات أي الشــراكة التــي بــن موكلــه‬\n\n\n‫‪371‬‬\n\f‫وبــن شــقيقه ‪ ......‬فــإذا ثبتــت شــراكته فلــه مطالبــة شــريكه يف ثمــن‬\n‫املبيــع ملــا تقــدم فإنــي أطلــب رد الدعــوى هكــذا أجــاب وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة أفــاد بقولــه ســأرد علــى مــا ذكــره املدعــى عليــه‬\n‫يف اجللســة القادمــة هكــذا أجــاب ورفعــت اجللســة يف الســاعة احلاديــة‬\n‫عشــرة وحــدد للطرفــن موعــد يف يــوم الثالثــاء ‪1434/6/20‬ه ـ الســاعة‬\n‫العاشــرة حــرر يف ‪1434/5/28‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                             ‫وآلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/7/22‬ه ـ افتتحــت‬\n‫اجللســة الثالثــة يف الســاعة العاشــرة والنصــف وحضــر فيهــا املدعــي‬\n‫وكالــة واملدعــى عليــه علم ـ ًا أنــه ســبق وأن حــدد للطرفــن موعــد يف‬\n‫يــوم الثالثــاء ‪1434/6/20‬ه ـ وحضــر فيهــا املدعــي وكالــة ولــم يحضــر‬\n‫املدعــى عليــه ولــم تفتــح اجللســة نظــر ًا لكــون الكهربــاء حينئــذ كانــت‬\n‫مقطوعــة ولــم يشــتغل النظــام وبســؤال املدعــي وكالــة عمــا ذكــره‬\n‫املدعــى عليــه أجــاب بقولــه ان لــدي ورقــة محــررة مــن موكلــي اطلــب‬\n‫تدوينهــا وهــي تتضمــن الــرد علــى مــا دفــع بــه املدعــى عليــه ثــم ابــرز‬\n‫الورقــة وهــذا نصهــا «أو ًال ‪ :‬يعلــم اهلل ســبحانه أننــي صــادق فيمــا ذكرته‬\n‫أننــي كنــت أعتقــد جازمـ ًا أن أخــي ‪ ......‬كان وســيطا بــن املدعــى عليــه‬\n‫والبائــع‪ ...... /‬املالــك االول للمزرعــة محــل النــزاع ‪ ،‬وأبــرأ إلــى اهلل أن‬\n‫أظلــم نفســي وغيــري بدعــوى كاذبــة ‪،‬ثانيـ ًا ‪:‬مــا أشــار إليــه أننــا لــو كنــا‬\n‫شــركاء لتــم إصــدار الصــك باســمنا وليــس باســم ‪ ......‬وحــده ينفيــه مــا‬\n‫مت االتفــاق عليــه بيننــا يف عقــد الشــراكة احملــرر عــام ‪1420‬ه ـ حيــث‬\n‫يوجــد عقــارات باســمي وعقــارات باســم االخ ‪ ......‬قبــل خروجــه مــن‬\n‫الشــراكة وعقــارات باســم االخ ‪ ......‬وهــي مشــتركة بيننــا بالســوية ‪،‬‬\n\n\n                                                                                        ‫‪372‬‬\n\f      ‫ثالثـ ًا ‪ :‬مــا أشــار إليــه أن الشــفعة كحــل العقــال الــخ فهــذا صحيــح ولهــذا‬\n      ‫فإننــي فــور علمــي بــأن أخــي ‪ ......‬اشــترى املزرعــة ثــم باعهــا شــفعت يف‬\n      ‫احلــال وأشــهدت احلاضريــن علــى ذلــك ‪ ،‬رابع ـ ًا ‪ :‬ليــس لــي حــق مطالبــة‬\n      ‫أخــي ‪ ......‬بقيمــة املزرعــة مــا دمــت شــريكا ولــي حــق الشــفعة فيهــا ‪،‬‬\n      ‫خامس ـ ًا ‪ :‬الشــفعة شــيء وتقــدمي الدعــوى شــيء آخــر فأنــا فــور علمــي‬\n      ‫شــفعت أمــا تقــدمي الدعــوى فأخرتــه بســبب ‪ 1‬ـ ـ وجــود خصومــة بــن‬\n      ‫أخــي ‪ ......‬واملدعــى عليــه لــدي فضيلتكــم وخشــيت أن أتقــدم بالدعــوى‬\n      ‫فينصــرف الظــن الــى ان الهــدف هــو االربــاك والتشــويش علــى خصــم‬\n      ‫أخــي فأثــرت التريــث حلــن انتهــاء اخلصومــة بينهمــا إال أن تأخــر احلكــم‬\n      ‫بينهمــا أجبرنــي علــى التقــدم بدعــواي ‪ 2 ،‬ـ ـ االســتفادة مــن ســير الدعوى‬\n      ‫بينهمــا فيمــا يثبــت صحــة دعــواي يف الشــفعة ‪ 3 ،‬ـ ـ البحــث عــن مزيــد‬\n      ‫مــن البينــات التــي تثبــت الشــراكة وذلــك ببعــض املعامــات مــع االخريــن‬\n      ‫بينــي وبــن اخــي ‪ ........‬تلــك هــي إجابــة موكلــي عــن مذكــرة املدعــى‬\n      ‫عليــه ‪ ،‬علمــا ان موكلــي يســعى جاهــد ًا للحصــول علــى بعــض االوراق‬\n      ‫الثبوتيــة للتعامــات القدميــة بينــه واخيــه ‪ ......‬مــن جهــة واالشــخاص‬\n      ‫الذيــن مت التعامــل معهــم مــن جهــة اخــرى «‪ .‬انتهــى نصهــا ‪ .‬فجــرى ســؤال‬\n      ‫املدعــي وكالــة متــى علــم موكلــه بــأن شــقيقه ‪ ......‬قــد اشــترى امللــك‬\n      ‫الزراعــي املذكــور اعــاه مــن املالــك ‪ ......‬ومتــى علــم ان امللــك املذكــور‬\n      ‫افــرغ لشــقيقه ‪ ......‬فأجــاب بقولــه ال أعلــم عــن ذلــك وســأرجع ملوكلــي‬\n      ‫لســؤاله عــن ذلــك هكــذا اجــاب والنتهــاء وقــت اجللســة فقــد رفعــت يف‬\n      ‫الســاعة احلاديــة عشــرة والنصــف وحــدد للطرفــن موعــد يف يــوم الســبت‬\n      ‫‪1434/8/6‬ه ـ يف الســاعة العاشــرة ‪ ..‬وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/22‬ه ـ‬\n\n\n‫‪373‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/08/06‬ه ـ‬\n‫افتتحــت اجللســة الرابعــة يف الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وبســؤال املدعــي وكالــة عمــا ســألته عنــه يف‬\n‫آخــر اجللســة املاضيــة فيمــا يتعلــق بوقــت علــم موكلــه بشــراء شــقيقه‬\n‫‪ ......‬امللــك الزراعــي املذكــور مــن املالــك االول ‪ ......‬ووقــت علــم موكلــه‬\n‫بإفــراغ امللــك الزراعــي املذكــور باســم شــقيقه ‪ ......‬وكذلــك متــى‬\n‫علــم موكلــه بإفــراغ امللــك املذكــور باســم املدعــى عليــه ‪ ......‬فأجــاب‬\n‫املدعــي وكالــة بقولــه لــم يعلــم موكلــي بجميــع مــا ذكــر ســواء فيمــا‬\n‫يتعلــق بإفــراغ امللــك باســم شــقيقه ‪ ......‬او إفــراغ امللــك بعــد ذلــك باســم‬\n‫املدعــى عليــه لــم يعلــم عــن ذلــك إ َّال بتاريــخ ‪1433/7/11‬ه ـ وبعــد ان‬\n‫علــم شـ َّهد علــى ذلــك شــهود ًا ووكلنــي فتقدمــت بهــذه الدعــوى هكــذا‬\n‫أجــاب فســألته ملــاذا لــم يتقــدم بهــذه الدعــوى إ َّال قبــل أربعــة أشــهر رغــم‬\n‫علــم موكلــه بالبيــع واالفــراغ للملــك الزراعــي ـ محــل النــزاع ـ قبــل ســنة‬\n‫فأجــاب بقولــه ان ســبب ذلــك هــو وجــود خصومــة بــن شــقيق موكلــي‬\n‫‪ ......‬وبــن املدعــى عليــه ‪ ......‬فلــم يرغــب التشــويش بدعــوى الشــفعة علــى‬\n‫ـاء علــى مــا‬\n           ‫الدعــوى القائمــة بــن ‪ ......‬واملدعــى عليــه هكــذا أجــاب فبنـ ُ‬\n‫تقــدم مــن دعــوى املدعــي وكالــة وإجابــة املدعــى عليــه باملصادقــة علــى‬\n‫دعــوى املدعــي وكالــة فيمــا يتعلــق بشــرائه ـ أي شــراء املدعــى عليــه ـ‬\n‫امللــك الزراعــي املذكــور يف الدعــوى مــن شــقيق مــوكل املدعــي بالثمــن‬\n‫والتاريــخ املذكوريــن يف الدعــوى ونفــى مــا ذكــره املدعــي وكالــة يف‬\n‫دعــواه مــن ان موكلــه كان يعتقــد ان شــقيقه ‪ ......‬كان مجــرد وســيط‬\n‫بــن ‪ ......‬وبــن املدعــى عليــه ‪ ......‬كمــا نفــى املدعــى عليــه مــا ذكــره‬\n‫أن بــن موكلــه وبــن شــقيقه ‪ ......‬شــراكة يف‬          ‫املدعــي وكالــة مــن َّ‬\n\n                                                                                         ‫‪374‬‬\n\f      ‫امللــك الزراعــي املذكــور يف الدعــوى وبعــد االطــاع علــى صــك امللــك‬\n      ‫الزراعــي املذكــور يف الدعــوى وعلــى ســجله فــاذا هــو ســاري املفعــول‬\n      ‫باســم املدعــى عليــه ‪ ......‬وحيــث ان امللــك الزراعــي املذكــور يف الدعــوى‬\n      ‫قــد ظَّ هــر عليــه بأنــه أنتقــل ‪ ......‬وليــس فيــه أي إشــارة الــى شــراكة‬\n      ‫مــوكل املدعــي لــه وهــذا يناقــض الشــراكة املدعــى بهــا إذ إن مــا يــدون‬\n      ‫علــى الصــك يعتبــر حجــة يســتند عليــه وحتــى لــو فــرض صحــة مــا ذكــره‬\n      ‫أن هنــاك شــراكة بــن موكلــه وبــن شــقيقه ‪......‬‬         ‫املدعــي وكالــة مــن َّ‬\n      ‫فهــذا ال مينــع أن تكــون هنــاك أمــاك ًا يختــص بهــا كل واحــد منهمــا‬\n      ‫أن املدعــي وكالــة قــد ذكــر يف دعــواه بــأن موكلــه‬        ‫عــن اآلخــر وحيــث َّ‬\n      ‫قــد علــم بالبيــع واالفــراغ بتاريــخ ‪1433/7/11‬ه ـ أي قبل ســنة تقريب ًا ولم‬\n      ‫يتقــدم بهــذه الدعــوى إال قبــل أربعــة أشــهر تقريبـ ًا وهــذا يــدل علــى عــدم‬\n      ‫صحــة الدعــوى إذ لــو كان مــوكل املدعــي صادق ـ ًا ملــا تأخــر يف تقــدمي‬\n      ‫الدعــوى شــهور ًا بعــد ان علــم أن البيــع قــد مت قبــل عــدة ســنوات والشــفعة‬\n      ‫«ملــن واثبهــا» رواه عبدالــرزاق عــن شــريح وذكــره الفقهــاء يف كتبهــم‬\n      ‫والشــفعة كحــل العقــال رواه ابــن ماجــة بســند ضعيــف والفقهــاء قــد‬\n      ‫نصــوا علــى أن الشــفعة علــى الفــور وقــت علمــه فــإن لــم يطلبهــا بــا عــذر‬\n      ‫بطلــت وذلــك ألن التراخــي يف طلبهــا يضــر باملشــتري لكونــه ال يســتقر‬\n      ‫يف ملكــه املبيــع ومينعــه مــن التصــرف ومــا ذكــره املدعــي وكالــة أعــاه‬\n      ‫مبــرر ًا تأخــر موكلــه يف تقــدمي الدعــوى ال يعتبــر عــذر ًا مقبــو ًال يف تأخيــر‬\n      ‫التقــدم بطلــب الشــفعة فانتظــاره انتهــاء الدعــوى االخــرى التــي بــن ‪......‬‬\n      ‫واملدعــى عليــه ‪ ......‬ال يعــد عــذر ًا مقبــو ًال يف تأخيــر طلــب الشــفعة وحيــث‬\n      ‫أن امللــك الزراعــي ـ محــل النــزاع ـ قــد أفــرغ باســم املدعــى عليــه منــذ‬\n      ‫تســع ســنوات وخــال كل هــذه الســنوات كان امللــك محــل النــزاع‬\n\n\n‫‪375‬‬\n\f‫بحــوزة املدعــى عليــه ويبعــد أن متــر كل هــذه الســنوات ولــم يعلــم مــوكل‬\n‫املدعــي بــأن شــقيقه اشــترى هــذا امللــك ثــم باعــه علــى املدعــى عليــه إ ّال‬\n‫ـدي خصومــة ال تــزال قائمــة بــن املدعــى‬     ‫يف ‪1433/7/11‬ه ـ علم ـ ًا أن لـ َّ‬\n‫عليــه وشــقيق مــوكل املدعــي ‪ ......‬بخصــوص معــدات يف نفــس هــذا‬\n‫امللــك الزراعــي ـ محــل النــزاع ـ وقــد يكــون ســبب تقــدمي هــذه الدعــوى‬\n‫هــو تلــك الدعــوى القائمــة بــن املدعــى عليــه و‪ ......‬ملــا تقــدم لــم تثبــت‬\n‫ـدي دعــوى املدعــي وكالــة فــرددت دعــواه وبذلــك حكمــت واهلل أعلــم‬            ‫لـ َّ‬\n‫وأحكــم وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه‬\n‫أمــا املدعــي وكالــة فقــد قــرر عــدم القناعــة بــه وطلــب رفعــه حملكمــة‬\n‫االســتئناف بالئحــة اعتراضيــة فــأ فهمتــه بــأن مــدة االعتــراض ثالثــون‬\n‫ـار ًا مــن تاريــخ هــذا اليــوم ليقــدم اعتراضــه خاللهــا وإذا انتهــت‬\n                                                                        ‫يومـ ًا اعتبـ ً‬\n‫هــذه املــدة ولــم يقــدم اعتراضــه خاللهــا فــإن احلكــم يعتبــر مكتســب ًا‬\n‫للصفــة القطعيــة ففهــم ذلــك ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/06‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫ففــي يــوم األحــد ‪1434/8/28‬ه ـ افتتحــت اجللســة اخلامســة يف الســاعة‬\n‫التاســعة وجــرى االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــي‬\n‫‪ ......‬ولــم أجــد فيهــا مــا يؤثــر علــى احلكــم وقــررت رفــع املعاملــة وبرفقهــا‬\n‫الالئحــة االعتراضيــة حملكمــة االســتئناف مبنطقــة القصيــم لتدقيــق‬\n‫احلكــم ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1434/08/28‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n\n\n                                                                                           ‫‪376‬‬\n\f      ‫ال ـمـ ــحكمة الـ ـع ــام ـ ــة بالقــوارة الشــيخ ‪ ...... /‬ب ــرق ـ ــم (‪)342200667‬‬\n      ‫وتــاري ـ ــخ ‪1434/9/16‬هـ ؛ احملالة إلينا برقم (‪ )34436092‬؛ الــمرف ـ ــق‬\n      ‫بها ال ـصــك الــمسج ــل ب ــرق ــم (‪ )......‬وت ــاريـ ــخ ‪1434/8/6‬هـ ؛ الصادر‬\n      ‫ا عــن ‪ ......‬ضــد‪، ...... /‬‬\n                                 ‫مــن فضيلتــه ؛ اخلــاص بدعــوى‪ ...... ...... /‬وكيـ ً‬\n      ‫بشــأن املطالبــة بإثبــات شــفعة مــوكل املدعــي يف بيــع ملــك زراعــي‪ ،‬وقــد‬\n      ‫تضمــن الصــك حكــم فضيلتــه أنــه لــم تثبــت لديــه دعوى املدعــي وكالة‬\n      ‫ورد دعــواه؛ علــى النحــو املفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة ‪ ،‬قررنــا املصادقــة علــى احلكــم‪.‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪377‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":367,"source_page_end":377,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"abdbf9fe3aa1f01a6f08e2b97929fc655f15533042054cef9c12dc5500af472c","normalized_text_hash":"f1dce50822bd7cb0f43bdda037ace9ce004351f6258da020d8d39e87335de253","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p367-34289201"},{"id":"9d6ff593-71e1-50cb-8d28-a90a03293cfb","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع أرض زراعية -إقرار املدعي بامتاك املدعى عليه (املشتري) لقطعة أرض مالصقة لأرض محل الدعوى- اإلقرار بوجود مسقى مستقل وفواصل بن أرض املدعي واألرض محل الدعوى -إذا وقعت احلدود وصرفت الطرق فا شفعة -صرف النظر عن الدعوى.","document_number":"34232609","case_number":"34134568","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/6","year":"1434","subject":"شفعة -شفعة جار -بيع أرض زراعية -إقرار املدعي بامتاك املدعى عليه (املشتري) لقطعة أرض مالصقة لأرض محل الدعوى- اإلقرار بوجود مسقى مستقل وفواصل بن أرض املدعي واألرض محل الدعوى -إذا وقعت احلدود وصرفت الطرق فا شفعة -صرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34232609 :‬‬\n                   ‫َر ْق ُم الدعوى‪34134568 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34355968‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع أرض زراعيــة‪ -‬إقــرار املدعــي بامتــاك املدعــى‬\n‫عليــه (املشــتري) لقطعــة أرض مالصقــة لــأرض محــل الدعــوى‪-‬‬\n‫اإلقــرار بوجــود مســقى مســتقل وفواصــل بــن أرض املدعــي واألرض‬\n‫محــل الدعــوى‪ -‬إذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة‪ -‬صــرف‬\n                                                      ‫النظــر عــن الدعــوى‪.‬‬\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (فــإذا وقعــت احلــدود وصرفــت الطــرق فــا‬\n                                                   ‫شــفعة) رواه البخــاري‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بــأن لــه أرض ـ ًا زراعيــة ويالصقهــا‬\n‫ركيــب جــاره وال يفصــل بــن املزرعتــن ســوى عقــم صغيــر وقــد باعــه‬\n‫علــى املدعــى عليــه ومبــا أنــه أحــق بهــذا الركيــب مــن املدعــى عليــه‬\n‫يطلــب حــق الشــفعة يف هــذا الركيــب هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n‫عليــه باملصادقــة علــى الدعــوى وأن جــار املدعــي الــذي باعــه الركيــب‬\n‫هــو خالــه وجــاره مــن اجلهــة الشــرقية وأنــه اشــتراه منــذ خمســة عشــر‬\n‫عام ـ ًا ولــه مصلحــة مــن ذلــك ليتمكــن مــن فتــح طريــق مــن خاللــه إلــى‬\n‫ركيبــه ويرفــض طلــب املدعــي الشــفعة هكــذا أجــاب ‪ -‬صــادق املدعــي‬\n\n                                                                                  ‫‪378‬‬\n\f      ‫بــأن للمدعــى عليــه ركيــب مالصــق لركيــب خالــه مــن اجلهــة الشــرقية‬\n      ‫‪ -‬قــرر الطرفــان بــأن لــكل ركيــب مســقى مســتقل ‪ -‬مبــا أن املدعــي‬\n      ‫أقــر بــأن للمدعــى عليــه أرض مالصقــة لــأرض املدعــى بهــا مــن جهتهــا‬\n      ‫الشــرقية وأن لــكل مــن أرضــه واألرض محــل الدعــوى مســقى مســتقل‬\n      ‫وأن أرضــه وأرض املدعــى عليــه واألرض املدعــى بهــا مفصــول بعضهــا‬\n      ‫عــن بعــض واضحــة املعالــم بينــة احلــدود‪ -‬ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫( فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعه ) ‪ -‬ومبــا أن املدعــي‬\n      ‫ليــس بأولــى بهــذه األرض مــن املدعــى عليــه ألن كالهما مجاور لها ‪ -‬ملا‬\n      ‫تقــدم صــدر احلكــم بصــرف النظــر عــن الدعــوى لعــدم ثبــوت موجبهــا‪-‬‬\n      ‫اعتــرض املدعــي علــى احلكــم بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة قلــوة وبنــاء علــى‬\n      ‫املعاملــة احملالــة ملكتبنــا برقــم ‪ 34134568‬وتاريــخ ‪1434/03/22‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34713517‬وتاريــخ ‪ 1434/03/22‬ه ـ املتعلقة‬\n      ‫بدعــوى ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n      ‫ضــد ‪.......‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬ففــي يــوم األربعــاء‬\n      ‫امل ـ ـ ــوافق‪ 1434/05/15‬ه ـ افتتحــت اجللســة الـ ــساع ـ ـ ــة ‪ 10 : 30‬وفيهــا‬\n      ‫ا أن لــي ارضـ ًا‬ ‫حضــر الطرفــان وبســؤال املدعــي عــن دعــواه ادعــى قائـ ً‬\n      ‫زراعيــه تقــع يف وادي نيــرا ويالصقهــا مــن اجلهــة الشــمالية ‪.......‬وهــو مــن‬\n      ‫جماعتنــا وال يفصــل بــن املزرعتــن ســوى عقــم صغيــر وقــد قــام ‪.....‬‬\n\n‫‪379‬‬\n\f‫املذكــور ببيــع هــذا الركيــب علــى املدعــى عليــه وحيــث أننــي أحــق‬\n‫بهــذا الركيــب مــن املدعــى عليــه حيــث أنــه ليــس مــن جماعتنــا فإنــي‬\n‫أطالــب بحــق الشــفعة يف هــذا الركيــب هــذه دعــواي وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه أن لــه أرضـ ًا زراعيــه تقــع‬\n‫يف وادي نيــرا ويالصقهــا مــن اجلهــة الشــمالية ‪.......‬وال يفصــل بينهمــا‬\n‫ســوى عقــم صغيــر واننــي اشــتريت ركيــب ‪ .....‬هــذا كلــه صحيــح‬\n‫و‪ ...........‬املذكــور هــو خالــي وقــد اشــتريت الركيــب املذكــور قبــل‬\n‫خمســة عشــر ســنه بخمســن الــف ري ــال الن لــي ركيبـ ًا زراعيـ ًا مالصــق‬\n‫لركيــب خالــي املذكــور مــن اجلهــة الشــرقية واشــتريت ركيــب خالــي‬\n‫ألمتكــن مــن فتــح طريــق مــن خاللــه إلــى ركيبــي ألن طريقــي األول‬\n‫إلــى ركيبــي بعيــد وفيــه مشــقه لــي وأنــا أرفــض مــا طالــب بــه املدعــي‬\n‫مــن الشــفعة ألنــه ليــس أولــى منــي يف ركيــب ‪ .....‬وكالنــا مجــاور لــه‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى عليــه‬\n‫أن لــه ركيب ـ ًا مالصق ـ ًا لركيــب خالــه مــن اجلهــة الشــرقية صحيــح‬\n‫ولكــن يفصــل بينهمــا عــراق وشــبك ومــا ذكــره انــه اشــتراه قبــل خمــس‬\n‫عشــرة ســنه بخمســن الــف ري ــال فهــذا ال أعلــم عنــه شــيئ ًا هكــذا قــرر‬\n‫ـكل‬\n ‫وبســؤال املدعــي هــل ركيبــه وركيــب ‪ ....‬لهــا مســقى واحــد أم لـ ٍ‬\n‫منهمــا مســقى قــال لــكل منهمــا مســقى هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي لــكل مــن ركيبــه و‪.......‬‬\n‫مســقى مســتقل صحيــح هكــذا قــرر ورفعــت اجللســة للتأمــل ويف جلســة‬\n‫اخــرى وفيهــا حضــر الطرفــان وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n‫وحيــث اقــر املدعــي أن للمدعــى عليــه أرضــا مالصقــة لــأرض محــل‬\n‫الدعــوى مــن جهتهــا الشــرقية واقــر بــأن لــكل مــن أرضــه واالرض محــل‬\n\n\n                                                                                       ‫‪380‬‬\n\f      ‫الدعــوى مســقى مســتقل وأقــر أن أرضــه وأرض املدعــى عليــه واألرض‬\n      ‫أراض واضحــه املعالــم‬‫ٍ‬      ‫محــل الدعــوى مفصــول بعضهــا عــن بعــض وهــي‬\n      ‫بينــة احلــدود وملــا رواه البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه‬\n      ‫وســلم قــال (فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعه ) واملدعــي‬\n      ‫ليــس بأولــى بهــذه األرض مــن املدعــى عليــه ألن كالهمــا مجــاور لهــا‬\n      ‫ومــا ذكــره املدعــي مــن أن املدعــى عليــه ليــس مــن جماعتهــم وبالتالــي‬\n      ‫يكــون هــو أحــق بــاألرض منــه كالم يف غيــر محلــه وال وجاهــة لــه البتــه‬\n      ‫الن هــذا الوصــف واحلــال مــا ذكــر ال يبطــل حــق املدعــى عليــه يف بيــع‬\n      ‫شــرعي مســتكمل لشــروطه وأركانــه لذلــك كلــه فقــد صرفــت النظر‬\n      ‫عــن دعــوى املدعــي لعــدم ثبــوت موجبهــا وبــه حكمــت وبعــرض ذلــك‬\n      ‫علــى املدعــي قــرر عــدم قناعتــه وقــررت تســليمه نســخه مــن احلكــم يف‬\n      ‫هــذه اجللســة وأفهمــت أن لــه مــدة وقدرهــا ثالثــون يومـ ًا لتقــدمي اعتراضــه‬\n      ‫واذا لــم يتقــدم باعتراضــه خــال هــذه املــدة فيســقط حقــه يف طلــب‬\n      ‫االســتئناف ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة‬\n      ‫‪ 09:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/06‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪.......‬رئيــس احملكمــة العامــة مبحافظــة قلــوة واملســجل بعــدد‬\n      ‫‪ 34232609‬وتــاري ــخ ‪1434/6 /6‬ه ـ املتضمــن دعــوى ‪.......‬ضــد ‪.......‬يف‬\n                                               ‫أرض احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n\n\n‫‪381‬‬\n\f‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا‬\n                                            ‫محم ــد وعل ــى آل ــه وصحب ــه وس ــلم‪.‬‬\n\n\n\n\n                                                                                             ‫‪382‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                   ‫املوضوع‬                       ‫التصنيف‬       ‫م‬\n\n         ‫منازعة يف تنفيذ عقد فرش وديكور‪ ،‬ويطالب‬\n         ‫املدعي بندب خبير إلحصاء األعمال التي قام‬\n  ‫‪5‬‬      ‫بها املدعى عليه وإلزامه بإكمال النواقص إن‬   ‫عقد مقاولة‬      ‫‪1‬‬\n                            ‫وجدت‬\n\n         ‫مدع بقيمة أعمال مقاولة واملدعى عليه‬\n                                         ‫مطالبة ٍ‬\n  ‫‪11‬‬              ‫يدفع بالسداد وال بينة له‬           ‫عقد مقاولة‬      ‫‪2‬‬\n\n         ‫مطالبة بإكمال أعمال مقاولة وغرامة شرط‬\n  ‫‪15‬‬         ‫جزائي يف عقد مقاولة ذي جهالة‬            ‫عقد مقاولة‬      ‫‪3‬‬\n\n          ‫مطالبة بإعادة جزء من عوض جعالة لم ينفذ‬\n  ‫‪27‬‬     ‫مطالبة بقيمة العامل املدعى عليه فيه املطلوب مع مرور املدى‬   ‫‪4‬‬\n                ‫الزمني املتفق عليه إلنهاء املطلوب‬        ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة سمسرة(سعي)متعارف عليها يف‬\n  ‫‪33‬‬                ‫قيمة أرض من البائع‬                               ‫‪5‬‬\n                                                   ‫أتعاب‬\n\n          ‫مطالبة بأتعاب تعقيب يف عقد وكالة بأجرة‬     ‫مطالبة بقيمة‬\n  ‫‪40‬‬                                                                 ‫‪6‬‬\n                                                        ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة سمسرة عقار من مشتر غائب لم‬\n  ‫‪57‬‬               ‫يحضر الدعوى مع تبلغه‬                              ‫‪7‬‬\n                                                    ‫أتعاب‬\n\n           ‫مطالبة بأتعاب محاماة لدى القاضي ناظر‬      ‫مطالبة بقيمة‬\n  ‫‪65‬‬                  ‫الدعوى األصل‬                                   ‫‪8‬‬\n                                                        ‫أتعاب‬\n\n          ‫مطالبة بأثر شرط جزائي يف عقد جعالة أو‬      ‫مطالبة بقيمة‬\n  ‫‪84‬‬         ‫إجارة على استخراج حجة استحكام‬                           ‫‪9‬‬\n                                                        ‫أتعاب‬\n\n                   ‫مطالبة بأتعاب محاماة‬              ‫مطالبة بقيمة‬\n  ‫‪92‬‬                                                                 ‫‪10‬‬\n                                                        ‫أتعاب‬\n\f‫الصفحة‬                    ‫املوضوع‬                        ‫التصنيف‬      ‫م‬\n\n               ‫إلزام مدعى عليه بأجرة محاماة‬            ‫مطالبة بقيمة‬\n  ‫‪98‬‬                                                                  ‫‪11‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة سمسرة (سعي) لفسخ‬          ‫مطالبة بقيمة‬\n ‫‪104‬‬             ‫البيع وإقالة املشتري منه‬                             ‫‪12‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة ورثة بأتعاب محاماة مورثهم من ورثة‬     ‫مطالبة بقيمة‬\n ‫‪110‬‬                       ‫متوفى‬                                      ‫‪13‬‬\n                                                          ‫أتعاب‬\n\n         ‫مطالبة بإعادة أجرة سمسرة (داللة) يف شراء‬      ‫مطالبة بقيمة‬\n ‫‪201‬‬                     ‫عقار لم يتم‬                                  ‫‪14‬‬\n                                                          ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة باسترداد أجرة سمسرة (داللة) لبطالن‬\n ‫‪209‬‬                      ‫عقد البيع‬                                   ‫‪15‬‬\n                                                      ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة استقدام خادمة أعيدت‬\n         ‫ملكتب املدعى عليه المتناعها عن العمل فترة‬     ‫مطالبة بقيمة‬\n ‫‪221‬‬                                                                  ‫‪16‬‬\n                     ‫التجربة املتفق عليها‬                 ‫أتعاب‬\n\n          ‫مطالبة بإعادة أجرة أعمال تعقيب لم تنجز‪،‬‬\n           ‫والعقد بني الطرفني ينص على استحقاق‬          ‫مطالبة بقيمة‬\n ‫‪227‬‬                                                                  ‫‪17‬‬\n              ‫األجرة يف حال فسخها من املدعي‬               ‫أتعاب‬\n\n          ‫احلكم بأجرة املثل ملدع انتحل صفة احملامي‬     ‫مطالبة بقيمة‬\n ‫‪241‬‬       ‫ويطالب بأتعاب محاماته من املدعى عليه‬                       ‫‪18‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة بباقي أتعاب عقد استشارات إدارية‬       ‫مطالبة بقيمة‬\n ‫‪260‬‬                      ‫وتربوية‬                                     ‫‪19‬‬\n                                                          ‫أتعاب‬\n\n          ‫مطالبة عاملة منزلية بتنفيذ العقد أو دفع ما‬   ‫مطالبة بقيمة‬\n ‫‪272‬‬            ‫غرمه املدعي ألجل استقدامها‬                            ‫‪20‬‬\n                                                          ‫أتعاب‬\n\f‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬      ‫م‬\n\n          ‫إلزام بالتحكيم يف منازعة يف أجرة محاماة‬\n           ‫اتفق الطرفان يف العقد بينهما على معاجلة‬    ‫مطالبة بقيمة‬\n ‫‪276‬‬                                                                 ‫‪21‬‬\n                       ‫النزاع بينهما به‬                  ‫أتعاب‬\n\n          ‫دعوى خادمة منزلية بباقي رواتبها‪ ،‬واملدعى‬    ‫مطالبة بقيمة‬\n ‫‪289‬‬             ‫عليه يدفع بحسمه ملا أتلفته‬                          ‫‪22‬‬\n                                                         ‫أتعاب‬\n\n            ‫مطالبة بأتعاب محاماة يف دعوى ال تزال‬      ‫مطالبة بقيمة‬\n ‫‪294‬‬                       ‫منظورة‬                                    ‫‪23‬‬\n                                                         ‫أتعاب‬\n\n          ‫مطالبة محام باحلجز التحفظي على أمالك‬        ‫مطالبة بقيمة‬\n ‫‪301‬‬     ‫للمدعى عليها حفظا ألتعابه يف محاماته عنها‬                   ‫‪24‬‬\n                                                         ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأتعاب محاماة من مدعى عليهم لتعاقد‬\n ‫‪305‬‬                  ‫مورثهم مع املدعي‬                               ‫‪25‬‬\n                                                      ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بأجرة عمل تعقيب من املدعى عليه وال‬\n ‫‪316‬‬                     ‫بينة للمدعي‬                                 ‫‪26‬‬\n                                                      ‫أتعاب‬\n\n           ‫مطالبة بأجرة محاماة‪ ،‬واملدعى عليه يدفع‬\n          ‫بأن املتفق عليه من أتعابه على املستحصل ال‬   ‫مطالبة بقيمة‬\n ‫‪322‬‬                                                                 ‫‪27‬‬\n                          ‫املستحق‬                        ‫أتعاب‬\n\n          ‫مطالبة عاملة منزلية بالرجوع إلى العمل لدى‬\n ‫‪330‬‬     ‫مطالبة بقيمة املدعي باقي مدة العقد بينهما أو دفع ما غرمه‬    ‫‪28‬‬\n                     ‫لقاء استقدامه لها‬                  ‫أتعاب‬\n\n         ‫مطالبة بقيمة مطالبة بإعادة أجرة أعمال تعقيب جتديد إقامة‬\n ‫‪335‬‬               ‫عامل لعدم إجناز العمل‬                             ‫‪29‬‬\n                                                       ‫أتعاب‬\n\n         ‫مطالبة بالشفعة يف شراء مزرعة مجاورة ملزرعة‬\n ‫‪343‬‬                       ‫املدعي‬                        ‫شفعة‬        ‫‪30‬‬\n\f‫الصفحة‬                   ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة مدع بالشفعة وإلزام مدعى عليه مبا‬\n         ‫حسم له نتيجة توسط املدعى عليه الشتراطه‬\n ‫‪359‬‬      ‫على املدعى عليه أن يختار جاره وأن ال يبيع‬    ‫شفعة‬     ‫‪31‬‬\n         ‫على أحد إال بإذنه‪ ،‬والعني ليست بيد املدعى‬\n                       ‫عليه حال الدعوى‬\n\n          ‫تأخر مدع يف إثبات شفعته يف شراء مزرعة‬\n ‫‪367‬‬             ‫يدعي شركاته مع بائعها‬                 ‫شفعة‬     ‫‪32‬‬\n\n          ‫مطالبة مدع بحق الشفعة يف أرض مستقلة‬\n ‫‪378‬‬                 ‫مجاورة مللكه‬                      ‫شفعة‬     ‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":378,"source_page_end":386,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"da83bd3b0bd081b181d0ba5b4496c1c50a51589855c69e2a386f412bb30278a7","normalized_text_hash":"0420f5c2df7ad3dca520d85263f3ce96d6fcb9c8de6b29562e3447aa23a1f011","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p378-34232609"},{"id":"400e07db-1cba-5f44-b4fd-85ce0ef7d6dc","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -طلب إعادة وقف إلى مستحقيه -نقل وقف إلى جمعية خيرية إعتقاد ا بانقطاع الوقف -ظهور مستحقني للوقف -رجوع القاضي عن حكمه إذا ثبت لديه عدم انقطاع الوقف -عدم جواز الوقف فيما يخالف الشرع -وزارة املالية صاحبة الوالية يف حفظ أموال الغيب -وزارة الشئون اإلسامية صاحبة الوالية يف حفظ أموال األوقاف العامة.","document_number":"33439487","case_number":"6102","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة ويف يوم الثالثاء املوافق 1429/12/25ه حضر ( )","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"وقف -طلب إعادة وقف إلى مستحقيه -نقل وقف إلى جمعية خيرية إعتقاد ا بانقطاع الوقف -ظهور مستحقني للوقف -رجوع القاضي عن حكمه إذا ثبت لديه عدم انقطاع الوقف -عدم جواز الوقف فيما يخالف الشرع -وزارة املالية صاحبة الوالية يف حفظ أموال الغيب -وزارة الشئون اإلسامية صاحبة الوالية يف حفظ أموال األوقاف العامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1433/10/28 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33439487 :‬‬\n                             ‫َر ْق ُم الدعوى‪6102 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34604528‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n     ‫وقــف ‪ -‬طلــب إعــادة وقــف إلــى مســتحقيه ‪ -‬نقــل وقــف إلــى جمعيــة‬\n     ‫خيريــة إعتقــاد ًا بانقطــاع الوقــف ‪ -‬ظهــور مســتحقني للوقــف ‪ -‬رجــوع‬\n     ‫القاضــي عــن حكمــه إذا ثبــت لديــه عــدم انقطــاع الوقــف ‪ -‬عــدم جــواز‬\n     ‫الوقــف فيمــا يخالــف الشــرع ‪ -‬وزارة املاليــة صاحبــة الواليــة يف حفــظ‬\n     ‫أمــوال الغيــب ‪ -‬وزارة الشــئون اإلســامية صاحبــة الواليــة يف حفــظ‬\n                                                       ‫أمــوال األوقــاف العامــة‪.‬‬\n\n\n\n\n     ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                         ‫حكمه‪.‬‬\n\n\n\n     ‫أقــام رجــل دعــوى أصالــة عــن نفســه وبوكالــة عــن غيــره دعــوى علــى‬\n     ‫اجلمعيــة (‪ ).....‬بصفتهــا اجلهــة القائمــة واملســتفيدة مــن وقــف امــرأة‬\n     ‫بحجــة أن وقــف املــرأة قــد انقطــع مســتحقه وقــد ســلم الوقــف املذكــور‬\n     ‫للجمعيــة (‪ ).....‬مبوجــب صــك صــادر مــن ناظــر القضيــة وطلــب املدعــي‬\n     ‫بإعــادة الوقــف ملســتحقه مــن األقربــن‪ ،‬طلبــت احملكمــة منــه حتديــد‬\n     ‫مــن آل إليهــم االســتحقاق يف الوقــف املذكــور فأبــرز صــك الوقفيــة فــإذا‬\n     ‫فيــه أنــه يــؤول مــن بعــد املوقفــة إلــى بنــت ابنهــا ثــم مــن بعدهــا ينحصــر‬\n\n‫‪5‬‬\n\f‫يف أوالدهــا وذريتهــا حتــى االنقــراض قــد أثبــت املدعــي أن املدعيــن‬\n‫هــم مــن ذريــة بنــت ابــن املوقفــة‪ ،‬نفــى املدعــى عليــه علمــه بالدعــوى‬\n‫وذكــر أنــه ال مانــع لــدى اجلمعيــة مــن إعــادة الوقــف إلــى مســتحقه إذا‬\n‫ثبــت اســتحقاقه‪ ،‬اطلعــت احملكمــة علــى الوصايــا اخلاصــة يف هــذا‬\n‫الوقــف ومــن ألــت إليــه صكــوك حصــر الورثــة وكيــف يقســم الريــع‬\n‫علــى مســتحقه كمــا اطلعــت علــى الصــك الصــادر مــن الناظــر الســابق‬\n‫علــى الوقــف والــذي تنــازل فيــه عــن الوقــف املذكــور لصالــح اجلمعيــة‬\n‫(‪ ).....‬بحيــث تتملكــه اجلمعيــة أو تتصــرف فيــه ملصلحتهــا‪ ،‬حكمــت‬\n‫احملكمــة باســتحقاق املدعيــن لوقــف بنــت ابــن املوقفــة وقــدره ســتة‬\n‫قراريــط وثلثــان مــن القيــراط وتســليم هــذا الوقــف لهــم كمــا رجعــت‬\n‫احملكمــة عمــا حكمــت بــه ســابق ًا مــن تســليم الوقــف جلمعيــة (‪،).....‬‬\n                                   ‫صــدق احلكــم ن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي باحملكمــة العامــة‬\n‫باملدينة ويف يوم الثالثاء املوافق ‪1429/12/25‬هـ حضر (‪ )......‬ســعودي‬\n‫اجلنسية أصالة عن نفسه ووكالة عن (‪ )......‬مبوجب الوكالة الصادرة‬\n‫مــن املدينــة يف ‪1433/2/10‬ه ـ جلــد ‪ 144‬حــال وكالتــه عــن كل مــن‬\n‫جميعهــم بالوكالــة الصــادرة مــن املدينــة يف ‪1423/2/18‬ه جلــد وأدعــى‬\n‫علــى احلاضــر معــه (‪ )......‬ســعودي اجلنســية الوكيــل الشــرعي بصفتــه‬\n‫رئيــس اجلمعيــة (‪ )......‬مبوجــب قــرار وزيــر الشــؤون اإلســامية واألوقــاف‬\n‫والدعــوة واإلرشــاد ‪/‬ق‪/‬م يف ‪1425/5/22‬ه ـ مبوجــب الوكالــة‬\n‫الصــادرة يف ‪1428/10/16‬ه ـ وقــدم املدعــي دعــواه احملــررة والتــي‬\n\n                                                                                 ‫‪6‬‬\n\f    ‫جــاء فيهــا انــه صــدر مــن فضيلتكــم صــك برقــم ‪ 10/1239/59‬يف‬\n    ‫‪1427/8/5‬ه ـ بتحويــل الوقــف العائــد لصالــح اجلمعيــة اخليريــة لتحفيــظ‬\n    ‫القــران الكــرمي مــن الناظــر املتنــازل املدعــو (‪ )......‬وهــو غيــر صحيــح‬\n    ‫لآلتــي‪ -1 :‬أن مــا ذكــره الناظــر (‪ )......‬يف أصــل التنــازل غيــر صحيــح‬\n    ‫مــن كونــه مــن ذريــة املــرأة املوقــف عليهــا وربــط نســبه بهــا علــى أن لديــه‬\n    ‫اليقــن وليــس لديــه بينــه أو صــك شــرعي يثبــت نســبه بهــا وأعطــى نفســه‬\n    ‫حــق التنــازل دون الرجــوع ألصحــاب احلــق املســتفيدين بــل نفــى وجــوب‬\n    ‫أنــه يســتطيع ربــط نســبه باملــرأة املوقــف عليهــا املذكــورة ونحــن نســبنا‬\n    ‫مثبــت بالصــك الصــادر مــن هــذه احملكمــة يف ‪1365/10/26‬هــ‪-2 .‬‬\n    ‫أن نظــارة اجلمعيــة للوقــف مخالفــه لشــرط الواقفــة حيــث أن الواقفــة‬\n    ‫حصــرت النظــر والواليــة علــى الواقــف املذكــور وإجــراء خيراتــه علــى‬\n    ‫نفســها مــدة حياتهــا ومــن بعدهــا للمصونــة (‪ )......‬املذكــورة ثــم مــن بعــد‬\n    ‫(‪ )......‬ينحصــر النظــر ألوالد (‪ )......‬وذريتهــا إلــى االنقــراض ثــم االقــرب‬\n    ‫فاألقــرب مــن اقاربهــا ملــن لهــم نظــر والواليــة لكائن مــن كان اخليار بني‬\n    ‫االســتغالل والســكني مبوجــب شــرط الواقفــة بالصــك عــام ‪1279‬ه ـ‬\n    ‫وعلــى مــا تقــدم نأمــل اعــادة النظــر يف نقــل الوقــف للجمعيــة حيــث أن‬\n    ‫الوقــف املذكــور لــه مســتحقون يصــرف عليهــم حســب شــرط الواقفــة‬\n    ‫حيــث أن صــرف ريعهــا علــى مســتحقيها وهــم مــن االقربــن أولــى وابلــغ‬\n    ‫يف الثــواب للواقفــة وملــا فيــه صلــة رحــم وصدقــه هكــذا قــرر دعــواه‬\n    ‫وبســؤاله حتريــر ًا لدعــواه عمــن آل لهــم االســتحقاق يف هــذا لوقــف قــال‬\n    ‫أن صــك الوقفيــة نــص علــى أنــه يــؤول مــن بعد املوقفة إلــى املصونة (‪)......‬‬\n    ‫ثــم مــن بعــد (‪ )......‬ينحصــر يف أوالد (‪ )......‬وذريتهــا حتــى االنقــراض وقــد‬\n    ‫توفيــت (‪ )......‬عــن عاصبهــا (‪ )......‬وأن تــويف عــن أختــه (‪ )......‬وأن (‪)......‬‬\n\n\n‫‪7‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":5,"source_page_end":7,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"150560ea1acf9697db9957d05bc625925e79cf84828b9fff7b4c3c375d07ddd1","normalized_text_hash":"31640c37be53763ee55b97d37f34fd3bf0732accdda43151753010cb2a9f21db","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p5-33439487"},{"id":"c614da37-156a-5762-bdc8-7d4187783ffb","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -كيفية توزيع غلة الوقف -اضطراب النظار يف كيفية توزيع نصيب من توفى عقيم ا وال ولد له -تدخل أحد املستحقني يف الدعوى لتضرره من إعادة التقسيم -عدم وجود نص يحدد كيفية إعادة تقسيم من ال ولد له -نصيب العقيم يعود إلى أصل الغلة عند عدم النص.","document_number":"3418295","case_number":"32175869","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"وقف -كيفية توزيع غلة الوقف -اضطراب النظار يف كيفية توزيع نصيب من توفى عقيم ا وال ولد له -تدخل أحد املستحقني يف الدعوى لتضرره من إعادة التقسيم -عدم وجود نص يحدد كيفية إعادة تقسيم من ال ولد له -نصيب العقيم يعود إلى أصل الغلة عند عدم النص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418295 :‬‬\n                   ‫َر ْق ُم الدعوى‪32175869 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34216589‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫وقــف ‪ -‬كيفيــة توزيــع غلــة الوقــف ‪ -‬اضطــراب النظــار يف كيفيــة‬\n‫توزيــع نصيــب مــن توفــى عقيمـ ًا وال ولــد لــه ‪ -‬تدخــل أحــد املســتحقني‬\n‫يف الدعــوى لتضــرره مــن إعــادة التقســيم ‪ -‬عــدم وجــود نــص يحــدد‬\n‫كيفيــة إعــادة تقســيم مــن ال ولــد لــه ‪ -‬نصيــب العقيــم يعــود إلــى أصــل‬\n                                                    ‫الغلــة عنــد عــدم النــص‪.‬‬\n\n\n\n\n‫‪ .1‬قــال يف تنقيــح احلامديــة املنصــوص عليــه يف اإلســعاف وغيــره « أنــه‬\n‫إذا ســكت عــن مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف الغلــة أي‬\n                  ‫ينقســم علــى جميــع املســتحقني أ‪.‬هــ‪ ».‬تنقيــح احلامديــة‪.‬‬\n‫‪ .2‬قــال يف اإلســعاف (ولــو قــال كلمــا حــدث املــوت علــى أحــد منهــم‬\n‫ا كان نصيبــه منهــا راجعـ ًا البطــن الــذي فوقــه‬   ‫ولــم يتــرك ولــد ًا أونسـ ً‬\n‫ومــات واحــد منهــم ولــم يكــن فوقــه أحــد أو لــم يذكــر يف ســهم مــن‬\n‫ميــوت عــن غيــر ولــد وال نســل شــيئ ًا فيكــون نصيبــه راجع ـ ًا إلــى أصــل‬\n                          ‫الغلــة وجاري ـ ًا مجراهــا)‪ .‬اإلســعاف الطرابلســي‪.‬‬\n\n\n\n\n‫أقــام رجــل دعــوى علــى ناظــر وقــف يطالبــه بإعطائــه جــزء مــن نصيــب‬\n‫احــد املســتحقني مــن الطبقــة األولــى لوفاتــه‪ ،‬صــادق املدعــى عليــه علــى‬\n\n                                                                                      ‫‪30‬‬\n\f     ‫الدعــوى ورفــض طلــب املدعــى ألن النظــار الســابقني كانــوا علــى نفــس‬\n     ‫الطريقــة فمــن مــات مــن املســتحقني مــن الطبقــة األولــى رجــع نصيبــه إلى‬\n     ‫ورثتــه ولــم يتطرقــوا إلــى مــن ال وارث لــه كالعقيــم الــذي يطالــب املدعــي‬\n     ‫بإعطائــه جــزء مــن نصيبــه وذكــر أن هــذا الوقــف علــى ثالثــة فــروع‬\n     ‫واملدعــي مــن أوالد أحــد الفــروع واملتوفــى هــو أحــد الفــروع وهــي امــرأة‬\n     ‫عقيــم والناظــر الســابق كان يقســم بــن أوالد الظهور والبطون بالســوية‬\n     ‫ومــن مــات بغيــر ولــد رجــع نصيبــه إلخوتــه وأن صــك الوقــف لــم يتطــرق‬\n     ‫للعقمــاء وأن نصيــب املــرأة العقيــم التــي هــي أحــد الفــروع يعطــى ألخيهــا‬\n     ‫الشــقيق واملدعــي يطالــب بإرجاعــه إلــى األصــل فيكــون الوقــف علــى‬\n     ‫فرعــن فقــط ال علــى ثالثــة‪ ،‬ثــم جــرى مداولــة بــن األطــراف يف تقســيم‬\n     ‫الغلــة وأصــر املدعــي أنــه يطالــب بــأن يعــاد نصيــب الفــرع العقيــم ألصــل‬\n     ‫الغلــة ويقســم بينهــم بالســوية وحضــر املشــرف علــى الوقــف بوصفــه أحــد‬\n     ‫املســتحقني للوقــف وطلــب إدخالــه يف الدعــوى وبعــد اطــاع احملكمــة‬\n     ‫علــى صــك الوقــف تبــن عــدم وجــود شــرط للواقــف وأن الغلــة تقســم‬\n     ‫أثالث ـ ًا وأن حصــة كل مســتحق تنتقــل ألوالده بعــد وفاتــه وألن الناظــر‬\n     ‫قــرر أن النظــار الســابقني كانــوا مضطربــن يف حصــة مــن توفــى عقيمـ ًا‬\n     ‫فأحيانــا يقســمونها بــن الورثــة وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن‬\n     ‫الراجــح عنــد العلمــاء أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع‬\n     ‫إليــه عنــد االختــاف فــإن حصــة مــن توفــى مــن غيــر ولــد تعــود إلــى أصــل‬\n     ‫الغلــة وبنــاء عليــه حكمــت احملكمــة بــأن حصــة مــن مــات بغيــر ولــد مــن‬\n     ‫املســتحقني تعــود إلــى أصــل الغلــة ويعــاد قســمتها بــن جميع املســتحقني‪،‬‬\n                                                   ‫صــدق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫‪31‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬مســاعد رئيــس احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم وتاريــخ ‪1432/05/15‬ه املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫‪1432/05/15‬ه ففــي يــوم االحــد املوافــق ‪1433/01/30‬ه ـ أفتتحــت‬\n‫اجللســة الســاعة (‪ )10 : 30‬وفيهــا حضــر (‪ )......‬ســجل مدنــي رقــم (‪)......‬‬\n‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ســجل مدنــي رقــم بصفتــه‬\n‫ناظــرا علــى وقــف مبوجــب صــك النظــارة الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 3/27/168‬يف ‪1429/12/18‬ه ـ قائــا يف تقريــر دعــواه إن‬\n‫املدعــى عليــه الناظــر يقــوم بصــرف مــا كان عائــدا لعمتــي (‪)......‬‬\n‫املتوفــاة عام‪1406‬ه ـ ألوالد أخيهــا (‪ )......‬وحرمنــا نحــن أوالد أخيهــا‬\n‫(‪ )......‬علمــا بــأن الناظــر الســابق كان يقســم مــا كان عائــدا لعمتنــا‬\n‫(‪ )......‬مــن الوقــف بــن ورثــة أخيهــا (‪ )......‬املتوفــى عام‪1400‬ه ـ وأنــا‬\n‫احدهــم وأخيهــا (‪ )......‬والــذي توفــى عام‪1411‬ه ـ علمــا بــأن الطبقــة‬\n‫العليــا قبلنــا قــد انقرضــت بوفــاة (‪ )......‬املتوفــاة عام‪1429‬ه ـ وانتقــل‬\n‫االســتحقاق للطبقــة التــي تليهــا وهــي طبقتنــا ل ـ ــذا اطلــب إلــزام املدعــى‬\n‫عليــه بقس ــمة االســتحقاق بالتســاوي بيننــا نحــن أوالد (‪ )......‬و(‪)......‬‬\n‫ولــدي (‪ )......‬النقــراض الطبقــة العليــا وانتقــال االســتحقاق للطبقــة التــي‬\n‫تليهــا هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه قــال إن الوقــف‬\n‫مــكان نظارتــي مقســم علــى ثالثــة فــروع فــرع (‪ )......‬ولــه الثلــث وفــرع‬\n‫(‪ )......‬ولــه الثلــث وفــرع (‪ )......‬الثلــث واملدعــي فرعــه (‪ )......‬وملــا اســتلمت‬\n‫الوقــف ودفاتــره وجــدت الناظــر الســابق كان يقســم بــن أوالد الظهــور‬\n\n                                                                                           ‫‪32‬‬\n\f     ‫وأوالد البطــون بالســوية ومــن مــات عــن وغيــر ولــد رجــع نصيبــه ألخوتــه‬\n     ‫وبعــد االطــاع علــى الصــك رقــم ‪ 569‬يف‪1378/4/15‬ه ـ الصــادر مــن‬\n     ‫هــذه احملكمــة اتضــح أن العمــل يف الوقــف جــار علــى انتقــال نصيــب‬\n     ‫كل مســتحق ألوالده ولــم يتطــرق للعقمــاء وأنــا اصــرف نصيــب (‪)......‬‬\n     ‫ألوالد (‪ )......‬دون أوالد (‪ )......‬حســب عمــل الناظــر الســابق يف إعــادة‬\n     ‫نصيــب العقيــم ألخيــه يف فــرع (‪ )......‬فقمــت بإعطــاء عائــد (‪ )......‬إلــى‬\n     ‫أوالد أخيهــا (‪ )......‬توحيــدا لإلجــراء علمــا بــأن الناظــر الســابق كان‬\n     ‫يعطــي عائــد (‪ )......‬ألوالد (‪ )......‬و(‪ )......‬بالســوية بينهــم علمــا بأنــه ال‬\n     ‫يوجــد شــرط واقــف وإمنــا جريــان عمــل هـ ــكذا أجــاب وقــد جــرى‬\n     ‫االطــاع علــى الصــك رقــم ‪ 569/568‬يف ‪1378/4/15‬ه ـ الصــادر مــن‬\n     ‫هــذه احملكمــة فوجــد يتضمــن اإلنهــاء بــان العــزل اخلمســة الكائنــة‬\n     ‫بــ(‪ )......‬احملــروس كانــت منحصــرة يف املرحــوم الشــيخ (‪ )......‬ومــن‬\n     ‫بعــده يف أوالده إلــى أن انحصــر يف ثــاث مــن ذريتــه وهــم (‪ )......‬ويف‬\n     ‫(‪ )......‬املذكــور ويف (‪ )......‬وان كان العمــل جــاري علــى قســمة هــذا‬\n     ‫الوقــف بــن مســتحقني يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى‬\n     ‫أوالده وقــد عمــل بهــذا العمــل جملــة من نظار هــذا الوقف وهم (‪)00000‬‬\n     ‫و(‪ )......‬و(‪ )......‬وقــد انحصــر الوقــف املذكــور واآلن يف املكرمــن‬\n     ‫الشــيخ (‪ )......‬واملصونــة (‪ )......‬املذكــور و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬أوالد املرحــوم (‪ )......‬ويف الشــيخ (‪ )......‬و(‪ )......‬و(‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬أوالد املرحــوم (‪ )......‬و(‪ )......‬املذكــورة و(‪ )......‬و(‪)......‬‬\n     ‫ابنــي املرحــوم (‪ )......‬فانتقــل نصيــب كل مــن (‪ )......‬و(‪ )00000‬ولــدي‬\n     ‫(‪ )......‬و(‪ )......‬ألوالده ‪.‬أ‪.‬ه ـ ويف جلســة أخــرى لــدي أنــا (‪ )......‬القائــم‬\n     ‫بعمــل مكتــب مســاعد رئيــس احملكمــة العامــة (‪ )......‬بنــاء علــى خطاب‬\n\n\n‫‪33‬‬\n\f‫فضيلــة رئيــس احملكمــة برقــم ‪ 33619201‬يف ‪1433/4/3‬ه ـ حضــر‬\n‫املدعــي كمــا حضــر املدعــى عليــه نظــارة وجــرى تــاوة الســابق ضبطــه‬\n‫علــى الطرفــن فصادقــا عليــه فطلبــت مــن املدعــى عليــه صــك النظــارة‬\n‫وجميــع صكــوك الوقــف املوجــودة لديهــم فأبــرز الصــك الصــادر مــن‬\n‫محكمــة مكــة برقــم ‪ 569/568‬يف ‪1330/4/15‬ه ـ وباالطــاع عليــه‬\n‫وجــد انــه يتضمــن اإلنهــاء بــان العــزل اخلمســة الكائنــة بالطائــف‬\n‫احملــروس كانــت منحصــرة يف املرحــوم الشــيخ (‪ )......‬ومــن بعــده يف‬\n‫أوالده إلــى أن انحصــر يف ثــاث مــن ذريتــه وهــم (‪ )......‬ويف (‪ )......‬ويف‬\n‫(‪ )......‬وان كان العمــل جــاري علــى قســمة هــذا الوقــف بــن مســتحقني‬\n‫يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا‬\n‫العمــل جملــة مــن نظــار هــذا الوقــف وهــم (‪ )......‬و(‪ )......‬و(‪ )......‬وقــد‬\n‫انحصــر الوقــف املذكــور واآلن يف املكرمــن الشــيخ (‪ )......‬واملصونــة‬\n‫(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد املرحــوم‬\n‫(‪ )......‬ويف الشــيخ (‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬أوالد املرحــوم (‪ )......‬و‬\n‫(‪ )......‬املذكــورة و(‪ )......‬و (‪ )......‬ابنــي املرحــوم (‪ )......‬فانتقــل نصيــب‬\n‫كل مــن (‪ )......‬و(‪ )......‬ولــدي (‪ )......‬و(‪ )......‬ألوالده ‪ .‬ثــم أقــام فضيلــة‬\n‫حاكمــه (‪ )......‬ناظــر علــى هــذا الوقــف إ‪-‬ه ـ كمــا ابرز الصــك الصادر‬\n‫مبحكمــة الطائــف برقــم ‪ 59/2‬يف ‪1377/3/5‬ه ـ وباالطــاع عليــه‬\n‫وجــدت فضيلــة حاكمــه قــد أشــار إلــى عمــل النظــار املــدون يف الصــك‬\n‫املشــار إليــه بعاليــة رقــم ‪ 569‬يف ‪1330/4/15‬ه ـ ثــم أقــام (‪ )......‬ناظــرا‬\n‫علــى هــذا الوقــف و(‪ )......‬مشــرفا عليــه أ‪.‬ه ـ كمــا أبــرز الصــك الصــادر‬\n‫مــن احملكمــة العامــة بــ(‪ 3/27/168 )......‬يف ‪1429/12/18‬ه ـ‬\n‫وباالطــاع عليــه وجــدت أن فضيلــة حاكمــه اطلــع علــى الصــك املشــار‬\n\n\n                                                                                          ‫‪34‬‬\n\f     ‫إليــه بعاليــة رقــم ‪ 59‬يف ‪1377/3/5‬ه واملشــار فيــه إلــى عمــل النظــار‬\n     ‫املــدون بالصــك رقــم ‪ 569‬يف‪1330/4/15‬ه ـ ثــم أقــام (‪ )......‬ناظــرا عــن‬\n     ‫هــذا الوقــف (‪ )......‬مشــرفا عليــه أ‪.‬ه ـ فجــرى ســؤال الناظــر هــل يوجــد‬\n     ‫صكــوك أخــرى للوقــف أو دعــاوى مــن املســتحقني ســابقه فيــه فقــال ال‬\n     ‫يوجــد ســوى هــذه الصكــوك وال يوجــد دعــاوى مــن املســتحقني ســابقه‬\n     ‫هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــال صحيــح مــا ذكــره املدعــى‬\n     ‫عليــه نظــار فــا يوجــد ســوى هــذه الصكــوك كمــا جرى ســؤال املدعى‬\n     ‫عليــه نظــارة عــن عمــل النظــار الســابقني بخصــوص مــن كان عقيمــا‬\n     ‫مــن املســتحقني فقــال فيــه تفصيــل وأبــرز ورقــة نصها (جوابنــا بخصوص‬\n     ‫النظــر يف عمــل النظــار الســابقني لطريقــة تقســيم حصــة العقيــم يف‬\n     ‫وقــف (‪ )......‬ب ــالـ(‪ )......‬أو ًال ‪ .‬قــد تولــت نظــارة هــذا الوقــف (‪ )......‬يف‬\n     ‫‪1330/4/15‬ه ـ إلــى حــن وفاتهــا عــام ‪1356‬ه ـ ولــم نعلــم شــيء مــن‬\n     ‫دفاتــره او ًال طريقــة تقســيم (‪ )......‬يف زمانهــا عبــر ســؤال كبــار‬\n     ‫املســتحقني يف هــذا الوقــف ثاني ـ ًا ‪ :‬أهمــل الوقــف مــن بعــد وفاتهــا وقــد‬\n     ‫اســتولى بعــض املســتأجرين علــى هــذا الوقــف إلــى أن قــام (‪ )......‬و (‪)......‬‬\n     ‫بإعــادة هــذا الوقــف وإجرائــه يف مجــراه حســب صــك هــذه الوقفيــة‬\n     ‫وبالرجــوع إلــى بعــض الدفاتــر املتفرقــة التــي ســألنا عنهــا أخيــرا عنــد‬\n     ‫أبنــاء الناظــر الســابق فوجدنــا طريقــة تقســيم هــذا الوقــف كالتالــي ‪.‬‬\n     ‫تقســم الغلــة إلــى ثالثــة أثــاث الثلــث األول ألبنــاء (‪ )......‬وهــم (‪)......‬‬\n     ‫و(‪ )......‬و(‪ )......‬فمــات (‪ )......‬عقيــم فأعطــى حصتــه ألخيــه (‪ )......‬ورقيــة‬\n     ‫وتسلســل يف العطــاء ألبنائهمــا بإعطــاء كل مــن مــات عــن ولــد فلولــده‪.‬‬\n     ‫ثــم جمــع نصيــب العقمــاء التســعة ووزع مبالغهــم علــى نصفــن نصــف‬\n     ‫منهــا لــ(‪ )0000‬مــن طــرف (‪ )0000‬والنصــف اآلخــر ألبنــاء (‪ )0000‬وهــم‬\n\n\n‫‪35‬‬\n\f‫(‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬و(‪ .)......‬علمـ ًا بــأن العقمــاء التســعة ســبعة‬\n‫منهــم مــن طــرف (‪ )......‬واثنــان مــن طــرف (‪ )......‬ومــع ذلــك كلــه قــام‬\n‫بجمــع التســعة العقمــاء وقســمتها علــى نصفــن ويف هــذا نظــر‪ .‬والثلــث‬\n‫الثانــي ألبنــاء (‪ )......‬وهــم (‪ )......‬و (‪ )......‬و (‪ )......‬فماتــت (‪ )......‬عــن‬\n‫(‪ )......‬وماتــت (‪ )......‬وأعطــت حصتهــا إلــى بنــت خالهــا (‪ )......‬والــى‬\n‫خالتهــا (‪ )......‬وذلــك باعتبــار إرجــاع حصتهــا ألصــل هــذا الفــرع وبعــد أن‬\n‫أخــذ يف توزيــع املبلــغ علــى مســتحقيها األحيــاء منهــم واألمــوات بــان‬\n‫يعطــي كل مــن مــات عــن ولــد لولــده جمــع نصيــب العقمــاء الســبعة وقــام‬\n‫بتوزيعهــا علــى اخلمســة األحيــاء بالســوية بينهــم‪ .‬وهــذا خــاف مــا قــام بــه‬\n‫يف فــرع (‪ )......‬أعــاه حيــث أعطــى نصــف مــال جميــع العقمــاء (‪ )......‬مــن‬\n‫طــرف (‪ )......‬والنصــف اآلخــر للخمســة األحيــاء مــن ورقــة (‪ . )......‬ويف‬\n‫هــذا نظــر أيضــا ألن املتوفــن عقمــاء يف طــرف (‪ )......‬ســتة عقمــاء بينمــا‬\n‫يف طــرف (‪ )......‬عقيمــة واحــدة فكيــف تكــون هنــا املســاواة‪ .‬والثلــث‬\n‫الثالــث ألبنــاء (‪ )......‬وهــم (‪ )......‬و(‪ )......‬و(‪ )......‬فماتــت (‪ )......‬وأعطــى‬\n‫نصيبهــا ألخويهــا الشــقيقني ووزع املبالــغ علــى كل املســتحقني األحيــاء‬\n‫منهــم واألمــوات ثــم جمــع نصيــب العقمــاء الثالثــة أثنــن منهــم مــن طــرف‬\n‫(‪ )......‬وواحــدة مــن طــرف (‪ )......‬وقــام بتوزيــع مبالــغ الثالثــة العقمــاء‬\n‫ووزعهــا علــى نصفــن النصــف األول لورثــة (‪ )......‬مــن فــرع (‪)......‬‬\n‫والنصــف الثانــي لورثــة (‪ )......‬و(‪ )......‬مــن فــرع (‪ )......‬ثــم قــام بتوزيــع‬\n‫حصــة (‪ )......‬العقيــم مــن فــرع (‪ )......‬لورثــة (‪ )......‬ولورثــة (‪ )......‬األحيــاء‬\n‫منهــم دون ترتيــب يف ذلــك وتوالــت االضطرابــات كمــا هــو موجــود‬\n‫لديكــم يف صــورة الدفتــر لعــام ‪1415‬ه ـ ) أ‪ .‬ه ـ وبعــرض الورقــة علــى‬\n‫املدعــي رده بورقــة هــذا نصهــا ( بعــد االطــاع علــى جميــع مــا قدمــه‬\n\n\n                                                                                             ‫‪36‬‬\n\f     ‫الناظــر علــى الوقــف (‪ )......‬أفيدكــم مبــا يلــي ‪ /1‬حســب مــا يدعيــه مــن‬\n     ‫وجــود اضطرابــات يف عمــل الناظــر الســابق (لــم يتــم العمــل علــى تعديلهــا‬\n     ‫وال زال العمــل بهــا مســتمر إلــى اآلن ) ‪ /2‬حســب إفادتــه الســابقة (أنــه‬\n     ‫مــن دفتــر الناظــر الســابق مــن لــم يكــن لــه إخــوة فيرجــع نصيبــه إلــى‬\n     ‫ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم) لــم يتــم العمــل بذلــك بــل ومت‬\n     ‫حرماننــا‪ / 3 .‬إقــرار املشــرف بأنــه املتســبب يف خطــأ التقســيم بحرمــان‬\n     ‫ورثــة املرحــوم (‪ )......‬مــن نصيــب املرحومــة (‪ )......‬وانتقالــه إلــى ورثــة‬\n     ‫(‪ )......‬ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل النظــار ومتاشــي ًا مــع‬\n     ‫العــرف املتبــع علــى أن (مــن مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي‬\n     ‫طبقتــه أو ألصــل الغلــة) وذلــك لعمــوم الفائــدة علــى بقيــة املســتحقني‬\n     ‫اآلخريــن فانــي أهيــب بفضيلتكــم املوقــرة إلــزام الناظــر احلالــي إعــادة‬\n     ‫تقســيم مــا يخــص عائلــة (‪ )......‬بالتســاوي بينهــم نظــرا لوفــاة جميــع‬\n     ‫أصحــاب الطبقــة الســابقة بوفــاة آخــر املســتحقني فيهــا وهــي (‪ )......‬يف‬\n     ‫عــام ‪1429‬ه ـ ونشــوء طبقــة جديــدة وهــم أبنــاء (‪ )......‬و (‪ ))......‬إ‪ -‬ه ـ‬\n     ‫وبعــرض هــذه الورقــة علــى املدعــى عليــه نظــارة ابــرز رده بورقــه هــذا‬\n     ‫نصهــا (أجيــب فضيلتكــم علــى دعــوى املدعــي (‪ )......‬واملقيــدة لديكــم‬\n     ‫برقــم (‪ )......‬وتاريــخ ‪1432/5/15‬ه ـ علــى مــا قدمه يف جلســة يوم االثنني‬\n     ‫‪1433/6/23‬ه يف مــا يلــي ‪ :‬أو ًال بخصــوص طلبــه إعــادة تقســيم ما يخص‬\n     ‫عائلــة (‪ )......‬فــرع (‪ )......‬يف هــذا الوقــف بقســمته بــن ابنــي (‪ )......‬و‬\n     ‫(‪ )......‬بالتســاوي بينهــم حســب مــا ميثلونــه مــن طبقــة جديــدة مــن‬\n     ‫املســتحقني‪ .‬أفيــد فضيلتكــم بــأن هــذا الوقــف غيــر طبقــي فــا نقــض‬\n     ‫للقســمة هنــا لعــدم النقــض يف شــرط الوقــف ولعــدم النقــض يف عمــل‬\n     ‫النظــار الســابقني وإمنــا كان تقســيم غلــة هــذا الوقــف علــى النحــو‬\n\n\n‫‪37‬‬\n\f‫التالــي‪( -:‬أ)‪ :‬حســب صــك الوقــف رقــم (‪ )569‬فى‪1330/4/15‬ه ـ‬\n‫الصــادر مــن محكمــة مكــة املكرمــة والــذي جــاء فيــه (أن الوقــف‬\n‫منحصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده إلــى أنــا نحصــر إلــى ثــاث‬\n‫مــن ذريتــه وهــم ‪ )......( :‬ويف (‪ )......‬ويف ســلم(‪ )......‬وأنــه كان العمــل‬\n‫جــارى علــى قســمة هــذا الوقــف بــن مســتحقيه يف كل زمــان بانتقــال‬\n‫نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا الصــك جملــة مــن‬\n‫نظــار هــذا الوقــف)‪(.‬ب)‪ :‬أن يســتمر يف تقســيم الغلــة إلــى ثالثــة أثــاث‬\n‫الثلــث األول مــن الغلــة لورثــة (‪ )......‬والثلــث الثانــي لورثــة (‪ )......‬والثلــث‬\n‫الثالــث لورثــة (‪( .)......‬ج)‪ :‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور‬\n‫وأوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق (وأن مــن مــات‬\n‫عــن غيــر ولــد فنصيبــه إلخوتــه حســب مــا جــاء يف صفحتــي ‪ 10‬و ‪ 11‬مــن‬\n‫دفتــر الناظــر الســابق لفــرع (‪ )......‬وبعــد مشــاورتي للمشــرف علــى تطبيق‬\n‫هــذا التقســيم لفــرع (‪ )......‬وفــرع (‪ )......‬بــدال مــن االضطرابــات التــي‬\n‫وقــع فيهــا الناظــر الســابق (‪ )......‬يرحمــه اهلل ‪ -‬ولتطابــق هــذا يف كثيــر‬\n‫مــن شــروط الواقفــن أيدنــى علــى ذلــك وعــدم إغفالنــا ملــن لــم يكــن لــه‬\n‫إخــوة فيرجــع نصيبــه إلــى ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا‬\n‫جــاء يف الدفتــر ص‪ ) 8‬وحيــث أن املســتحقني لفــرع (‪ )......‬انحصــر يف‬\n‫أوالد (‪ )......‬وعددهم تســعة أشــخاص ويف أوالد (‪ )......‬وعددهم خمســة‬\n‫أشــخاص‪ ،‬وأن وفــاة (‪ )......‬كان قبــل وفــاة أختــه (‪ )......‬وقــد انتقــل‬\n‫نصيبهــا إلــى أخيهــا (‪ )......‬ممــا زاد يف حصــص املســتحقني مــن أوالد‬\n‫(‪ )......‬وأن عددهــم أقــل مــن عــدد أوالد (‪ )......‬ممــا جعــل نصيــب املدعــي‬\n        ‫أقل من نصيب أوالد عمه (‪ )......‬هذا ما دفع املدعى إلقامة دعواه‬\n‫ثانيـاً‪ :‬علــى املدعــى التأمــل يف تطبيــق طريقــة القســمة مــن عدمهــا أعــاه‬\n\n\n                                                                                          ‫‪38‬‬\n\f     ‫ليتأكــد مــن أن هــذه االضطرابــات قــد أزيلــت أم ال ؟ عليــه نرجــوا مــن‬\n     ‫فضيلتكــم التوجيــه مبــا ترونــه حيــال حصــة العقيــم) وبعــرض ذلــك‬\n     ‫علــى املدعــي ابــرز رده بورقــه هــذا نصهــا بعــد االطــاع والتأمــل يف جميــع‬\n     ‫الــردود التــي قدمهــا الناظــر علــى الوقــف أفيدكــم باعتراضــي وعــدم‬\n     ‫قناعتــي الن جميــع أعمالــه يف قســمة عائلــة مــن تلقــاء نفســه دون الرجــوع‬\n     ‫إلــى أي اســتناد وكمــا تعلمــون فضيلتكــم أنــه ال يوجــد شــرط للوقــف‬\n     ‫وهــذا خــاف مــا يدعيــه يف جميــع ردوده ‪ ،‬وحتى بعــد املراجعة والتدقيق‬\n     ‫يف عمــل الناظــر الســابق يف قســمة عائلــة (‪ )......‬لــم يوجــد حرمــان بــل‬\n     ‫وزعــت حصــة العقيــم بالتســاوي واســتمر بالعمــل علــى ذلــك حتــى مــن‬\n     ‫بعــد وفاتــه ‪.‬لذلــك ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل النظــار‬\n     ‫ومتاشــيا مــع العــرف املتبــع يف كثيــر مــن شــروط الواقفــن علــى أن «مــن‬\n     ‫مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي طبقتــه أو ألصــل الغلــة «ولعمــوم‬\n     ‫الفائــدة ولتحيــق العدالــة بيننــا‪ ،‬فإنــي أطلــب مــن فضيلتكــم املوقــرة‬\n     ‫إلــزام الناظــر احلالــي إعــادة تقســيم مــا يخــص عائلــة (‪ )......‬بالتســاوي‬\n     ‫بينهــم نظــرا لوفــاة جميــع أصحــاب الطبقــة الســابقة بوفــاة أخــر‬\n     ‫املســتحقني فيهــا وهــي يف عــام ‪1429‬ه ونشــوء طبقــة جديــدة وهــم أبنــاء‪.‬‬\n     ‫كمــا حضــر (‪ )......‬ســجل مدنــي رقــم (‪ )......‬وهــو املشــرف علــى والناظر‬\n     ‫مبوجب الصك الصادر من احملكمة العامة (‪ )......‬برقم ‪3/27/168‬يف‬\n     ‫‪1429/12/18‬ه كمــا حضــر بالســجل املدنــي رقــم (‪ )......‬بالســجل‬\n     ‫املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم‬\n     ‫(‪ )......‬وقــرروا جميعــا قائلــن أننــا مــن املســتحقني يف هــذا الوقــف ونقــرر‬\n     ‫بــان حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني ســواء كان عقيمــا أو‬\n     ‫لــم يتــزوج فإنهــا تصــرف إلخوانــه مــن املســتحقني هكــذا قــرروا جميعــا‬\n\n\n‫‪39‬‬\n\f‫إ‪.‬ه ـ ثــم قــرر املدعــى عليــه نظــاره أن جميــع املســتحقني مــن الفــروع‬\n‫الثالثــة يقــررون أن حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني تكون‬\n‫إلخوانــه ولكنهــم ال يســتطيعون احلضــور لديكــم واطلــب إمهالــي‬\n‫إلحضــار إقــرارا منهــم بذلــك هكــذا قــرر وبعــرض ذلــك علــى املدعــي‬\n‫قــال أنــي ال أوافــق علــى مــا قــرره الناظــر واحلاضــرون مــن املســتحقني الن‬\n‫حصــة العقيــم والــذي ليــس لــه ذريــة مــن املســتحقني يرجــع ألصــل الثلــث‬\n‫وليــس إلخــوة امليــت هكــذا قــرر ويف جلســة أخــرى حضــر املدعــي (‪)......‬‬\n‫أصالــة كمــا حضــر املدعــى عليــه (‪ )......‬نظــارة كمــا حضــر كل مــن‬\n‫(‪ )......‬الســجل املدني رقم (‪ )......‬و (‪ )......‬بالســجل املدني (‪ )......‬و(‪)......‬‬\n‫وقــرروا جميعــا قائلــن إننــا أوالد ونحــن مــن املســتحقني يف هــذا الوقــف‬\n‫وكان والدنــا وعمنــا (‪ )......‬وعمتنــا (‪ )......‬مســتحقني يف الوقــف‬\n‫ويســتلمون اســتحقاقهم مــن الناظــر الســابق (‪ )......‬يــوزع عليهــم‬\n‫االســتحقاق بالتســاوي بينهــم وملــا توفيــت (‪ )......‬عقيمــا كان يقســم‬\n‫اســتحقاقها علــى أخويهــا (‪ )......‬و(‪ )......‬واســتمر العمــل علــى ذلــك بعــد‬\n‫وفــاة والدنــا وعمنــا ثــم تولــى هــذا الناظــر النظــارة واســتمر علــى هــذا‬\n‫العمــل ملــدة ســنتني وبعــد ذلــك اختلفــت القســمة وأصبــح يعطــى كامــل‬\n‫حصــة عمتنــا (‪ )......‬ألوالد عمنــا (‪ )......‬ويحرمنــا منهــا وملــا اعترضنــا‬\n‫عليــه قــال إن (‪ )......‬توفيــت بعــد والدكــم وحصتهــا تكــون ألخيهــا‬\n‫الــذي تــويف بعدهــا وهــو (‪ )......‬وأمــا مــن تــويف قبلهــا فــا يأخــذ شــيئا‬\n‫وبنــاء علــى ذلــك تقــدم أخونــا ‪ .....‬بهــذه الدعــوى ونحــن نطلــب إعــادة‬\n‫القســمة علــى مــا كانــت عليــه بقســمة حصــة العقيــم علــى أخــوة امليــت‬\n‫بالتســاوي هكــذا قــرروا وبعــرض ذلــك علــى املدعــى عليــه نظــارة‬\n‫فالصحيــح مــا ذكــره املدعــي وإخوانــه احلضــور فقــد كان الناظــر‬\n\n\n                                                                                     ‫‪40‬‬\n\f     ‫الســابق مضطــرب يف العمــل يف هــذا الفــرع وهــو فــرع (‪ )......‬كان‬\n     ‫يصــرف حصــة العقيــم إلــى أصــل الثلــث ويوزع بالتســاوي بني املســتحقني‬\n     ‫بينمــا يف الفرعــن اآلخريــن وهمــا فــرع (‪ )......‬وفــرع (‪ )......‬حيــث كان‬\n     ‫يجعــل حصــة العقيــم إلخوانــه فقــط دون بقيــة املســتحقني يف الفــرع هــذا‬\n     ‫إذا كان للعقيــم إخــوة وإذا لــم يكــن لــه إخــوة أعــاد حصــة العقيم ألصل‬\n     ‫الثلــث وقســمه بالتســاوي بــن املســتحقني وملــا توليــت النظــارة اســتمريت‬\n     ‫علــى هــذا العمــل ملــدة ســنة واحدة فقط وقمت بعمل شــباكا الســتحقاق‬\n     ‫مــن واقــع الدفاتــر لــكل فــرع وظهــر لــي االضطــراب وجعلــت عمــل‬\n     ‫الناظــر الســابق يف فرعــي (‪ )......‬و(‪ )......‬هــو األصــل وعملــت بــه يف فــرع‬\n     ‫(‪ )......‬الــذي ينتمــي إليــه املدعــي وإخوانــه وبنــاء عليــه وملــا كان والــد‬\n     ‫املدعــن قــد تــويف قبــل أختــه (‪ )......‬العقيمــة فإنــه ال يســتحق شــيئا مــن‬\n     ‫اســتحقاقها وإمنــا يكــون اســتحقاقها ألخيهــا (‪ )......‬الــذي توفيــت وهــو‬\n     ‫حــي ولــذا فــإن اســتحقاقها أصبــح ألوالد (‪ )......‬وحدهم دون أوالد (‪)......‬‬\n     ‫هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــي واخوانــه قالــوا إننــا نطلــب‬\n     ‫أعــادة قســمة حصــة العقيــم (‪ )......‬علــى إخوانهــا فمــن كان حيــا اخــذ‬\n     ‫حصتــه ومــن كان ميتــا أعطيــت حصتــه ألوالده هكــذا قــرروا ثــم ابــرز‬\n     ‫املدعــى عليــه نظــارة أوراق إقــرارات مــن املســتحقني يف الوقــف وهــذا‬\n     ‫نصهــا (نقــر نحــن املســتحقني لوقــف (‪ )......‬بالطائــف فــرع (‪ )......‬وفــرع‬\n     ‫(‪ )......‬بــأن يكــون تقسيـ ــم غلــة الوقــف علــى النحــو التالــي‪ -:‬أ‪ -‬حســب‬\n     ‫صــك الوقــف رقــم ‪569‬يف‪1330/4/15‬ه الصــادر مــن محكمــة (‪)......‬‬\n     ‫والــذي جــاء فيــه أن الوقــف منحصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده‬\n     ‫إلــى أن انحصــر إلــى ثــاث مــن ذريتــه وهــم (‪ )......‬ويف (‪ )......‬ويف (‪)......‬‬\n     ‫وانــه كان جــاري علــى قســمة هــذا الوقــف بــن مســتحقيه يف كل زمــان‬\n\n\n‫‪41‬‬\n\f‫بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا الصــك جملــة‬\n‫مــن نظــار هــذا الوقــف ب‪ -‬أن يســتمر يف تقســيم الغلــة إلــى ثــاث أثــاث‬\n‫الثلــث األول مــن الغلــة لورثــة (‪ )......‬والثلــث الثانــي لورثــة (‪ )......‬والثلــث‬\n‫لورثــة (‪ . )......‬ت‪ -‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور وأوالد‬\n‫البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق وان مــن مــات مــن غيــر‬\n‫ولــد فنصيبــه ألخواتــه حســب مــا جــاء يف صفحتــي (‪10‬و‪ )11‬مــن دفتــر‬\n‫الناظــر الســابق لفــرع (‪ )......‬ومــن لــم يكــن لــه إخــوة فيرجــع نصيبــه إلــى‬\n‫ثلــث ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا جــاء يف الدفتــر ص‪8‬‬\n‫‪.‬املســتحقني املوقعــن هــم (‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و‬\n‫(‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و‬\n‫(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و(‪ )......‬و (‪ )......‬و‬\n‫(‪)......‬و (‪ )......‬و (‪ )......‬أوالد (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬أوالد (‪)......‬‬\n‫و (‪ )......‬و (‪ )......‬بنتــي (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و(‪ )......‬أوالد (‪.)......‬‬\n‫و(‪ )......‬و(‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬و (‪ )......‬ابنــي (‪ )......‬و‬\n‫(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و (‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد (‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و (‪ )......‬أوالد (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬أوالد و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد و(‪)......‬‬\n‫و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و و(‪)......‬‬\n‫أوالد (‪ ) )......‬أ‪.‬ه ـ وبعــرض هــذه اإلقــرارات علــى املدعــي قــال اطلــب‬\n‫تزويــدي بصــورة منهــا وإمهالــي لالطــاع عليهــا وجــرى تســليم املدعــي‬\n\n\n                                                                                                ‫‪42‬‬\n\f     ‫صــورة منهــا ثــم قــرر احلاضــر (‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬و(‪ )......‬أوالد‬\n     ‫(‪ )......‬بأننــا نــوكل أخانــا املدعــي يف مواصلــة هــذه الدعــوى وحضــور‬\n     ‫جميــع اجللســات واملرافعــة واملدافعــة وتقــدمي البينــات والــرد عليهــا‬\n     ‫والقناعــة واالعتــراض وتقــدمي الالئحــة االعتراضيــة حتــى اكتســاب‬\n     ‫احلكــم القطعيــة هكــذا قــرروا وقــرر احلاضــر ‪ .....‬موافقتــه علــى ذلــك‪.‬‬\n     ‫ويف جلســة أخــرى حضــر املدعــي أصالــة ووكالــة كمــا حضــر املدعــى‬\n     ‫عليــه نظــارة حــال حضــور (‪ )......‬وقــرر رفقــي أن الناظــر الســابق كان‬\n     ‫مضطربــا يف تقســيم حصــة العقيــم أو الــذي توفــى عــن غيــر ولــد فأحيانا‬\n     ‫يعيدهــا إلــى أصــل الغلــة كمــا فعــل يف (‪ )000‬ومــن قبلهــا مــن العقمــاء‬\n     ‫حيــث كان يجمــع حصــة العقمــاء ويعيــد قســمتها علــى املســتحقني‬\n     ‫بالتســاوي وحينمــا توفيــت (‪ )......‬لــم يفعــل ذلــك وإمنــا أعطــى اســتحقاقها‬\n     ‫ألختهــا الشــقيقة (‪ )......‬ولــم يعــط بقيــة املســتحقني شــيئا هكــذا قــرر‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــي واملدعــى عليــه قــاال صحيــح مــا ذكــره‬\n     ‫احلاضــر (‪ )0......‬فالناظــر الســابق كان مضطربــا يف قســمة حصــة‬\n     ‫العقيــم ومــن لــم يخلــف أوالد ًا هكــذا قــررا‪ .‬وبســؤال الطرفــن هــل‬\n     ‫لديهــم مــا يضيفانــه يف هــذه القضيــة فقــاال ليــس لدينــا ســوى مــا قدمنــاه‬\n     ‫‪.‬هكــذا قــاال ويف جلســة أخــرى حضــر املدعــي كمــا حضــر املدعــي‬\n     ‫عليــه نظــارة وبســؤال الطرفــن هــل لديهمــا مــا يضيفانه يف هــذه القضية‬\n     ‫فقــال املدعــي أننــي ســبق أن ذكــرت يف دعــواي إننــي اطلــب إعــادة‬\n     ‫قســمة الغلــة بــن املســتحقني بالتســاوي وتبــن لــي أن عمــل النظــارة‬\n     ‫الســابقني هــو إعطــاء حصــة كل مســتحق ألوالده ولــذا فــا مطالبــة لــي‬\n     ‫فيمــا يخــص ذلــك وإمنــا مطالبتــي هــي فيمــا يخــص حصــة العقيــم بــأن ال‬\n     ‫تصــرف ألحــد دون أحــد مــن املســتحقني وإمنــا تعــود ألصــل الغلــة هكــذا‬\n\n\n‫‪43‬‬\n\f‫قــرر وبعــرض ذلــك علــى املدعــي عليــه نظــارة قــال ليــس لــدي ســوى مــا‬\n‫قدمتــه بــأن حصــة العقيــم قــد اضطــرب فيهــا النظــار الســابقون ففــي‬\n‫ثلثــن تعطــى حصــة العقيــم ومــن توفــى عــن غيــر ولــد إلخوانــه ويف الثلــث‬\n‫الــذي ينتمــي إليــه املدعــي فــإن الناظــر الســابق كان يعطــي حصــة‬\n‫العقيــم ومــن مــات عــن غيــر ولــد إلخوانــه ثــم بعــد ذلــك إعــادة إلــى أصــل‬\n‫الغلــة ثــم رجــع وأعطــاه إلخــوة املتــويف حســب مــا بينتــه لكــم ســابقا‬\n‫هكــذا قــرر وقــد حضــر املشــرف علــى الناظــر (‪ )......‬ســجل مدنــي رقــم‬\n‫(‪ )0......‬مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪3/27/168‬‬\n‫يف ‪1429/12/18‬ه ـ وقــرر قائــا إننــي اطلــب إدخالــي يف هــذه القضيــة‬\n‫وأنــا أطلــب العمــل بإعطــاء حصــة مــن توفــى عــن غيــر ولد من املســتحقني‬\n‫إلخوتــه يف كل ثلــث ألنــه ال يوجــد شــرط واقــف يف هــذا الوقــف وإمنــا‬\n‫أكثــر عمــل النظــار علــى ذلــك هكــذا قــرر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وبعــد اإلطــاع علــى صكــوك هــذا الوقــف وألنــه‬\n‫تبــن عــدم وجــود شــرط واقــف لــدى نظــار هــذا الوقــف وأن غلــة هــذا‬\n‫الوقــف تقســم أثالث ـ ًا علــى الوصــف املشــار إليــه بعاليــه وأن حصــة كل‬\n‫مســتحق تنتقــل إلــى أوالده وألن الناظــر قــرر أن النظــار الســابقني كانوا‬\n‫مضطربــن يف حصــة مــن تــويف عقيمــا أوعــن غيــر ولــد فأحيانــا كانــوا‬\n‫يقســمونها بــن إخوتــه وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن الراجــح‬\n‫عنــد أهــل العلــم أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع إليــه‬\n‫عنــد االختــاف فــإن حصــة مــن توفــى عــن غيــر ولــد تعــود ألصــل الغلــة‬\n‫قــال يف تنقيــح احلامديــة املنصــوص عليــه عندنــا يف االســعاف وغيــره أنــه‬\n‫إذا ســكت عــن حكــم مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف‬\n‫الغلــة أي ينقســم علــى جميــع املســتحقني أ‪.‬ه ـ ينظــر تنقيــح احلامديــة‬\n\n\n                                                                                       ‫‪44‬‬\n\f     ‫‪ 382/2‬واالســعاف يف أحــكام األوقــاف للطرابلســي صحيفــة ‪106‬‬\n     ‫وقــال يف االســعاف ولــو قــال كلمــا حــدث املــوت علــى احــد منهــم ولــم‬\n     ‫ا كان نصيبــه منهــا راجعــا البطــن الــذي فوقــه ومــات‬  ‫يتــرك ولــدا أو نسـ َ‬\n     ‫واحــد منهــم ولــم يكــن فوقــه احــد أو لــم يذكــر يف ســهم مــن ميــوت عــن‬\n     ‫غيــر ولــد وال نســل شــيئا فيكــون نصيبــه راجعــا إلــى أصــل الغلــة وجاريــا‬\n     ‫مجراهــا أ‪.‬ه ـ لذلــك كلــه حكمــت بــأن حصــة مــن مــات عــن غيــر ولــد‬\n     ‫مــن املســتحقني يف كل ثلــث تعــود إلــى أصــل الثلــث ويعــاد قســمتها بــن‬\n     ‫جميــع املســتحقني وبعــرض ذلــك علــى الطرفــن قــرر املدعــي واملدعــي‬\n     ‫عليــه نظــارة القناعــة وقــرر املشــرف عــدم القناعــة وطلــب رفعــه حملكمة‬\n     ‫االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة ومت إفهامــه بالتعليمــات ‪،‬‬\n     ‫حــرر بتاريــخ ‪1434/1/14‬ه ـ ‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمد وعلى آله وصحبه وسلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافق‪1433/8/27‬ه ـ‬\n     ‫حضــر املدعــي أصالــة كمــا حضــر املدعــى عليــه نظــارة وبســؤال‬\n     ‫املدعــى عليــه نظــارة عــن رده عــن مــا قدمــه املدعــي يف اجللســة املاضيــة‬\n     ‫فأبــرز ورقــه هــذا نصهــا (أجيــب فضيلتكــم علــى دعــوى املدعــي (‪)......‬‬\n     ‫واملقيــدة لديكــم برقــم (‪ )......‬وتاريــخ ‪1432/5/15‬ه ـ علــى مــا قدمــه‬\n     ‫يف جلســة يــوم االثنــن ‪1433/6/23‬ه يف مــا يلــي ‪:‬أوال بخصــوص طلبــه‬\n     ‫إعــادة تقســيم مــا يخــص عائلــة (‪ )......‬فرع (‪ )......‬يف هذا الوقف بقســمته‬\n     ‫بــن ابنــي (‪ )......‬و (‪ )......‬بالتســاوي بينهــم حســب مــا ميثلونــه مــن طبقــة‬\n     ‫جديــدة مــن املســتحقني‪ .‬أفيــد فضيلتكــم بــأن هــذا الوقــف غيــر طبقــي‬\n     ‫فــا نقــض للقســمة هنــا لعــدم النقــض يف شــرط الوقــف ولعــدم النقــض‬\n     ‫يف عمــل النظــار الســابقني وإمنــا كان تقســيم غلــة هــذا الوقــف علــى‬\n\n\n‫‪45‬‬\n\f‫النحــو التالــي ‪( :‬أ)‪ :‬حســب صــك الوقــف رقــم (‪ )569‬فى‪1330/4/15‬ه ـ‬\n‫الصــادر مــن محكمــة مكــة املكرمــة والــذي جــاء فيــه ) أن الوقــف مــن‬\n‫حصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده إلــى أن نحصــر إلــى ثــاث مــن‬\n‫ذريتــه وأنــه كان العمــل جــاري علــى قســمة هــذا الوقــف بــن مســتحقيه‬\n‫يف كل زمــان بانتقــال نصيــب كل مســتحق إلــى أوالده وقــد عمــل بهــذا‬\n‫الصــك جملــة مــن نظــار هــذا الوقــف) ‪( .‬ب)‪ :‬أن يســتمر يف تقســيم الغلــة‬\n‫إلــى ثالثــة أثــاث ‪ :‬الثلــث األول مــن الغلــة لورثــة والثلــث الثانــي لورثــة‬\n‫والثلــث الثالــث لورثــة‪( .‬ج)‪ :‬أن يســتمر التقســيم يف ذلــك ألوالد الظهــور‬\n‫و أوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر الســابق ( وأن مــن مــات‬\n‫عــن غيــر ولــد فنصيبــه إلخوتــه حســب مــا جــاء يف صفحتــي (‪( 10‬و (‪)11‬‬\n‫مــن دفتــر الناظــر الســابق لفــرع (‪ )......‬وبعــد مشــاورتي للمشــرف علــى‬\n‫تطبيــق هــذا التقســيم لفــرع (‪ ).....‬و فــرع (‪ ).....‬بــدال مــن االضطرابــات‬\n‫التــي وقــع فيهــا الناظــر الســابق ‪ -‬يرحمــه اهلل ‪ -‬ولتطابــق هــذا يف كثيــر‬\n‫مــن شــروط الواقفــن أيدنــى علــى ذلــك وعــدم إغفالنــا ملــن لــم يكــن لــه‬\n‫إخــوة فيرجــع نصيبــه إلــى ثلــث الغلــة املنتمــي إليهــا ذلــك العقيــم كمــا‬\n‫جــاء يف الدفتــر (ص ‪ ) 8‬وحيــث أن املســتحقني لفــرع (‪ )......‬انحصــر يف‬\n‫أوالد (‪ )......‬وعددهــم ( تســعة ) أشــخاص ويف أوالد (‪ )......‬وعددهــم‬\n‫(خمســة) أشــخاص ‪ ،‬وأن وفــاة (‪ )......‬كان قبــل وفــاة أختــه (‪ )......‬وقــد‬\n‫انتقــل نصيبهــا إلــى أخيهــا (‪ )......‬ممــا زاد يف حصــص املســتحقني مــن‬\n‫أوالد (‪ )......‬وأن عددهــم أقــل مــن عــدد أوالد (‪ )......‬ممــا جعــل نصيــب‬\n‫املدعــي أقــل مــن نصيــب أوالد عمــه (‪ )......‬هــذا مــا دفــع املدعــى إلقامــة‬\n                                                                         ‫دعــواه ‪.‬‬\n‫ثانيـاً‪ :‬علــى املدعــى التأمــل يف تطبيــق طريقــة القســمة مــن عدمهــا أعــاه‬\n\n\n                                                                                      ‫‪46‬‬\n\f     ‫ليتأكــد مــن أن هــذه االضطرابــات قــد ازيلــت أم ال؟ عليــه نرجــوا مــن‬\n     ‫فضيلتكــم التوجيــه مبــا ترونــه حيــال حصــة العقيــم) وبعــرض ذلــك على‬\n     ‫املدعــي قــال أطلــب إمهالــي لالطــاع علــى مــا قدمــه الناظــر‪ ،‬وطلــب‬\n     ‫الطرفــان موعــد بعــد رمضــان‪ .‬ولــذا رفعــت اجللســة إلــى يــوم الســبت‬\n     ‫املوافق‪1433/10/21‬ه ـ الســاعة العاشــرة صباحــا ‪ .‬وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                     ‫‪1433/8/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1433/10/21‬هـ‬\n     ‫ويف متــام الســاعة احلاديــة عشــر والنصــف حضــر املدعــي كمــا حضــر‬\n     ‫املدعــى عليــه نظــارة وبســؤال املدعــي عمــا اســتمهل ألجلــه يف اجللســة‬\n     ‫املاضيــة فابــرز ورقــة هــذا نصهــا بعــد االطــاع والتأمــل يف جميــع‬\n     ‫الــردود التــي قدمهــا الناظــر علــى الوقــف أفيدكــم باعتراضــي وعــدم‬\n     ‫قناعتــي الن جميــع أعمالــه يف قســمة عائلــة (‪ )......‬مــن تلقــاء نفســه دون‬\n     ‫الرجــوع إلــى أي اســتناد وكمــا تعلمــون فضيلتكــم أنــه ال يوجــد شــرط‬\n     ‫للوقــف وهــذا خــاف مــا يدعيــه يف جميــع ردوده ‪ ،‬وحتــى بعــد املراجعــة‬\n     ‫والتدقيــق فيعمــل الناظــر الســابق يف قســمة عائلــة (‪ )......‬لــم يوجــد‬\n     ‫حرمــان بــل وزعــت حصــة العقيــم بالتســاوي واســتمر بالعمــل علــى ذلــك‬\n     ‫حتــى مــن بعــد وفاتــه‪ .‬لذلــك ونظــرا لعــدم وجــود مرجعيــة توضــح عمــل‬\n     ‫النظــار ومتاشــي ًا مــع العــرف املتبــع يف كثيــر مــن شــروط الواقفــن علــى‬\n     ‫أن» مــن مــات مــن غيــر ولــد فيعــود نصيبــه لــذوي طبقتــه أو ألصــل الغلــة‬\n     ‫«ولعمــوم الفائــدة ولتحيــق العدالــة بيننــا ‪ ،‬فإنــي أطلــب مــن فضيلتكــم‬\n     ‫املوقــرة إلــزام الناظــر احلالــي إعــادة تقســيم مــا يخــص عائلــة (‪)......‬‬\n     ‫بالتســاوي بينهــم نظــرا لوفــاة جميــع أصحــاب الطبقــة الســابقة بوفــاة‬\n\n\n‫‪47‬‬\n\f‫أخــر املســتحقني فيهــا وهــي (‪ )......‬يف عــام ‪1429‬ه ـ ونشــوء طبقــة جديدة‬\n‫وهــم أبنــاء (‪ )......‬و (‪.)......‬كمــا حضــر بالســجل املدنــي رقــم (‪ )......‬وهــو‬\n‫املشــرف علــى والناظــر مبوجــب الصــك الصــادر مــن احملكمــة العامــة‬\n‫(‪ )......‬برقــم ‪3/27/168‬يف ‪1429/12/18‬ه ـ كمــا حضــر بالســجل‬\n‫املدنــي رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و(‪ )......‬بالســجل املدنــي‬\n‫رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬وقــرروا جميعــا قائلــن أننــا مــن‬\n‫املســتحقني يف هــذا الوقــف ونقــرر بــان حصــة مــن مــات عــن غيــر ولــد‬\n‫مــن املســتحقني ســواء كان عقيمــا أو لــم يتــزوج فإنهــا تصــرف إلخوانــه‬\n‫مــن املســتحقني هكــذا قــرروا جميعــا إ‪.‬ه ـ ثــم قــرر املدعــى عليــه نظــاره‬\n‫أن جميــع املســتحقني مــن الفــروع الثالثــة يقــررون أن حصــة مــن مــات‬\n‫عــن غيــر ولــد مــن املســتحقني تكــون إلخوانــه ولكنهــم ال يســتطيعون‬\n‫احلضــور لديكــم واطلــب إمهالــي إلحضــار إقــرارا منهــم بذلــك هكــذا‬\n‫قــرر وبعــرض ذلــك علــى املدعــي قــال أنــي ال أوافــق علــى مــا قــرره الناظــر‬\n‫واحلاضــرون مــن املســتحقني الن حصــة العقيــم والــذي ليــس لــه ذريــة‬\n‫مــن املســتحقني يرجــع ألصــل الثلــث وليــس إلخــوة امليــت هكــذا قــرر‬\n‫وإلحضــار اإلقــرارات التــي ذكرهــا الناظــر وعليــه رفعــت اجللســة إلــى‬\n‫يــوم الســبت املوافــق ‪1433/11/13‬ه ـ الســاعة العاشــرة ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف متــام‬\n                       ‫الســاعة الثانيــة عشــر والنصــف يف ‪1433/10/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافق‪1433/11/13‬ه ـ‬\n‫حضــر املدعــي أصالــة كمــا حضــر املدعــى عليــه نظــارة كمــا حضــر‬\n‫كل مــن (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و (‪ )......‬بالســجل املدنــي‬\n‫رقــم (‪ )......‬بالســجل املدنــي رقــم (‪ )......‬و بالســجل املدنــي رقــم (‪)......‬‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫بالســجل املدنــي رقــم (‪ )......‬وقــرروا جميعــا قائلــن إننــا أوالد ونحــن مــن‬\n     ‫املســتحقني يف هــذا الوقــف وكان والدنــا وعمنــا (‪ )......‬وعمتنــا (‪)......‬‬\n     ‫مســتحقني يف الوقــف ويســتلمون اســتحقاقهم مــن الناظــر الســابق يــوزع‬\n     ‫عليهــم االســتحقاق بالتســاوي بينهــم وملــا توفيــت عقيمــا كان يقســم‬\n     ‫اســتحقاقها علــى أخويهــا واســتمر العمــل علــى ذلــك بعــد وفــاة والدنــا‬\n     ‫وعمنــا ثــم تولــى هــذا الناظــر النظــارة واســتمر علــى هــذا العمــل ملــدة‬\n     ‫ســنتني وبعــد ذلــك اختلفــت القســمة وأصبــح يعطــى كامــل حصــة‬\n     ‫عمتنــا (‪ )......‬ألوالد عمنــا (‪ )......‬ويحرمنــا منهــا وملــا اعترضنــا عليــه قــال‬\n     ‫إن (‪ )......‬توفيــت بعــد والدكــم وحصتهــا تكــون ألخيهــا الــذي تــويف‬\n     ‫بعدهــا وهــو (‪ )......‬وأمــا مــن تــويف قبلهــا فــا يأخــذ شــيئا وبنــاء علــى‬\n     ‫ذلــك تقــدم أخونــا (‪ )......‬بهــذه الدعــوى ونحــن نطلــب إعــادة القســمة‬\n     ‫علــى مــا كانــت عليــه بقســمة حصــة العقيــم علــى أخــوة امليــت بالتســاوي‬\n     ‫هكــذا قــرروا وبعــرض ذلــك علــى املدعــى عليــه نظــارة قــال صحيــح مــا‬\n     ‫ذكــره املدعــي وإخوانــه احلضــور فقــد كان الناظــر الســابق مضطــرب‬\n     ‫يف العمــل ففــي هــذا الفــرع هــو فــرع (‪ )......‬كان يصــرف حصــة العقيــم‬\n     ‫إلــى أصــل الثلــث ويــوزع بالتســاوي بــن املســتحقني بينمــا يف الفرعــن‬\n     ‫اآلخريــن وهمــا فــرع (‪ )......‬وفــرع (‪ )......‬حيــث كان يجعــل حصــة‬\n     ‫العقيــم إلخوانــه فقــط دون بقيــة املســتحقني يف الفــرع هــذا إذا كان‬\n     ‫للعقيــم إخــوة وإذا لــم يكــن لــه إخــوة أعــاد حصــة العقيــم ألصــل الثلــث‬\n     ‫وقســمه بالتســاوي بــن املســتحقني وملــا توليــت النظــارة اســتمريت علــى‬\n     ‫هــذا العمــل ملــدة ســنة واحــدة فقــط وقمــت بعمــل شــباك االســتحقاق‬\n     ‫مــن واقــع الدفاتــر لــكل فــرع وظهــر لــي االضطــراب وجعلــت عمــل‬\n     ‫الناظــر الســابق يف فرعــي (‪ )......‬و (‪ )......‬هــو األصــل وعملــت بــه يف‬\n\n\n‫‪49‬‬\n\f‫فــرع (‪ )......‬الــذي ينتهــي إليــه املدعــي وإخوانــه وبنــاء عليــه وملــا كان‬\n‫والــد املدعــن قــد تــويف قبــل أختــه (‪ )......‬العقيمــة فإنــه ال يســتحق شــيئ ًا‬\n‫مــن اســتحقاقها وامنــا يكــون اســتحقاقها ألخيهــا (‪ )......‬الــذي توفيــت‬\n‫وهــو حــي ولــذا فــأن اســتحقاقها أصبــح ألوالد (‪ )......‬وحدهــم دون أوالد‬\n‫(‪ )......‬هكــذا قــرروا‪ .‬ثــم وبعــرض ذلــك علــى املدعــي واخواتــه قالــوا اننا‬\n‫نطلــب اعــادة قســمة حصــة العقيــم (‪ )......‬علــى اخوانهــا فمــن كان حيــا‬\n‫اخــذ حصتــه ومــن كان ميتــا اعطيــت حصتــه ألوالده هكــذا قــرروا‬\n‫ثــم ابــرز املدعــى عليــه نظــارة أوراق إقــرارات مــن املســتحقني يف الوقــف‬\n‫وهــذا نصهــا ( نقــر نحــن املســتحقني لوقــف (‪ )......‬فــرع و(‪ )......‬وفــرع‬\n‫(‪ )......‬بــأن يكــون تقسيـ ــم غلــة الوقــف علــى النحــو التالــي‪ :‬أ‪ -‬حســب‬\n‫صــك الوقــف رقم‪569‬يف‪1330/4/15‬ه ـ الصــادر مــن محكمــة (‪)......‬‬\n‫والــذي جــاء فيــه ان الوقــف مــن حصــر يف الشــيخ (‪ )......‬ومــن بعــده أوالده‬\n‫إلــى أن انحصــر إلــى ثــاث مــن ذريتــه وهــم وانــه كان جــاري علــى قســمة‬\n‫هــذا الوقــف بــن مســتحقيه يف كل زمــان بانتقــال نصيــب كل مســتحق‬\n‫إلــى أوالده وقــد عمــل بهــذا الصــك جملــة مــن نظــار هــذا الوقــف ب‪ -‬ان‬\n‫يســتمر يف تقســيم الغلــة الــى ثــاث اثــاث الثلــث االول مــن الغلــة لورثــة‬\n‫والثلــث الثانــي لورثــة (‪ )......‬والثلــث لورثــة‪ )......( .‬ان يســتمر التقســيم‬\n‫يف ذلــك ألوالد الظهــور وأوالد البطــون بالســوية بينهــم مــن دفتــر الناظــر‬\n‫الســابق وان مــن مــات مــن غيــر ولــد فنصيبــه ألخواتــه حســب مــا جــاء‬\n‫يف صفحتــي (‪ )10‬و(‪ )11‬مــن دفتــر الناظــر الســابق لفــرع (‪ )......‬ومــن‬\n‫لــم يكــن لــه اخــوة فيرجــع نصيبــه إلــى ثلــث ثلــث الغلــة املنتمــي إليهــا‬\n‫ذلــك العقيــم كمــا جــاء يف الدفتــر ص‪. 8‬املســتحقني املوقعــن هــم اوالد‬\n‫‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬و اوالد ‪ .....‬اوالد ‪ .....‬اوالد‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ .....‬اوالد ‪ ).....‬ا‪ -‬ه ــو بعــرض‬\n     ‫هــذه اإلقــرارات علــى املدعــي قــال اطلــب تزويــدي بصــورة منهــا وامهالــي‬\n     ‫لالطــاع عليهــا وجــرى تســليم املدعــي صــورة منهــا ثــم قرر احلاضــر أوالد‬\n     ‫بأننــا نــوكل اخانــا املدعــي يف مواصلــة هــذه الدعــوى وحضــور جميــع‬\n     ‫اجللســات واملرافعــة واملدافعــة وتقــدمي البينــات والــرد عليهــا والقناعــة‬\n     ‫واالعتــراض وتقــدمي الالئحــة االعتراضيــة حتــى اكتســاب احلكــم‬\n     ‫القطعيــة هكــذا قــرروا وقــرر احلاضــر (‪ )......‬موافقتــه علــى ذلــك ‪.‬‬\n     ‫ول ـ ــذا رفعــت اجللســة إلــى يــوم الســبت املوافــق ‪1433/11/27‬ه ـ الســاعة‬\n     ‫التاســعة صباحــا‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/11/13‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق‪1433/11/ 27‬هـ‬\n     ‫حضــر املدعــي أصالــة ووكالــة كمــا حضــر املدعــى عليــه نظــارة حــال‬\n     ‫حضور وقرر (‪ )......‬أن الناظر الســابق كان مضطربا يف تقســيم حصة‬\n     ‫العقيــم أو الــذي تــويف عــن غيــر ولــد فأحيانــا يعيدهــا إلــى أصــل الغلــة‬\n     ‫كمــا فعــل يف (‪ )......‬ومــن قبلهــا مــن العقمــاء حيــث كان يجمــع حصــة‬\n     ‫العقمــاء ويعيــد قســمتها علــى املســتحقني بالتســاوي وحينمــا توفيــت‬\n     ‫(‪ )......‬لــم يفعــل ذلــك وإمنــا أعطــى اســتحقاقها ألختهــا العقيمــة (‪ )......‬ولم‬\n     ‫يعــط بقيــة املســتحقني شــيئا هكــذا قــرر ‪ .‬وبعــرض ذلــك علــى املدعــي‬\n     ‫واملدعــى عليــه قــاال صحيــح مــا ذكــره احلاضــر (‪ )......‬فالناظــر الســابق‬\n     ‫كان مضطربــا يف قســمة حصــة العقيــم ومــن لــم يخلــف أوالدا هكــذا‬\n     ‫قــررا ‪ .‬وبســؤال الطرفــن هــل لديهــم مــا يضيفانــه يف هــذه القضيــة فقــاال‬\n     ‫ليــس لدينــا ســوى مــا قدمنــاه ‪ ،‬والتأمــل القضيــة رفعــت اجللســة إلــى يــوم‬\n     ‫الثالثــاء املوافــق ‪1434/1/6‬ه الســاعة التاســعة والنصــف صباحــا وبــاهلل‬\n\n\n‫‪51‬‬\n\f‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪1433/11/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ‬\n‫ويف متــام الســاعة العاشــرة والربــع صباحـ ًا افتتحــت اجللســة ولــم يحضــر‬\n‫املدعــي أو وكيــل شــرعي عنــه ولــم يتقــدم بعــذر عــن تخلفــه كمــا لــم‬\n‫يحضــر املدعــي عليــه لــذا فقــد شــطب القضيــة للمــرة األولــى حســب‬\n‫التعليمــات حــرر يف الســاعة العاشــرة والربــع بتاريــخ ‪1434/1/6‬هــ‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األربعــاء املوافــق ‪1434/1/14‬ه ـ‬\n‫ويف متــام الســاعة (‪ )9.30‬صباحــا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫كمــا حضــر املدعــي عليــه نظــارة وبســؤال الطرفــن هــل لديهمــا مــا‬\n‫يضيفانــه يف هــذه القضيــة فقــال املدعــي أننــي ســبق أن ذكــرت يف‬\n‫دعــواي إننــي اطلــب إعــادة قســمة الغلــة بــن املســتحقني بالتســاوي وتبــن‬\n‫لــي أن عمــل النظــارة الســابقني هــو إعطــاء حصــة كل مســتحق ألوالده‬\n‫ولــذا فــا مطالبــة لــي فيمــا يخــص ذلــك وإمنــا مطالبتــي هــي فيمــا يخــص‬\n‫حصــة العقيــم بــأن ال تصــرف ألحــد دون أحــد مــن املســتحقني وإمنــا تعــود‬\n‫ألصــل الغلــة هكــذا قــرر وبعــرض ذلــك علــى املدعــي عليــه نظــارة قــال‬\n‫ليــس لــدي ســوى مــا قدمتــه بــأن العقيــم قــد اضطــرب فيهــا النظــار‬\n‫الســابقون ففــي ثلثــن تعطــى حصــة العقيــم ومــن توفــى عــن غيــر ولــد‬\n‫إلخوانــه ويف الثلــث الــذي ينتمــي إليــه املدعــي فــإن الناظــر الســابق كان‬\n‫يعطــي حصــة العقيــم ومــن مــات عــن غيــر ولــد إلخوانــه ثــم بعــد ذلــك‬\n‫إعــادة إلــى أصــل الغلــة ثــم رجــع وأعطــاه إلخــوة املتــويف حســب مــا بينتــه‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫لكــم ســابقا هكــذا قــرر وقــد حضــر املشــرف علــى الناظــر ســجل‬\n     ‫مدنــي رقــم (‪ )......‬الصــك الصــادر مــن هــذه احملكمــة برقــم (‪ )......‬يف‬\n     ‫‪1429/12/18‬ه ـ وقــرر قائــا إننــي اطلــب إدخالــي يف هــذه القضيــة وأنــا‬\n     ‫أطلــب العمــل بإعطــاء حصــة مــن توفــى غيــر ولــد مــن املســتحقني إلخوتــه‬\n     ‫يف كل ثلــث ألنــه ال يوجــد شــرط واقــف يف هــذا الوقــف وإمنــا أكثــر‬\n     ‫عمــل النظــار علــى ذلــك هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وبعــد اإلطــاع علــى صكــوك هــذا الوقــف وألنــه تبــن عــدم‬\n     ‫وجــود شــرط واقــف لــدى نظــار هــذا الوقــف وأن غلــة هــذا الوقــف تقســم‬\n     ‫أثالثــا علــى الوصــف املشــار إليــه بعاليــه وأن حصــة كل مســتحق تنتقــل‬\n     ‫إلــى أوالده وألن الناظــر قــرر أن النظــار الســابقني كانــوا مضطربــن يف‬\n     ‫حصــة مــن تــويف عقيمــا أو عــن غيــر ولــد فأحيانــا كانــوا يقســمونها بــن‬\n     ‫إخوتــه وأحيانــا يعيدونهــا إلــى أصــل الغلــة وألن الراجــح عنــد أهــل العلــم‬\n     ‫أن الوقــف إذا لــم يعثــر لــه علــى شــرط واقــف يرجــع إليــه عنــد االختــاف‬\n     ‫فــإن حصــة مــن توفــى عــن غيــر ولــد تعــود ألصــل الغلــة قــال يف تنقيــح‬\n     ‫احلامديــة املنصــوص عليــه عندنــا يف االســعاف وغيــره أنــه إذا ســكت‬\n     ‫عــن حكــم مــن مــات عــن غيــر ولــد يصــرف نصيبــه مصــرف الغلــة أي‬\n     ‫ينقســم علــى جميــع املســتحقني أ‪.‬ه ـ ينظــر تنقيــح احلامديــة واالســعاف‬\n     ‫يف أحــكام األوقــاف للطرابلســي صحيفــة ‪106‬وقــال يف االســعاف ولــو‬\n     ‫ا كان‬     ‫قــال كلمــا حــدث املــوت علــى احــد منهــم ولــم يتــرك ولــدا أو نسـ َ‬\n     ‫نصيبــه منهــا راجع ـ ًا البطــن الــذي فوقــه ومــات واحــد منهــم ولــم يكــن‬\n     ‫فوقــه احــد أو لــم يذكــر يف ســهم مــن ميــوت عــن غيــر ولــد وال نســل شــيئا‬\n     ‫فيكــون نصيبــه راجعــا الــى أصــل الغلــة وجاريــا مجراهــا أ‪.‬ه ـ لذلــك‬\n     ‫كلــه حكمــت بــأن حصــة مــن مــات عــن غيــر ولــد مــن املســتحقني يف‬\n\n\n‫‪53‬‬\n\f‫كل ثلــث تعــود الــى أصــل الثلــث ويعــاد قســمتها بــن جميــع املســتحقني‬\n‫وبعــرض ذلــك علــى الطرفــن قــرر املدعــي واملدعــي عليــه نظــارة القناعــة‬\n‫وقــرر املشــرف عــدم القناعــة وطلــب رفعــه حملكمــة اإلســتئناف واســتعد‬\n‫بتقــدمي الئحــة اعتراضيــة ومت إفهامــه بالتعليمــات ‪ ،‬حــرر يف الســاعة‬\n‫(‪ )10.00‬صباحـ ًا بتاريــخ ‪1434/1/14‬ه ـ ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n                              ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة بشــرح فضيلة رئيــس احملكمة‬\n‫برقــم يف ‪1434/4/24‬ه علــى خطــاب محكمــة االســتئناف بخطابهــم‬\n‫رقــم يف ‪1434/4/9‬ه ـ مرفقــا بــه القــرار الصــادر مــن دائــرة االحــوال‬\n‫الشــخصية االولــى برقــم يف ‪1434/3/22‬ه ـ املتضمــن وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــه حاكمهــا‬\n‫حيــث جــاء يف الالئحــة االعتراضيــة يف جميــع فقراتهــا مــا يســتدعي‬\n‫النظر الشرعي واملناقشة بحضور اطراف القضية أو اجلواب بالتفصيل‬\n‫ومــن ذلــك مــا ورد يف الفقــرة ثاني ـاً‪ ،‬وكذلــك مــا ذكــره املعتــرض يف‬\n‫الئحتــه يف الفقــرة رابعـ ًا بشــأن جوابــه علــى مــا ذكــره أطــراف القضيــة‬\n‫ومســتنده علــى ذلــك ويتعــن اجــراء الوجــه الشــرعي نحــو ذلــك وإذا‬\n‫ثبــت مــا ذكــره املشــرف علــى الوقــف يف الئحتــه فيلــزم إعــادة النظــر‬\n‫يف احلكــم‪ .‬وبــاهلل التوفيــق أ‪.‬ه ـ وعليــه أجيــب علــى مــا جــاء يف قــرار‬\n‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف بأننــي ســبق أن اطلعــت‬\n‫علــى الالئحــة االعتراضيــة ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت‬\n‫بــه وقــد دونــت ذلــك علــى الالئحــة املرفقــة بــاألوراق ويف ضبــط القضيــة‬\n‫مــع احاطــة أصحــاب الفضيلــة بــأن كل مــا ذكــره املشــرف يف الالئحــة‬\n‫ســبق أن ذكــره يف اجللســات ومتــت مناقشــته قبــل احلكــم ولــم يظهــر لــي‬\n\n\n                                                                                   ‫‪54‬‬\n\f     ‫أن فيمــا ذكــره أثــر علــى احلكــم ولــذا فليــس لــدي ســوى مــا حكمــت‬\n     ‫بــه وأمــرت بإحلاقــه بالصــك وســجله ورفعــه حملكمــة االســتئناف لتقريــر‬\n     ‫مــا تــراه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/4/30‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بشــرح فضيلــة الرئيــس برقــم يف ‪1434/6/6‬ه ـ علــى خطــاب رئيــس‬\n     ‫محكمــة االســتئناف مبنطقــة املكلــف برقــم يف ‪1434/5/29‬ه ـ‬\n     ‫برفقهــا قــرار التصديــق مبوجــب القــرار رقــم ‪1434/5/‬ه ـ وهــذا نصــه‬\n     ‫‪ -:‬احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف‬\n     ‫والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n     ‫خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة رقــم وتاريــخ‬\n     ‫‪1434/5/5‬ه ـ املشــتملة علــى الصــك وتاريــخ ‪1434/1/20‬ه ـ الصــادر‬\n     ‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة واملتضمــن دعــوى ضــد‬\n     ‫بصفتــه ناظــر ًا علــى وقــف يف اســتحقاق مــن الوقــف وبدراســة الصــك‬\n     ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n     ‫احلكــم بعــد اجلــواب األخيــر لفضيلتــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬قاضــي اســتئناف (‪)......‬‬\n     ‫ختــم وتوقيــع قاضــي اســتئناف (‪ )......‬ختــم وتوقيــع رئيــس الدائــرة لــي‬\n     ‫وجهــة نظــر (‪ )......‬ختــم وتوقيــع‪ ،‬ل ـ ــذا جــرى التهميــش مبوجبــه ‪ .‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                           ‫حــرر يف ‪1434/6/14‬ه ـ‬\n\n\n‫‪55‬‬\n\f‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة جــرى منــا االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة رقــم وتاريــخ ‪1434/5/5‬ه ـ املشــتملة علــى الصــك رقــم وتاريــخ‬\n‫‪1434/1/20‬ه ـ الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامة‬\n‫املتضمن دعوى (‪ )......‬ضد (‪ )......‬بصفته ناظر ًا على وقف يف استحقاق‬\n‫مــن الوقــف وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم بعــد اجلــواب األخيــر لفضيلتــه واهلل‬\n          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":30,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2d973159b171c64cb8d482ad8b7da838f52b5354c50147bad7c4451e66bec724","normalized_text_hash":"10161daa1537339ebf1ef60d2b1ae214269964c0173e23314f875e4e7bd4a549","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p30-3418295"},{"id":"0712707e-a572-5824-9388-88740a02d105","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -إفراغ مسجد -إثبات وقفيته -رفض املدعى عليه ،حجته شرائه املزرعة باملسجد وأنه مسجد عائلي -ثبوت قيام املالك السابق بإيقاف املسجد قبل شراء املدعى عليه املزرعة -إقرار املدعى عليه أن املسجد كان قائم ا قبل شرائه املزرعة -الوقف ال يباع وال يوهب -احلكم بثبوت وقفية املسجد -إفهام املدعى عليه الرجوع على من باعه إذا كان غره.","document_number":"32297345","case_number":"32486362","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/11/5","year":"1434","subject":"وقف -إفراغ مسجد -إثبات وقفيته -رفض املدعى عليه ،حجته شرائه املزرعة باملسجد وأنه مسجد عائلي -ثبوت قيام املالك السابق بإيقاف املسجد قبل شراء املدعى عليه املزرعة -إقرار املدعى عليه أن املسجد كان قائم ا قبل شرائه املزرعة -الوقف ال يباع وال يوهب -احلكم بثبوت وقفية املسجد -إفهام املدعى عليه الرجوع على من باعه إذا كان غره.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1432/11/5 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪32297345 :‬‬\n                        ‫َر ْق ُم الدعوى‪32486362 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 348289‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n     ‫وقــف ‪ -‬إفــراغ مســجد ‪ -‬إثبــات وقفيتــه ‪ -‬رفــض املدعــى عليــه ‪ ،‬حجتــه‬\n     ‫شــرائه املزرعــة باملســجد وأنــه مســجد عائلــي ‪ -‬ثبــوت قيــام املالــك‬\n     ‫الســابق بإيقــاف املســجد قبــل شــراء املدعــى عليــه املزرعــة ‪ -‬إقــرار‬\n     ‫املدعــى عليــه أن املســجد كان قائم ـ ًا قبــل شــرائه املزرعــة ‪ -‬الوقــف ال‬\n     ‫يبــاع وال يوهــب ‪ -‬احلكــم بثبــوت وقفيــة املســجد ‪ -‬إفهــام املدعــى عليــه‬\n                                        ‫الرجــوع علــى مــن باعــه إذا كان غــره‪.‬‬\n\n\n\n\n     ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (ال يبــاع أصلهــا وال توهــب وال تــورث)‬\n                                                                      ‫متفــق عليــه‪.‬‬\n     ‫‪ -2‬قــال القرطبــي رحمــه اهلل يف املفهــم (ال خــاف بــن األئمــة يف‬\n                                     ‫حتبيــس املســاجد والقناطــر ) ‪.600/4‬‬\n     ‫‪ -3‬جــاء يف كشــاف القنــاع (يــزول ملــك الواقــف عــن العــن املوقوفــة‬\n     ‫مبجــرد الوقــف وينتقــل امللــك فيهــا إلــى اهلل تعالــى) ‪.104/10-34/10‬‬\n     ‫‪ -4‬جــاء يف كشــاف القنــاع‪« 104/10 :‬الوقــف عقــد الزم ‪ ..‬ويحــرم وال‬\n                                       ‫يصــح بيعــه وال هبتــه وال املناقلــة بــه»‪.‬‬\n     ‫‪ -5‬جــاء يف كشــاف القنــاع‪ « :‬ويلــزم الوقــف مبجــرد القــول دون حكــم‬\n                                                                 ‫حاكــم» ‪.104/10‬‬\n\n\n\n‫‪57‬‬\n\f‫أقامــت (‪ )000‬دعــوى علــى رجــل قــام بهــدم جــزء مــن مســجد يف مزرعتــه‬\n‫فتعطلــت الصلــوات فيــه وطالبــت املدعــى عليــه بإعــادة بنــاء املســجد‬\n‫وإزالــة العوائــق التــي بناهــا وإفــراغ املســجد وملحقاتــه واألرض املقــام‬\n‫عليــه لصالــح وزارة الشــؤون اإلســامية‪ ،‬بعــرض الدعــوى علــى املدعــى‬\n‫عليــه أفــاد بــأن املســجد املذكــور هــو مســجد عائلــي وداخــل مزرعتــه‬\n‫وأنــه اشــترى املزرعــة ومــن ضمنهــا املســجد املذكــور وأنــه قــام ببعــض‬\n‫التعديــات اخلاصــة يف مزرعتــه أدت إلــى إزالــة بعــض جــدران املســجد‬\n‫ودورات امليــاه فتعطــل املســجد ورفــض إفــراغ املســجد وملحقاتــه لــوزارة‬\n‫الشــؤون اإلســامية ثــم ســألته احملكمــة هــل كان املســجد قائمـ ًا عنــد‬\n‫شــراءه للمزرعــة أجــاب قائــا نعــم وأن الــذي بنــاه املالــك الســابق (‪).....‬‬\n‫فجــرى اطــاع احملكمــة علــى إقــرار املالــك الســابق للتنازل عن املســجد‬\n‫وتســليمه لألوقــاف كمــا طلبــت احملكمــة أســاس صــك العقــار فرفــض‬\n‫املدعــى عليــه تســليمه ثــم ســألت احملكمــة وزارة الشــؤون اإلســامية‬\n‫عــن حــدود املســجد وأطوالــه فحددتهــا الــوزارة ثــم رجــع املدعــى عليــه‬\n‫وقــال إن ســبب إزالتــه لبعــض أجــزاء املســجد وتعطيلــه تصرفــات بعــض‬\n‫مريــدي املســجد التــي أســاءت لــه حيــث أصبحــوا يكشــفون منزلــه‬\n‫وإلقــرار املدعــى عليــه لــدى احملكمــة بــأن املســجد املذكــور كان‬\n‫قائــم قبــل شــرائه للمزرعــة تصلــى فيــه الصلــوات اخلمــس وأن الــذي بنــاه‬\n‫املالــك الســابق الــذي أقــر بوقفيتــه وألنــه يــزول ملــك الواقــف عــن العــن‬\n‫املوقوفــة وألنــه ال يجــوز بيــع األوقــاف وألن النظــام جعــل لــوزارة الشــؤون‬\n‫اإلســامية احلــق يف اإلشــراف علــى املســاجد فقــد ثبــت لــدى احملكمــة‬\n\n                                                                                     ‫‪58‬‬\n\f     ‫وقفيــة املســجد املذكــور يف الدعــوى وملحقاتــه واألرض املقــام عليهــا‬\n     ‫باحلــدود واألطــوال املشــار إليهــا بالدعــوى‪ ،‬وأفهمــت احملكمــة املدعــى‬\n     ‫عليــه بــأن لــه الرجــوع علــى مــن باعــه إن كان قــد غــره‪ ،‬اعتــرض املدعى‬\n                                                      ‫عليــه‪ ،‬وصــدق احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n     ‫ـاء‬\n     ‫وبعــد لــدي أنــا (‪ )0000‬رئيــس محاكــم منطقــة جنــران املســاعد وبنـ ً‬\n     ‫علــى املعاملــة احملالــة لنــا برقــم ‪ 1622‬يف ‪1431/9/5‬ه ـ واحملدثــة بقيــد‬\n     ‫احملكمــة رقــم ‪ 321357605‬وتاريــخ ‪1432/10/29‬ه واحملالــة برقــم‬\n     ‫‪ 32486362‬يف ‪1432/10/29‬ه ـ حضــر (‪ )000‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ )000‬منــدوب فــرع وزارة الشــؤون‬\n     ‫اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران مبوجــب‬\n     ‫خطابهــم رقــم (‪ )000‬يف ‪1431/6/8‬ه ـ وادعــى علــى احلاضر معه (‪)000‬‬\n     ‫ا يف دعــواه‬ ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )000‬قائ ـ ً‬\n     ‫لقــد ســبق وأن قــام املواطــن ببنــاء مســجد (‪ )000‬علــى جــزء مــن مزرعتــه‬\n     ‫وتنــازل عــن املســجد وملحقاتــه وحرمــه ودورات امليــاه التابعــة لــه لوجــه‬\n     ‫اهلل تعالــى وذلــك يف ‪1417/9/1‬ه ـ حســب إقــراره املرفــق باملعاملــة ولــم‬\n     ‫يتــم إفــراغ املســجد يف حينــه ثــم مت بيــع األرض عــدة مــرات إلى أن وصلت‬\n     ‫إلــى املدعــى عليــه احلاضــر ومنــذ ذلــك التاريــخ وحتــى اآلن واملســجد‬\n     ‫باســتالم فــرع وزارة الشــؤون اإلســامية واالوقــاف والدعــوة واإلرشــاد‬\n     ‫مبنطقــة جنــران وتقــام فيــه الصلــوات اخلمــس وفيــه مــؤذن وإمــام بشــكل‬\n     ‫رســمي ثــم قــام املدعــى عليــه باالعتــداء علــى املســجد وذلــك ببنــاء ســور‬\n\n‫‪59‬‬\n\f‫يحجــز املســجد عــن الشــارع العــام كمــا قــام أخيــر ًا بإقفــال دورات امليــاه‬\n‫وكذلــك إقفــال أحــد أبــواب املســجد وقــام كذلــك بإزالــة اجلــدار‬\n‫اجلنوبــي حلــرم املســجد وإزالــة خــزان امليــاه وإزالــة لوحــة املســجد أطلــب‬\n‫إفــراغ املســجد وملحقاتــه واألرض املقــام عليهــا لصالــح فــرع وزارة‬\n‫الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة وذلــك‬\n‫مبســاحة إجماليــة قدرهــا (‪232‬م‪ )2‬مائتــان واثنــان وثالثــون متــر ًا مربعـ ًا‬\n‫كمــا أطلــب بإزالــة اجلــدار الــذي أقامــه املدعــى عليــه بــن املســجد‬\n‫والشــارع العــام وكذلــك إعــادة بنــاء اجلــدار الــذي أزالــه املدعــى عليــه‬\n‫مــن اجلهــة اجلنوبيــة وكذلــك إعــادة خــزان امليــاه الــذي أزالــه املدعــى عليه‬\n‫وكل ذلــك علــى حســابه هــذه دعــواي وبســؤال املدعــى عليــه أجــاب‬\n‫ا لقــد قمــت بشــراء املزرعــة مــن املواطــن (‪ )000‬يف عــام ‪1424‬ه ـ‬          ‫قائ ـ ً‬\n‫وقــد ســألته عــن املســجد املوجــود فيهــا فقــال لــي إنــه مســجد عائلــي وهــو‬\n‫داخــل املزرعــة ويف حاللــك وقــد قمــت بتلبيــس حجــر لســور املزرعــة ومــن‬\n‫ضمنهــا املســجد وأمــا اجلــدار اجلنوبــي فأنــا الــذي أقمتــه منــذ فتــرة ثــم‬\n‫أزلتــه وأغلقــت دورات امليــاه والبــاب الــذي يوصــل إليهــا كمــا قمــت‬\n‫بإزالــة خــزان امليــاه وذلــك للضــرر الــذي حلقنــي بســببها حيــث يقــوم‬\n‫األوالد باإلطــال علــى املزرعــة ومحارمــي فيهــا مــن خــال نوافــذ دورات‬\n‫امليــاه وكذلــك مــن خــال الصعــود للخــزان وأمــا لوحــة املســجد فلــم أقــم‬\n‫بإزالتها وأرفض طلب فرع وزارة الشــؤون اإلســامية واألوقاف والدعوة‬\n‫واإلرشــاد مبنطقــة جنــران إفــراغ املســجد وملحقاتــه هكــذا أجــاب‬\n‫فجــرى ســؤال املدعــى عليــه هــل كان املســجد قائم ـ ًا عنــد شــرائه‬\n‫ا نعــم لقــد كان املســجد قائم ـ ًا تصلــى فيــه‬        ‫للمزرعــة فأجــاب قائ ـ ً‬\n‫الصلــوات اخلمــس واليــزال وأخبرنــي البائــع أن الــذي بنــاه هــو ولــم يقــم‬\n\n\n                                                                                         ‫‪60‬‬\n\f     ‫ا وليــس فيــه ذكــر‬   ‫أحــد بإفــراغ املســجد وقــد اشــتريت الصــك كام ـ ً‬\n     ‫للمســجد هكــذا أجــاب فجــرى االطــاع علــى أوراق املعاملــة ومنهــا‬\n     ‫صــورة إقــرار (‪ )000‬املرفــق باملعاملــة وهــذا نصــه (احلمــد هلل رب العاملــن‬\n     ‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد هــذا إقــرار منــي بالتنــازل‬\n     ‫عــن املســجد الــذي أقمتــه علــى جــزء مــن أرضــي بــ(‪ )000‬هــو وأرضــه‬\n     ‫وحرمــه ودورات امليــاه التابعــة لــه هلل تعالــى وســلمته إدارة األوقــاف‬\n     ‫لتشــرف عليــه وتقــوم بواجباتــه هــذا واهلل مــن وراء القصــد حــرر يف‬\n     ‫‪1417/9/1‬ه ـ املقــر (‪( )000‬وتوقيعــه ) أ‪.‬ه كمــا جــرى اإلطــاع علــى‬\n     ‫خطــاب مديــر فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة‬\n     ‫واإلرشــاد مبنطقــة جنــران رقــم ‪ 11263‬يف ‪1432/3/13‬ه ـ املتضمــن أن‬\n     ‫التعليمــات تنــص علــى أن حــرم املســجد إذا كان احمليــط للمســجد‬\n     ‫مبنــى أو مواقــف أو جــار هــو متريــن وبطلــب أســاس الصــك مــن املدعــى‬\n     ‫عليــه لالطــاع عليــه قــال صــورة الصــك موجــودة يف املعاملــة وأما أســاس‬\n     ‫الصــك فلــن أســلمه ألحــد هكــذا أجــاب كمــا جــرى ســؤال منــدوب‬\n     ‫فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة‬\n     ‫جنــران عــن حــدود املســجد وأطوالــه فقــال ســأحضر بياناتهــا يف اجللســة‬\n     ‫القادمــة ويف جلســة أخــرى حضــر الطرفــان وبســؤال منــدوب فــرع وزارة‬\n     ‫الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران عــن‬\n     ‫ا إن حــدود وأطــوال املســجد‬        ‫حــدود وأطــوال املســجد أجــاب قائ ـ ً‬\n     ‫كالتالــي مــن الشــمال باقــي الصــك الــذي ميلكــه املدعــى عليــه رقــم‬\n     ‫‪ 3/35‬بطــول خمســة عشــر متــر ًا وســبعني ســنتيمتر ًا ومــن اجلنــوب باقــي‬\n     ‫الصــك الــذي ميلكــه املدعــى عليــه رقــم ‪ 3/35‬بطــول خمســة عشــر متــر ًا‬\n     ‫وخمســة وتســعني ســنتيمتر ًا ومــن الشــرق شــارع اســفلت بطــول يبــدأ مــن‬\n\n\n‫‪61‬‬\n\f‫الشــمال خمســة أمتــار وســتني ســنتيمتر ًا ثــم ينكســر جنــوب غــرب‬\n‫بطــول ســبعة أمتــار وأربعــة عشــر ســنتيمتر ًا ثــم ينكســر جنــوب غــرب‬\n‫بطــول متــر وتســعني ســنتيمتر ًا بطــول إجمالــي للشــرق أربعــة عشــر متــر ًا‬\n‫وأربعــة وســتون ســنتيمتر ًا ومــن الغــرب باقــي الصــك الــذي ميلكــه رقــم‬\n‫‪ 35/3‬بطــول ثالثــة عشــر متــر ًا وتســعة ســنتيمتر مبســاحة إجماليــة‬\n‫قدرهــا ‪232‬م‪ 2‬مائتــان واثنــان وثالثــون متــر ًا مربع ـ ًا هكــذا أجــاب‬\n‫وجــرى ســؤال املدعــى عليــه مــر ًة أخــرى عــن املســجد مــن الــذي بنــاه وهــل‬\n‫ا إن الــذي‬   ‫كان قائم ـ ًا يصلــى فيــه عنــد شــرائه للمزرعــة فأجــاب قائ ـ ً‬\n‫بنــاه هــو (‪ )000‬حســب مــا ذكــر لــي ابــن (‪ )000‬الــذي اشــتريت منــه‬\n‫املزرعــة وقــد اشــتريتها واملســجد قائــم تصلــى فيــه الصلــوات اخلمــس‬\n‫واليــزال وســيبقى كذلــك علم ـ ًا أن اجلــدار الــذي يفصــل املســجد عــن‬\n‫الشــارع موجــود قبــل شــرائي للمزرعــة ووزارة الشــؤون اإلســامية لــم‬\n‫تقــم بإضافــة أي شــيء للمســجد ولــم تتصــرف فيــه طيلــة هــذه املــدة ألنهــا‬\n‫ال متلكــه هكــذا أجــاب ثــم أبــرز ورقـ ًة هــذا نصهــا (بســم اهلل الرحمــن‬\n‫الرحيــم صاحــب الفضيلــة رئيــس احملكمــة العامــة املســاعد حفظــه اهلل‬\n‫الســام عليكــم ورحمــة اهلل وبركاتــه أقــدم إلتماســي هــذا أمــام‬\n‫ا إحقــاق احلــق مفيــد ًا فضيلتكــم بــأن لي مزرعـ ًة خاصة‬      ‫فضيلتكــم آمـ ً‬\n‫أســكن فيهــا وفيهــا مســجد داخــل صكــي الشــرعي وجــزء مــن‬\n‫ـزء مــن منزلــي وقــد فتحــت لــه بــاب مــن‬\n                                           ‫أمالكــي وهــذا املســجد يعتبــر جـ ً‬\n‫اخلــارج ألجــل يصلــي فيــه مــن يرغــب فضيلــة الرئيــس لقــد أخــذ بعــض‬\n‫مريــدي املســجد إســاءة اســتعمال بعــض مرافــق املســجد حتــى أصبــح‬\n‫يكشــف علــى منزلــي لهــذا قمــت بهــدم العــازل لــدورة امليــاه مــن حــوش‬\n‫املســجد وذلــك بهــدف ســتر بيتــي حتــى ال يســتطيع أحــد أن يكشــف‬\n\n\n                                                                                      ‫‪62‬‬\n\f     ‫بيتــي مــن جهــة دورة امليــاه فضيلــة الرئيــس فوجئــت باســتدعائي مــن قبــل‬\n     ‫الشــرطة وإيداعــي الســجن بحجــة أن هنــاك قضيــة ضــدي مــن قبــل هيئــة‬\n     ‫التحقيــق واالدعــاء العــام فضيلــة الرئيــس لــم أرتكــب أي جــرم أســجن‬\n     ‫عليــه وقــد تصرفــت يف جــزء بســيط مــن ملكــي وإذا كانــت وزارة‬\n     ‫الشــؤون اإلســامية ترغــب أن تنــزع جــزء مــن ملكــي فــا يحــق لهــا ذلــك‬\n     ‫إال مبوجــب نظــام نــزع امللكيــة املبلــغ بتعميــم صاحــب الســمو امللكــي‬\n     ‫رئيــس ديــوان رئاســة مجلــس الــوزراء البرقــي رقــم ‪/8‬ب‪ 12662/‬تاريــخ‬\n     ‫‪1424/3/17‬ه ـ املصــادر عليــه باملرســوم امللكــي م‪ 15/‬تاريــخ‬\n     ‫‪1424/3/11‬ه ـ والتــي تنــص مادتهــا األولــى علــى أنــه يجــوز للــوزارات‬\n     ‫واملصالــح احلكوميــة وغيرهــا مــن األجهــزة ذوات الشــخصية املعنويــة‬\n     ‫العامــة نــزع ملكيــة العقــار للمنفعــة العامــة لقــاء تعويــض عــادل بعــد‬\n     ‫التحقــق مــن عــدم توفــر األراضــي والعقــارات احلكوميــة التــي تفــي‬\n     ‫بحاجــة املشــروع وال يجــوز نــزع ملكيــة عقــار إال لتنفيــذ مشــروع معتمــد‬\n     ‫يف امليزانيــة صاحــب الفضيلــة أوالً‪ :‬إن الظلــم ظلمــات حرمــه اهلل علــى‬\n     ‫نفســه وجعلــه بــن عبــاده محرمـ ًا أرجــو إطــاق ســراحي بالكفالــة حتــى‬\n     ‫يبــت يف قضيتــي شــرع ًا ثاني ـاً‪ :‬إلــزام اجلهــة املدعيــة بتعويضــي تعويض ـ ًا‬\n     ‫عــاد ًال فيمــا يســتقطع مــن ملكــي أو إعطائــي التصــرف يف ملكــي دون‬\n     ‫اعتــراض هــذا واهلل يحفظكــم مقدمــه) أ‪.‬ه ـ ثــم جــرى ســؤال الطرفــن‬\n     ‫هــل ألحدهمــا مــا يضيفــه فأجــاب كل واحــد منهمــا قائــا ليــس لــدي‬\n     ‫ســوى مــا ذكــرت هكــذا قــررا ورفعــت اجللســة حلضــور وقــت الصــاة‬\n     ‫ويف جلســة أخــرى حضــر الطرفــان وجــرى االطــاع علــى خطــاب رئيــس‬\n     ‫كتابــة عــدل جنــران املكلــف رقــم ‪ 2865‬يف ‪1432/10/30‬هـ املتضمن‬\n     ‫أن الصــك رقــم ‪ 3/35‬ســاري املفعــول وال يوجــد عليــه مالحظــة حتــى‬\n\n\n‫‪63‬‬\n\f‫تاريخــه كمــا جــرى االطــاع علــى صــورة ســجل الصــك املشــار إليــه‬\n‫املرفقــة بخطــاب رئيــس كتابــة عــدل جنــران املكلــف املشــار إليــه‬\n‫واملتضمنــة انتقــال ملكيــة الصــك للمدعــى عليــه كمــا جــرى االطــاع‬\n‫علــى أســاس إقــرار الواقــف فوجدتــه مطابق ـ ًا لصورتــه املــدون نصهــا‬\n‫ســابق ًا ثــم جــرى ســؤال الطرفــن هــل لــدى أحدهمــا مــا يضيفــه فأجــاب‬\n‫ا ليــس لــدي ســوى مــا ذكــرت هكــذا‬        ‫كل واحــد منهمــا مبفــرده قائـ ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n                                                                       ‫قــررا فبنـ ً‬\n‫يف مجلــس احلكــم بــأن املســجد محــل الدعــوى كان قائمـ ًا قبــل شــرائه‬\n‫للمزرعــة تصلــى فيــه الصلــوات اخلمــس والزال كذلــك وأن الــذي بنــاه‬\n‫هــو (‪ )000‬وملــا جــاء يف إقــرار الواقــف وملــا تقــرر شــرع ًا مــن اســتحباب‬\n‫بنــاء املســاجد ووقفهــا قــال القرطبــي رحمــه اهلل يف املفهــم (ال خــاف‬\n‫بــن األئمــة يف حتبيــس املســاجد والقناطــر )‪ 600/4‬ولعــدم جــواز بيــع‬\n‫األوقــاف لقولــه صلــى اهلل عليــه وســلم (ال يبــاع أصلهــا وال توهــب وال‬\n‫تــورث) متفــق عليــه وجــاء يف كشــاف القنــاع (يــزول ملــك الواقــف عــن‬\n‫العــن املوقوفــة مبجــرد الوقــف وينتقــل امللــك فيهــا إلــى اهلل تعالــى)‬\n‫‪ 34/10‬وجــاء يف كشــاف القنــاع (الوقــف عقــد الزم ‪ ...‬ويحــرم وال يصح‬\n‫بيعــه وال هبتــه وال املناقلــة بــه) ‪ 104/10‬وجــاء يف كشــاف القنــاع) ويلزم‬\n‫الوقــف مبجــرد القــول بــدون حكــم حاكــم) ‪ 104/10‬وألن النظــام قــد‬\n‫جعــل لــوزارة الشــؤون اإلســامية حــق اإلشــراف علــى املســاجد وجلميــع‬\n‫مــا تقــدم فقــد حكمــت بثبــوت وقفيــة املســجد املذكــور يف الدعــوى‬\n‫وملحقاتــه واألرض املقــام عليهــا باحلــدود واألطــوال واملســاحة املشــار‬\n‫إليهــا يف الدعــوى تشــرف عليــه وزارة الشــؤون اإلســامية واألوقــاف‬\n‫والدعــوة واإلرشــاد وأفهمــت املدعــى عليــه بــأن لــه الرجــوع علــى مــن باعه‬\n\n\n                                                                                       ‫‪64‬‬\n\f     ‫إن كان قــد غــره وبعــرض احلكــم علــى الطرفــن قــرر منــدوب فــرع‬\n     ‫وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد مبنطقــة جنــران‬\n     ‫القناعــة وقــرر املدعــى عليــه االعتــراض وتقــدمي الئحــة اعتراضيــة‬\n     ‫فأجيــب لطلبــه وأفهــم باملراجعــة غــد ًا الثالثــاء الســتالم نســخة مــن‬\n     ‫احلكــم وأن مــدة االعتــراض هــي ثالثــون يوم ـ ًا مــن تاريــخ اإلســتالم‬\n     ‫وبعدهــا يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة ففهــم‬\n     ‫ذلــك وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                  ‫‪1432/11/5‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n     ‫وبرفــع القضيــة حملكمــة االســتئناف مبنطقــة عســير عــادت بقــرار‬\n     ‫املالحظــة الصــادر دائــرة األحــوال الشــخصية رقــم ‪ 3398428‬وتاريــخ‬\n     ‫‪1433/02/23‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n     ‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أوالً‪ :‬لــم جنــد‬\n     ‫أن فضيلتــه اســتلحق الواقــف (‪ )000‬وأخــذ إقــراره بالضبــط علم ـ ًا بــأن‬\n     ‫إجابــة املدعــى عليــه غيــر مالقيــة لدعــوى املدعــي حيث لم يســأل املدعى‬\n     ‫عليــه عــن صحــة احلــدود واألطــوال واملســاحة املذكــورة بدعــوى منــدوب‬\n     ‫األوقــاف ثاني ـ ًا تطبــق حــدود وأطــوال ومســاحة املســجد وملحقاتــه مــن‬\n     ‫قبــل البلديــة علــى الطبيعــة حتــى ال يحصــل اختــاف عــن إفــراغ املســجد‬\n     ‫ثالث ـ ًا لــم يتطــرق فضيلتــه يف حكمــه بإفــراغ املســجد بعــد أن أثبــت‬\n     ‫وقفيتــه حســب دعــوى منــدوب األوقــاف فلمالحظــة مــا ذكــر وإحلــاق‬\n     ‫مــا يســتجد بالضبــط وصورتــه والصــك وســجله واهلل املوفــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف (‪ )000‬ختمــه‬\n     ‫وتوقيعــه قاضــي اســتئناف (‪ )000‬ختمــه وتوقيعــه رئيــس الدائــرة (‪)000‬‬\n\n\n‫‪65‬‬\n\f‫(ختمــه وتوقيعــه ) أ ‪ .‬ه ـ وعليــه فقــد حضــر (‪ )000‬ســعودي اجلنســية‬\n‫مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪ )000‬وبســؤاله عمــا لديــه بشــأن‬\n‫ا إننــي كنــت أملــك املزرعــة‬    ‫وقفــه للمســجد مــدار الدعــوى قــرر قائ ـ ً‬\n‫املذكــورة يف دعــوى األوقــاف وقــد قمــت ببنــاء املســجد املذكــور وقفـ ًا‬\n‫هلل تعالــى مبنافعــه وحرمــه بواقــع متريــن مــن كل جهــة وعنــد بيعــي‬\n‫ا يف‬  ‫للمزرعــة علــى املدعــو (‪ )000‬اشــترطت عليــه أن املســجد ليــس داخـ ً‬\n‫املبيــع وأنــه وقــف هلل تعالــى مــع جميــع ملحقاتــه وحرمــه علمـ ًا بأننــي قــد‬\n‫ســلمت املســجد لألوقــاف قبــل بيعــي للمزرعــة هكــذا قــرر لــذا جــرى‬\n‫إثباتــه كمــا جــرى منــي مخاطبــة أمانــة منطقــة جنــران لتطبيــق حــدود‬\n‫وأطــوال ومســاحة املســجد وملحقاتــه واملصادقــة علــى الكروكــي‬\n‫وذلــك بخطاباتنــا رقــم ‪ 33468818‬يف ‪1433/03/12‬ه ـ ورقــم‬\n‫‪ 33817271‬يف ‪1433/05/04‬ه ـ ورقــم ‪ 33993693‬يف ‪1433/5/25‬ه ـ‬\n‫ورقــم ‪ 331195109‬يف ‪1433/06/24‬ه ـ ورقــم ‪ 331380128‬يف‬\n‫‪1433/07/23‬ه ـ ورقــم ‪ 331708163‬يف ‪1433/09/16‬ه ـ إال أننــا لــم‬\n‫جنــد جتاوب ـ ًا مــن قبــل األمانــة مبــا مت طلبــه وملــا جــاء يف خطــاب أمــن‬\n‫منطقــة جنــران رقــم ‪ 13009‬يف ‪1433/09/19‬ه ـ مــن أنــه طاملــا أن‬\n‫الكروكــي أعــد مــن قبــل مكتــب هندســي متخصــص وقُ ـ ِّـدم مــن قبــل‬\n‫جهــة حكوميــة فإنــه ميكــن األخــذ بــه دون احلاجــة إلــى تطبيقــه ولعــدم‬\n‫جتــاوب املدعــى عليــه ومماطلتــه وإلحلاقــه الضــرر الظاهــر باملســجد‬\n‫ومنافعــه ممــا أدى إلــى تعطيــل منافــع املســجد وهجــران املصلــن لــه‬\n‫ولوقوفنــا علــى املســجد وحلضــور الواقــف وإقــراره بوقفيتــه للمســجد‬\n‫ولــكل مــا ذكــر فلــم يظهــر لــي ســوى مــا حكمــت بــه ســابق ًا مــن إثبــات‬\n‫وقفيــة املســجد املذكــور يف الدعــوى وإفــراغ اجلــزء املقــام عليــه حــال‬\n\n\n                                                                                       ‫‪66‬‬\n\f     ‫تصديــق احلكــم مــن االســتئناف وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1433/10/09‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n     ‫وبعــد وقــد عــادت املعاملــة بكتــاب فضيلــة رئيــس محكمــة االســتئناف‬\n     ‫مبنطقــة عســير رقــم ‪ 33/1906843‬وتاريــخ ‪1434/02/06‬ه ـ وشــفعها‬\n     ‫قــرار التصديــق الصــادر مــن دائــرة األحــوال الشــخصية مبحكمــة‬\n     ‫االســتئناف مبنطقــة عســير برقــم ‪ 348289‬يف ‪1434/1/11‬ه ـ املظهــر‬\n     ‫مبوجبــه علــى صــك احلكــم ونــص احلاجــة منــه (وحيــث ســبق دراســة‬\n     ‫الصــك وصــورة ضبطــه والالئحة االعتراضيــة وأوراق املعاملة وباالطالع‬\n     ‫ـاء علــى‬‫علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنـ ً‬\n     ‫قــرار الدائــرة رقــم وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى‬\n     ‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n     ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ) أ‬\n     ‫‪ .‬ه ـ ومبوجبــه أمــرت بالتهميــش بذلــك علــى الصــك وســجله وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/02/13‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n     ‫بتدقيــق قضايــا األحــوال الشــخصية واألوقــاف والوصايــا والقصــار‬\n     ‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة لهــذه احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة الشــيخ‬\n     ‫(‪ ).....‬برقــم وتاريــخ ‪1433/10/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n     ‫فضيلتــه واملســجل برقــم (‪ ).....‬وتاريــخ ‪1432/11/5‬ه ـ واخلاصــة بدعــوى‬\n\n\n‫‪67‬‬\n\f‫فــرع وزارة الشــؤون اإلســامية واألوقــاف والدعــوة واإلرشــاد ضــد بشــأن‬\n‫إفــراغ مســجد علــى الصفــة املوضحــة بالصــك واملتضمن حكــم فضيلته‬\n‫مبــا هــو مــدون بباطنــه وحيــث ســبق دراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫ـاء علــى قــرار الدائــرة رقــم‬\n                              ‫فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنـ ً‬\n‫وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n‫دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n‫وبعــد وقــد عــادت املعاملــة بكتــاب فضيلــة رئيــس محكمــة االســتئناف‬\n‫مبنطقــة عســير رقــم ‪ 331906843‬وتاريــخ ‪1434/2/6‬ه ـ وشــفعها قــرار‬\n‫التصديــق الصــادر مــن دائــرة األحــوال الشــخصية مبحكمــة االســتئناف‬\n‫مبنطقــة عســير برقــم ‪ 348289‬يف ‪1434/1/11‬ه ـ املظهــر مبوجبــه‬\n‫علــى صــك احلكــم ونــص احلاجــة منــه (وحيــث ســبق دراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط وصــك احلكــم بنــاء علــى قــرار‬\n‫الدائــرة رقــم ‪ 3398428‬وتاريــخ ‪1433/2/23‬ه ـ تقــررت املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه)‬\n‫أ‪.‬ه ـ ومبوجبــه أمــرت بالتهميــش علــى الصــك وســجله وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/13‬هــ‪.‬‬\n\n\n                                                       